  );

  const rows = await query(
    `SELECT te.*, c.company_name AS customer_name
     FROM time_entries te
     LEFT JOIN clients c ON c.id = te.customer_id
     WHERE ${where}
     ORDER BY te.entry_date DESC, te.created_at DESC
     LIMIT $${idx} OFFSET $${idx + 1}`,
