/**
 * Multi-Entity / Multi-Company Service
 * Manage companies and user-company associations.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface Company {
  id: string;
  name: string;
  tradingName: string | null;
  registrationNumber: string | null;
  vatNumber: string | null;
  taxNumber: string | null;
  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  province: string | null;
  postalCode: string | null;
  country: string;
  phone: string | null;
  email: string | null;
  website: string | null;
  logoUrl: string | null;
  bankName: string | null;
  bankAccountNumber: string | null;
  bankBranchCode: string | null;
  bankAccountType: string;
  financialYearStart: number;
  vatPeriod: string;
  defaultCurrency: string;
  isActive: boolean;
  createdAt: string;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

// ── Company CRUD ─────────────────────────────────────────────────────────────

export async function listCompanies(): Promise<Company[]> {
  const rows = (await sql`SELECT * FROM companies WHERE is_active = true ORDER BY name`) as Row[];
  return rows.map(mapCompany);
}

export async function getCompany(id: string): Promise<Company | null> {
  const rows = (await sql`SELECT * FROM companies WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapCompany(rows[0]) : null;
}

export async function createCompany(input: {
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  email?: string;
  phone?: string;
}, userId: string): Promise<Company> {
  const rows = (await sql`
    INSERT INTO companies (name, trading_name, registration_number, vat_number, tax_number, email, phone)
    VALUES (${input.name}, ${input.tradingName || null}, ${input.registrationNumber || null},
            ${input.vatNumber || null}, ${input.taxNumber || null}, ${input.email || null}, ${input.phone || null})
    RETURNING *
  `) as Row[];

  // Auto-assign creator as owner
  await sql`
    INSERT INTO company_users (company_id, user_id, role, is_default)
    VALUES (${rows[0].id}::UUID, ${userId}, 'owner', false)
  `;

  log.info('Company created', { id: rows[0].id, name: input.name }, 'accounting');
  return mapCompany(rows[0]);
}

export async function updateCompany(id: string, input: Partial<{
  name: string;
  tradingName: string;
  registrationNumber: string;
  vatNumber: string;
  taxNumber: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  province: string;
  postalCode: string;
  phone: string;
  email: string;
  website: string;
  bankName: string;
  bankAccountNumber: string;
  bankBranchCode: string;
  financialYearStart: number;
  vatPeriod: string;
}>): Promise<Company> {
  const rows = (await sql`
    UPDATE companies SET
      name = COALESCE(${input.name ?? null}, name),
      trading_name = COALESCE(${input.tradingName ?? null}, trading_name),
      registration_number = COALESCE(${input.registrationNumber ?? null}, registration_number),
      vat_number = COALESCE(${input.vatNumber ?? null}, vat_number),
      tax_number = COALESCE(${input.taxNumber ?? null}, tax_number),
      address_line1 = COALESCE(${input.addressLine1 ?? null}, address_line1),
      address_line2 = COALESCE(${input.addressLine2 ?? null}, address_line2),
      city = COALESCE(${input.city ?? null}, city),
      province = COALESCE(${input.province ?? null}, province),
      postal_code = COALESCE(${input.postalCode ?? null}, postal_code),
      phone = COALESCE(${input.phone ?? null}, phone),
      email = COALESCE(${input.email ?? null}, email),
      website = COALESCE(${input.website ?? null}, website),
      bank_name = COALESCE(${input.bankName ?? null}, bank_name),
      bank_account_number = COALESCE(${input.bankAccountNumber ?? null}, bank_account_number),
      bank_branch_code = COALESCE(${input.bankBranchCode ?? null}, bank_branch_code),
      financial_year_start = COALESCE(${input.financialYearStart ?? null}, financial_year_start),
      vat_period = COALESCE(${input.vatPeriod ?? null}, vat_period),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId} AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({
    companyId: r.company_id,
    companyName: r.company_name,
    role: r.role,
    isDefault: r.is_default,
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await sql`UPDATE company_users SET is_default = false WHERE user_id = ${userId}`;
  await sql`UPDATE company_users SET is_default = true WHERE user_id = ${userId} AND company_id = ${companyId}::UUID`;
}

export async function addUserToCompany(companyId: string, userId: string, role = 'user'): Promise<void> {
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${companyId}::UUID, ${userId}, ${role})
    ON CONFLICT (company_id, user_id) DO UPDATE SET role = ${role}
  `;
}

export async function removeUserFromCompany(companyId: string, userId: string): Promise<void> {
  await sql`DELETE FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}`;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Row): Company {
  return {
    id: r.id,
    name: r.name,
    tradingName: r.trading_name,
    registrationNumber: r.registration_number,
    vatNumber: r.vat_number,
    taxNumber: r.tax_number,
    addressLine1: r.address_line1,
    addressLine2: r.address_line2,
    city: r.city,
    province: r.province,
    postalCode: r.postal_code,
    country: r.country,
    phone: r.phone,
    email: r.email,
    website: r.website,
    logoUrl: r.logo_url,
    bankName: r.bank_name,
    bankAccountNumber: r.bank_account_number,
    bankBranchCode: r.bank_branch_code,
    bankAccountType: r.bank_account_type,
    financialYearStart: r.financial_year_start,
    vatPeriod: r.vat_period,
    defaultCurrency: r.default_currency,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * Companies API
 * GET  — list companies for current user
 * POST — create a new company
 * PUT  — update company details
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listCompanies, getCompany, createCompany, updateCompany,
  getUserCompanies, setDefaultCompany,
} from '@/modules/accounting/services/companyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    if (req.query.action === 'user-companies') {
      const companies = await getUserCompanies(userId);
      return apiResponse.success(res, { items: companies });
    }
    if (req.query.id) {
      // Verify user has access to this company
      const userCompanies = await getUserCompanies(userId);
      const hasAccess = userCompanies.some(c => c.companyId === req.query.id);
      if (!hasAccess) return apiResponse.forbidden(res, 'You do not have access to this company');
      const company = await getCompany(req.query.id as string);
      if (!company) return apiResponse.notFound(res, 'Company');
      return apiResponse.success(res, company);
    }
    // Default: only return companies the user belongs to
    const companies = await getUserCompanies(userId);
    return apiResponse.success(res, { items: companies });
  }

  if (req.method === 'POST') {
    if (req.body.action === 'set-default') {
      // Verify membership before setting default
      const userCompanies = await getUserCompanies(userId);
      if (!userCompanies.some(c => c.companyId === req.body.companyId)) {
        return apiResponse.forbidden(res, 'You do not have access to this company');
      }
      await setDefaultCompany(userId, req.body.companyId);
      return apiResponse.success(res, { success: true });
    }
    const { name, tradingName, registrationNumber, vatNumber, taxNumber, email, phone } = req.body;
    if (!name) return apiResponse.badRequest(res, 'name is required');
    const company = await createCompany(
      { name, tradingName, registrationNumber, vatNumber, taxNumber, email, phone },
      userId
    );
    return apiResponse.success(res, company);
  }

  if (req.method === 'PUT') {
    const { id, ...updates } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    // Verify user is owner or admin of this company
    const userCompanies = await getUserCompanies(userId);
    const membership = userCompanies.find(c => c.companyId === id);
    if (!membership) return apiResponse.forbidden(res, 'You do not have access to this company');
    if (!['owner', 'admin'].includes(membership.role)) {
      return apiResponse.forbidden(res, 'Only owners and admins can update company details');
    }
    const company = await updateCompany(id, updates);
    return apiResponse.success(res, company);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * POST /api/auth/login
 * Authenticates a user with email + password.
 * On success: signs a JWT, creates a DB session, sets an HttpOnly cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword } from '@/lib/auth/password';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const { email, password } = req.body as { email?: string; password?: string };

  if (!email || !password) {
    return apiResponse.badRequest(res, 'Email and password are required');
  }

  try {
    // Look up user by email
    const rows = (await sql`
      SELECT id, email, password_hash, first_name, last_name, role,
             is_active, permissions, profile_picture, department
      FROM users
      WHERE email = ${email.toLowerCase().trim()}
      LIMIT 1
    `) as Row[];

    const user = rows[0];

    if (!user) {
      // Constant-time failure — avoid timing attacks
      await verifyPassword(password, '$2a$12$placeholder.hash.to.prevent.timing.attacks');
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    if (!user.is_active) {
      return res.status(403).json({
        success: false,
        error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
      });
    }

    // Verify password
    const passwordValid = await verifyPassword(password, user.password_hash as string);
    if (!passwordValid) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Sign JWT and create DB session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    // Create session first, then sign token with the real sessionId
    // We pass a temporary token to createSession, then update the hash
    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);

    // Re-sign token with the real sessionId
    const finalToken = await signToken(authUser, session.id);

    // Update session with the hash of the final token
    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Set HttpOnly cookie
    res.setHeader(
      'Set-Cookie',
      serialize(AUTH_COOKIE_NAME, finalToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        path: '/',
        maxAge: 30 * 24 * 60 * 60, // 30 days
      })
    );

    log.info('User logged in', { userId: authUser.id, email: authUser.email }, 'auth/login');

    return apiResponse.success(res, { user: authUser }, 'Login successful');
  } catch (err) {
    log.error('Login error', err instanceof Error ? { message: err.message } : { err }, 'auth/login');
    return apiResponse.internalError(res, err);
  }
}

