/**
 * Accounting Documents API
 * GET  /api/accounting/documents?entity_type=...&entity_id=...  — List documents (direct + cross-linked)
 * POST /api/accounting/documents  (multipart form-data)          — Upload document
 * DELETE /api/accounting/documents?id=...                        — Soft-delete document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import formidable from 'formidable';
import fs from 'fs';
import { vfStorage } from '@/services/vfStorageAdapter';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import type {
  ProcurementDocument,
  LinkedDocument,
  AccountingEntityType,
  AccountingDocumentType,
} from '@/types/procurement/document.types';

export const config = {
  api: { bodyParser: false },
};

const VALID_ENTITY_TYPES: AccountingEntityType[] = [
  'supplier_invoice',
  'supplier_payment',
  'customer_invoice',
  'customer_payment',
  'credit_note',
];

const VALID_DOCUMENT_TYPES: AccountingDocumentType[] = [
  'proof_of_payment',
  'bank_statement',
  'remittance_advice',
  'credit_note_doc',
  'invoice',
  'receipt',
  'other',
];

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB

function validateMagicBytes(buffer: Buffer): boolean {
  if (buffer.length < 4) return false;
  const hex = buffer.subarray(0, 8).toString('hex').toUpperCase();
  if (hex.startsWith('FFD8FF')) return true;   // JPEG
  if (hex.startsWith('89504E47')) return true;  // PNG
  if (hex.startsWith('25504446')) return true;  // PDF
  if (hex.startsWith('504B0304')) return true;  // ZIP (docx/xlsx)
  return false;
}

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({ maxFileSize: MAX_FILE_SIZE, keepExtensions: true });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>, source: 'direct' | 'linked' = 'direct', linkReason?: string): LinkedDocument {
  return {
    id: row.id as string,
    entityType: row.entity_type as string,
    entityId: row.entity_id as string,
    documentType: row.document_type as AccountingDocumentType,
    documentName: row.document_name as string,
    fileUrl: row.file_url as string,
    filePath: (row.file_path as string) || undefined,
    fileSize: (row.file_size as number) || undefined,
    mimeType: (row.mime_type as string) || undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedByName: (row.uploaded_by_name as string) || undefined,
    uploadedAt: new Date(row.uploaded_at as string).toISOString(),
    notes: (row.notes as string) || undefined,
    isActive: row.is_active as boolean,
    source,
    linkReason,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string; name: string; email: string } }).user;

  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res, user);
  if (req.method === 'DELETE') return handleDelete(req, res);

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** GET — List direct + cross-linked documents for an accounting entity */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const entityType = req.query.entity_type as string;
  const entityId = req.query.entity_id as string;

  if (!entityType || !entityId) {
    return apiResponse.badRequest(res, 'Missing required query params: entity_type, entity_id');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
    return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  // Direct documents
  const directRows = await sql`
    SELECT * FROM procurement_documents
    WHERE entity_type = ${entityType}
      AND entity_id = ${entityId}::uuid
      AND is_active = true
    ORDER BY uploaded_at DESC
  `;

  // Cross-linked documents (via document_links)
  const linkedRows = await sql`
    SELECT pd.*, dl.link_reason
    FROM document_links dl
    JOIN procurement_documents pd ON pd.id = dl.document_id
    WHERE dl.linked_entity_type = ${entityType}
      AND dl.linked_entity_id = ${entityId}::uuid
      AND pd.is_active = true
    ORDER BY pd.uploaded_at DESC
  `;

  const results: LinkedDocument[] = [
    ...directRows.map(r => mapRow(r as Record<string, unknown>, 'direct')),
    ...linkedRows.map(r => mapRow(r as Record<string, unknown>, 'linked', (r as Record<string, unknown>).link_reason as string)),
  ];

  return apiResponse.success(res, results);
}

/** POST — Upload a document to an accounting entity */
async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  user: { id: string; name: string; email: string }
) {
  let tempFilePath: string | null = null;

  try {
    const { fields, files } = await parseForm(req);

    const entityType = (Array.isArray(fields.entity_type) ? fields.entity_type[0] : fields.entity_type) as string;
    const entityId = (Array.isArray(fields.entity_id) ? fields.entity_id[0] : fields.entity_id) as string;
    const documentType = ((Array.isArray(fields.document_type) ? fields.document_type[0] : fields.document_type) || 'other') as string;
    const notes = (Array.isArray(fields.notes) ? fields.notes[0] : fields.notes) as string | undefined;

    if (!entityType || !entityId) {
      return apiResponse.badRequest(res, 'Missing required fields: entity_type, entity_id');
    }
    if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
      return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
    }
    if (!VALID_DOCUMENT_TYPES.includes(documentType as AccountingDocumentType)) {
      return apiResponse.badRequest(res, `Invalid document_type. Allowed: ${VALID_DOCUMENT_TYPES.join(', ')}`);
    }

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;
    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    tempFilePath = file.filepath;

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype || '')) {
      return apiResponse.badRequest(res, `File type not allowed: ${file.mimetype}. Allowed: PDF, JPEG, PNG, DOCX, XLSX`);
    }
    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, 'File too large. Maximum size: 20MB');
    }

    const buffer = await fs.promises.readFile(file.filepath);
    if (!validateMagicBytes(buffer)) {
      return apiResponse.badRequest(res, 'File content does not match declared type');
    }

    // Upload to VF Storage: accounting/{entity_type}/{entityId}_{filename}
    const fileName = file.originalFilename || `document_${Date.now()}`;
    const storageName = `${entityId}_${fileName}`;
    const result = await vfStorage.uploadFile(buffer, 'accounting', entityType, storageName);

    // Insert DB record
    const [row] = await sql`
      INSERT INTO procurement_documents (
        entity_type, entity_id, document_type, document_name,
        file_url, file_path, file_size, mime_type,
        uploaded_by, uploaded_by_name, notes
      ) VALUES (
        ${entityType}, ${entityId}::uuid, ${documentType}, ${fileName},
        ${result.url}, ${result.path}, ${file.size}, ${file.mimetype || ''},
        ${user.email}, ${user.name}, ${notes || null}
      )
      RETURNING *
    `;

    const docId = (row as Record<string, unknown>).id as string;

    // Auto-link: if supplier_invoice, create cross-links to PO/GRN
    if (entityType === 'supplier_invoice') {
      await autoLinkSupplierInvoice(docId, entityId);
    }

    log.info('Accounting document uploaded', {
      data: { entityType, entityId, documentType, fileName },
    }, 'accounting-docs');

    return apiResponse.created(res, mapRow(row as Record<string, unknown>, 'direct'));
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error('Accounting document upload error', { error }, 'accounting-docs');
    return apiResponse.internalError(res, error, `Failed to upload document: ${errMsg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) =>
        log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'accounting')
      );
    }
  }
}

/**
 * Auto-link a newly uploaded supplier_invoice doc to related PO/GRN,
 * and create reverse links so existing PO/GRN docs appear on the invoice.
 */
async function autoLinkSupplierInvoice(docId: string, invoiceId: string) {
  try {
    // Look up FK references on the invoice
    const [invoice] = await sql`
      SELECT purchase_order_id, grn_id
      FROM sage_supplier_invoices
      WHERE id = ${invoiceId}::uuid
    `;

    if (!invoice) return;

    const poId = invoice.purchase_order_id as string | null;
    const grnId = invoice.grn_id as string | null;

    // Forward links: this doc -> PO/GRN
    if (poId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'purchase_order', ${poId}::uuid, 'po_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }
    if (grnId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'goods_receipt_note', ${grnId}::uuid, 'grn_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }

    // Reverse links: existing PO/GRN docs -> this invoice
    if (poId) {
      const poDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'purchase_order' AND entity_id = ${poId}::uuid AND is_active = true
      `;
      for (const doc of poDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'po_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
    if (grnId) {
      const grnDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'goods_receipt_note' AND entity_id = ${grnId}::uuid AND is_active = true
      `;
      for (const doc of grnDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'grn_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
  } catch (err) {
    log.warn('Auto-link supplier invoice docs failed (non-fatal)', { error: err }, 'accounting-docs');
  }
}

/** DELETE — Soft-delete a document */
async function handleDelete(req: NextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;
  if (!id) {
    return apiResponse.badRequest(res, 'Missing required query param: id');
  }

  const [row] = await sql`
    UPDATE procurement_documents
    SET is_active = false
    WHERE id = ${id}::uuid AND is_active = true
    RETURNING id
  `;

  if (!row) {
    return apiResponse.notFound(res, 'Document', id);
  }

  log.info('Accounting document soft-deleted', { data: { id } }, 'accounting-docs');
  return apiResponse.success(res, { id: row.id, deleted: true });
}

export default withCompany(handler);

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  ReactNode,
} from 'react';
import { useAuth } from './AuthContext';
import { apiFetch } from '@/lib/apiFetch';

const STORAGE_KEY = 'isaflow_active_company';

export interface Company {
  id: string;
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  phone?: string;
  email?: string;
  website?: string;
  logoUrl?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  defaultCurrency?: string;
  isActive?: boolean;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

interface CompanyContextType {
  activeCompany: Company | null;
  companies: CompanyUser[];
  loading: boolean;
  companyRole: string | null;
  switchCompany: (companyId: string) => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export function CompanyProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [activeCompany, setActiveCompany] = useState<Company | null>(null);
  const [companies, setCompanies] = useState<CompanyUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [companyRole, setCompanyRole] = useState<string | null>(null);

  const loadCompanyDetails = useCallback(async (companyId: string) => {
    try {
      const res = await apiFetch(`/api/accounting/companies?id=${companyId}`);
      if (res.ok) {
        const data = await res.json();
        const c = data.data;
        if (c) {
          const company: Company = {
            id: c.id,
            name: c.name,
            tradingName: c.trading_name || c.tradingName,
            registrationNumber: c.registration_number || c.registrationNumber,
            vatNumber: c.vat_number || c.vatNumber,
            taxNumber: c.tax_number || c.taxNumber,
            addressLine1: c.address_line1 || c.addressLine1,
            addressLine2: c.address_line2 || c.addressLine2,
            city: c.city,
            province: c.province,
            postalCode: c.postal_code || c.postalCode,
            country: c.country,
            phone: c.phone,
            email: c.email,
            website: c.website,
            logoUrl: c.logo_url || c.logoUrl,
            logoData: c.logo_data || c.logoData,
            bankName: c.bank_name || c.bankName,
            bankAccountNumber: c.bank_account_number || c.bankAccountNumber,
            bankBranchCode: c.bank_branch_code || c.bankBranchCode,
            bankAccountType: c.bank_account_type || c.bankAccountType,
            financialYearStart: c.financial_year_start || c.financialYearStart,
            vatPeriod: c.vat_period || c.vatPeriod,
            defaultCurrency: c.default_currency || c.defaultCurrency,
            isActive: c.is_active ?? c.isActive ?? true,
          };
          setActiveCompany(company);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ id: company.id, name: company.name }));
          return company;
        }
      }
    } catch {
      // Failed to load company details
    }
    return null;
  }, []);

  const loadUserCompanies = useCallback(async () => {
    if (!isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const res = await apiFetch('/api/accounting/companies?action=user-companies');

      if (!res.ok) {
        setLoading(false);
        return;
      }

      const data = await res.json();
      const raw = data.data?.items ?? data.data ?? [];
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const list: CompanyUser[] = (Array.isArray(raw) ? raw : []).map((c: any) => ({
        companyId: (c.companyId || c.company_id) as string,
        companyName: (c.companyName || c.company_name) as string,
        role: c.role as string,
        isDefault: Boolean(c.isDefault ?? c.is_default ?? false),
      }));

      setCompanies(list);

      if (list.length === 0) {
        setLoading(false);
        return;
      }

      // Determine which company to activate
      let targetId: string | null = null;

      // 1. Check localStorage
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const { id } = JSON.parse(stored);
          if (id && list.some((c: CompanyUser) => c.companyId === id)) {
            targetId = id;
          }
        }
      } catch {
        // Invalid stored data
      }

      // 2. Fall back to default company
      if (!targetId) {
        const defaultCompany = list.find((c: CompanyUser) => c.isDefault) ?? list[0];
        targetId = defaultCompany?.companyId ?? null;
      }

      if (!targetId) {
        setLoading(false);
        return;
      }

      // Set the role
      const match = list.find((c: CompanyUser) => c.companyId === targetId);
      if (match) setCompanyRole(match.role);

      await loadCompanyDetails(targetId);
    } catch {
      // Network error
    } finally {
      setLoading(false);
    }
  }, [isAuthenticated, loadCompanyDetails]);

  useEffect(() => {
    loadUserCompanies();
  }, [loadUserCompanies]);

  const switchCompany = useCallback(async (companyId: string) => {
    setLoading(true);
    const match = companies.find(c => c.companyId === companyId);
    if (match) setCompanyRole(match.role);
    await loadCompanyDetails(companyId);
    setLoading(false);

    // Set as default on the server
    try {
      await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'set-default', companyId }),
      });
    } catch {
      // Non-critical
    }
  }, [companies, loadCompanyDetails]);

  const value: CompanyContextType = {
    activeCompany,
    companies,
    loading,
    companyRole,
    switchCompany,
  };

  return <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>;
}

export function useCompany() {
  const context = useContext(CompanyContext);
  if (context === undefined) {
    throw new Error('useCompany must be used within a CompanyProvider');
  }
  return context;
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
  useCallback,
} from 'react';
import type { AuthRole } from '@/lib/auth/types';

/**
 * Authenticated user shape returned from /api/auth/me
 */
export interface AuthUser {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  name: string;
  role: AuthRole;
  permissions: string[];
  isActive: boolean;
  profilePicture?: string | null;
  department?: string;
}

interface AuthContextType {
  /** Currently authenticated user, or null if not logged in */
  user: AuthUser | null;
  /** True while the initial session check is in progress */
  loading: boolean;
  /** Last authentication error message */
  error: string | null;
  /** True when a valid user session exists */
  isAuthenticated: boolean;

  /** Sign in with email and password */
  login: (email: string, password: string) => Promise<void>;
  /** Sign out and redirect to /sign-in */
  logout: () => Promise<void>;
  /** Re-fetch the current user from /api/auth/me */
  refreshUser: () => Promise<void>;
  /** Clear the current error state */
  clearError: () => void;

  /** Check if the user has a specific permission string */
  hasPermission: (permission: string) => boolean;
  /** Check if the user has the given role or higher */
  hasRole: (role: AuthRole) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Map the raw API response into a typed AuthUser
 */
function mapApiUser(raw: Record<string, unknown>): AuthUser {
  const firstName = (raw.firstName as string) || (raw.first_name as string) || '';
  const lastName = (raw.lastName as string) || (raw.last_name as string) || '';
  const name =
    (raw.name as string) ||
    (firstName && lastName ? `${firstName} ${lastName}`.trim() : (raw.email as string));

  return {
    id: raw.id as string,
    email: raw.email as string,
    firstName,
    lastName,
    name,
    role: (raw.role as AuthRole) || 'viewer',
    permissions: (raw.permissions as string[]) || [],
    isActive: raw.isActive !== false && raw.is_active !== false,
    profilePicture: (raw.profilePicture as string) || (raw.profile_picture as string) || null,
    department: (raw.department as string) || undefined,
  };
}

// Role hierarchy for permission checks
const ROLE_HIERARCHY: Record<AuthRole, number> = {
  super_admin: 6,
  system: 5,
  admin: 4,
  manager: 3,
  storeman: 2,
  technician: 2,
  viewer: 1,
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  /**
   * Fetch current session from the API
   */
  const checkAuth = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/me', { credentials: 'include' });

      if (res.ok) {
        const data = await res.json();
        // Support both { data: { user } } and { data: user } shapes
        const raw = data.data?.user ?? data.data ?? data.user;
        if (raw) {
          setUser(mapApiUser(raw));
        } else {
          setUser(null);
        }
      } else {
        setUser(null);
      }
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkAuth();

    // Re-fetch user when tab regains focus (picks up RBAC changes)
    const onFocus = () => checkAuth();
    window.addEventListener('focus', onFocus);

    // Also poll every 5 minutes as a fallback
    const interval = setInterval(checkAuth, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('focus', onFocus);
      clearInterval(interval);
    };
  }, [checkAuth]);

  /**
   * Sign in with email/password credentials
   */
  const login = async (email: string, password: string) => {
    setLoading(true);
    setError(null);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Login failed');
      }

      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Sign out and clear session cookie
   */
  const logout = async () => {
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include',
      });
    } finally {
      setUser(null);
      if (typeof window !== 'undefined') {
        window.location.href = '/login';
      }
    }
  };

  const refreshUser = async () => {
    await checkAuth();
  };

  const clearError = () => {
    setError(null);
  };

  /**
   * Check if the current user holds a specific permission string.
   * Users with the 'all' permission pass all checks.
   */
  const hasPermission = (permission: string): boolean => {
    if (!user) return false;
    return user.permissions.includes('all') || user.permissions.includes(permission);
  };

  /**
   * Check if the current user's role meets or exceeds the required role level.
   */
  const hasRole = (role: AuthRole): boolean => {
    if (!user) return false;
    const userLevel = ROLE_HIERARCHY[user.role] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[role] ?? 0;
    return userLevel >= requiredLevel;
  };

  const value: AuthContextType = {
    user,
    loading,
    error,
    isAuthenticated: user !== null,
    login,
    logout,
    refreshUser,
    clearError,
    hasPermission,
    hasRole,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { defineConfig } from '@playwright/test';

export default defineConfig({
