/**
 * TDD: Asset Depreciation Calculation Tests
 * These tests define the contract for depreciation methods.
 * Written BEFORE implementation — all should FAIL initially (RED).
 */

import { describe, it, expect } from 'vitest';
import {
  calculateStraightLine,
  calculateReducingBalance,
  calculateSumOfYears,
  calculateDepreciation,
  type DepreciationInput,
  type DepreciationResult,
} from '@/modules/accounting/services/assetService';

// ═══════════════════════════════════════════════════════════════════════════
// STRAIGHT-LINE DEPRECIATION
// Formula: (Cost - Salvage) / Useful Life Years / 12
// ═══════════════════════════════════════════════════════════════════════════

describe('Straight-Line Depreciation', () => {
  it('calculates monthly depreciation correctly', () => {
    const result = calculateStraightLine({
      cost: 120000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    // (120000 - 0) / 5 / 12 = 2000/month
    expect(result.monthlyAmount).toBe(2000);
    expect(result.annualAmount).toBe(24000);
  });

  it('accounts for salvage value', () => {
    const result = calculateStraightLine({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    // (100000 - 10000) / 5 / 12 = 1500/month
    expect(result.monthlyAmount).toBe(1500);
  });

  it('returns zero when fully depreciated', () => {
    const result = calculateStraightLine({
      cost: 60000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 60, // 5 years = fully depreciated
    });
    expect(result.monthlyAmount).toBe(0);
  });

  it('caps depreciation at remaining depreciable amount', () => {
    const result = calculateStraightLine({
      cost: 60000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 59,
      accumulatedDepreciation: 59000,
    });
    // Only R1000 left to depreciate
    expect(result.monthlyAmount).toBe(1000);
  });

  it('handles zero useful life gracefully', () => {
    const result = calculateStraightLine({
      cost: 10000,
      salvageValue: 0,
      usefulLifeYears: 0,
      monthsElapsed: 0,
    });
    expect(result.monthlyAmount).toBe(0);
  });

  it('handles cost equal to salvage value', () => {
    const result = calculateStraightLine({
      cost: 10000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    expect(result.monthlyAmount).toBe(0);
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// REDUCING BALANCE DEPRECIATION
// Formula: Book Value * (Rate / 12), where Rate is typically 2/useful_life
// ═══════════════════════════════════════════════════════════════════════════

describe('Reducing Balance Depreciation', () => {
  it('calculates first month correctly', () => {
    const result = calculateReducingBalance({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    // Rate = 2/5 = 40%, Monthly = 100000 * 0.4 / 12 = 3333.33
    expect(result.monthlyAmount).toBeCloseTo(3333.33, 0);
  });

  it('reduces depreciation amount as book value decreases', () => {
    const month1 = calculateReducingBalance({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    const month2 = calculateReducingBalance({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 1,
      accumulatedDepreciation: month1.monthlyAmount,
    });
    expect(month2.monthlyAmount).toBeLessThan(month1.monthlyAmount);
  });

  it('does not depreciate below salvage value', () => {
    const result = calculateReducingBalance({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 120,
      accumulatedDepreciation: 89500,
    });
    // Only R500 left before hitting salvage
    expect(result.monthlyAmount).toBeLessThanOrEqual(500);
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// SUM-OF-YEARS DIGITS DEPRECIATION
// Formula: (Cost - Salvage) * (Remaining Life / Sum of Digits) / 12
// ═══════════════════════════════════════════════════════════════════════════

describe('Sum-of-Years Digits Depreciation', () => {
  it('calculates first year correctly', () => {
    // 5-year life: sum = 15, first year fraction = 5/15 = 1/3
    const result = calculateSumOfYears({
      cost: 150000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    // Year 1: 150000 * (5/15) / 12 = 150000 * 0.3333 / 12 = 4166.67
    expect(result.monthlyAmount).toBeCloseTo(4166.67, 0);
  });

  it('decreases each year', () => {
    const year1 = calculateSumOfYears({
      cost: 150000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    const year2 = calculateSumOfYears({
      cost: 150000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 12,
    });
    expect(year2.monthlyAmount).toBeLessThan(year1.monthlyAmount);
  });

  it('returns zero after useful life exhausted', () => {
    const result = calculateSumOfYears({
      cost: 150000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 60,
    });
    expect(result.monthlyAmount).toBe(0);
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// SARS WEAR-AND-TEAR RATES (South Africa specific)
// ═══════════════════════════════════════════════════════════════════════════

describe('SARS Wear-and-Tear Integration', () => {
  it('applies SARS rate for computers (3 years)', () => {
    const result = calculateDepreciation({
      cost: 30000,
      salvageValue: 0,
      usefulLifeYears: 3,
      monthsElapsed: 0,
      method: 'straight_line',
      sarsCategory: 'computers',
    });
    // SARS allows 33.33% (3 years) for computers
    expect(result.monthlyAmount).toBeCloseTo(833.33, 0);
    expect(result.annualRate).toBeCloseTo(33.33, 0);
  });

  it('applies SARS rate for motor vehicles (5 years)', () => {
    const result = calculateDepreciation({
      cost: 500000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 0,
      method: 'straight_line',
      sarsCategory: 'motor_vehicles',
    });
    // 20% per year = 500000/5/12 = 8333.33
    expect(result.monthlyAmount).toBeCloseTo(8333.33, 0);
    expect(result.annualRate).toBeCloseTo(20, 0);
  });

  it('applies SARS rate for furniture (6 years)', () => {
    const result = calculateDepreciation({
      cost: 36000,
      salvageValue: 0,
      usefulLifeYears: 6,
      monthsElapsed: 0,
      method: 'straight_line',
      sarsCategory: 'furniture',
    });
    // 16.67% per year
    expect(result.monthlyAmount).toBe(500);
    expect(result.annualRate).toBeCloseTo(16.67, 0);
  });

  it('applies SARS rate for manufacturing equipment (4 years / 20% SLA)', () => {
    const result = calculateDepreciation({
      cost: 1000000,
      salvageValue: 0,
      usefulLifeYears: 4,
      monthsElapsed: 0,
      method: 'straight_line',
      sarsCategory: 'manufacturing_equipment',
    });
    expect(result.annualRate).toBeCloseTo(25, 0);
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// DISPATCH / METHOD SELECTION
// ═══════════════════════════════════════════════════════════════════════════

describe('calculateDepreciation dispatcher', () => {
  const base: DepreciationInput = {
    cost: 120000,
    salvageValue: 0,
    usefulLifeYears: 5,
    monthsElapsed: 0,
    method: 'straight_line',
  };

  it('routes to straight-line', () => {
    const result = calculateDepreciation({ ...base, method: 'straight_line' });
    expect(result.method).toBe('straight_line');
    expect(result.monthlyAmount).toBe(2000);
  });

  it('routes to reducing balance', () => {
    const result = calculateDepreciation({ ...base, method: 'reducing_balance' });
    expect(result.method).toBe('reducing_balance');
    expect(result.monthlyAmount).toBeGreaterThan(0);
  });

  it('routes to sum-of-years', () => {
    const result = calculateDepreciation({ ...base, method: 'sum_of_years' });
    expect(result.method).toBe('sum_of_years');
    expect(result.monthlyAmount).toBeGreaterThan(0);
  });

  it('defaults to straight-line for unknown method', () => {
    const result = calculateDepreciation({ ...base, method: 'unknown' as any });
    expect(result.method).toBe('straight_line');
  });

  it('result includes all required fields', () => {
    const result = calculateDepreciation(base);
    expect(result).toHaveProperty('monthlyAmount');
    expect(result).toHaveProperty('annualAmount');
    expect(result).toHaveProperty('annualRate');
    expect(result).toHaveProperty('method');
    expect(result).toHaveProperty('remainingMonths');
    expect(typeof result.monthlyAmount).toBe('number');
    expect(typeof result.annualAmount).toBe('number');
    expect(typeof result.annualRate).toBe('number');
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// TAX vs BOOK DEPRECIATION
// ═══════════════════════════════════════════════════════════════════════════

describe('Tax vs Book Depreciation', () => {
  it('can calculate both tax and book depreciation for same asset', () => {
    const bookDep = calculateDepreciation({
      cost: 100000,
      salvageValue: 10000,
      usefulLifeYears: 10,
      monthsElapsed: 0,
      method: 'straight_line',
    });

    const taxDep = calculateDepreciation({
      cost: 100000,
      salvageValue: 0,
      usefulLifeYears: 6, // SARS furniture rate
      monthsElapsed: 0,
      method: 'straight_line',
      sarsCategory: 'furniture',
    });

    // Tax depreciation should be higher (shorter life, no salvage)
    expect(taxDep.monthlyAmount).toBeGreaterThan(bookDep.monthlyAmount);
  });
});

