      salvageValue: 10000,
      usefulLifeYears: 5,
      monthsElapsed: 120,
      accumulatedDepreciation: 89500,
    });
    // Only R500 left before hitting salvage
    expect(result.monthlyAmount).toBeLessThanOrEqual(500);
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// SUM-OF-YEARS DIGITS DEPRECIATION
// Formula: (Cost - Salvage) * (Remaining Life / Sum of Digits) / 12
// ═══════════════════════════════════════════════════════════════════════════

describe('Sum-of-Years Digits Depreciation', () => {
  it('calculates first year correctly', () => {
