      usefulLifeYears: 5,
      monthsElapsed: 0,
    });
    const year2 = calculateSumOfYears({
      cost: 150000,
      salvageValue: 0,
      usefulLifeYears: 5,
      monthsElapsed: 12,
    });
    expect(year2.monthlyAmount).toBeLessThan(year1.monthlyAmount);
