/**
 * TDD: Asset Validation & Business Rules Tests
 * Written BEFORE implementation — all should FAIL initially (RED).
 */

import { describe, it, expect } from 'vitest';
import {
  validateAsset,
  validateDisposal,
  generateAssetNumber,
  SARS_WEAR_AND_TEAR,
  type AssetInput,
  type DisposalInput,
} from '@/modules/accounting/services/assetService';

// ═══════════════════════════════════════════════════════════════════════════
// ASSET VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

describe('Asset Input Validation', () => {
  const validAsset: AssetInput = {
    name: 'Dell Laptop XPS 15',
    category: 'computers',
    purchaseDate: '2026-01-15',
    cost: 25000,
    salvageValue: 2500,
    usefulLifeYears: 3,
    depreciationMethod: 'straight_line',
    location: 'Head Office',
    status: 'available',
  };

  it('accepts a valid asset', () => {
    const result = validateAsset(validAsset);
    expect(result.success).toBe(true);
    expect(result.errors).toBeUndefined();
  });

  it('rejects missing name', () => {
    const result = validateAsset({ ...validAsset, name: '' });
    expect(result.success).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({ field: 'name' })
    );
  });

  it('rejects negative cost', () => {
    const result = validateAsset({ ...validAsset, cost: -1000 });
    expect(result.success).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({ field: 'cost' })
    );
  });

  it('rejects zero cost', () => {
    const result = validateAsset({ ...validAsset, cost: 0 });
    expect(result.success).toBe(false);
  });

  it('rejects salvage value greater than cost', () => {
    const result = validateAsset({ ...validAsset, salvageValue: 30000 });
    expect(result.success).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({ field: 'salvageValue' })
    );
  });

  it('rejects negative useful life', () => {
    const result = validateAsset({ ...validAsset, usefulLifeYears: -1 });
    expect(result.success).toBe(false);
  });

  it('rejects zero useful life', () => {
    const result = validateAsset({ ...validAsset, usefulLifeYears: 0 });
    expect(result.success).toBe(false);
  });

  it('rejects invalid depreciation method', () => {
    const result = validateAsset({
      ...validAsset,
      depreciationMethod: 'invalid_method' as any,
    });
    expect(result.success).toBe(false);
  });

  it('accepts valid depreciation methods', () => {
    for (const method of ['straight_line', 'reducing_balance', 'sum_of_years']) {
      const result = validateAsset({
        ...validAsset,
        depreciationMethod: method as any,
      });
      expect(result.success).toBe(true);
    }
  });

  it('rejects future purchase date beyond today', () => {
    const future = new Date();
    future.setFullYear(future.getFullYear() + 1);
    const result = validateAsset({
      ...validAsset,
      purchaseDate: future.toISOString().split('T')[0]!,
    });
    expect(result.success).toBe(false);
  });

  it('rejects invalid date format', () => {
    const result = validateAsset({
      ...validAsset,
      purchaseDate: 'not-a-date',
    });
    expect(result.success).toBe(false);
  });

  it('accepts valid statuses', () => {
    for (const status of ['available', 'assigned', 'in_maintenance', 'disposed', 'written_off']) {
      const result = validateAsset({ ...validAsset, status: status as any });
      expect(result.success).toBe(true);
    }
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// DISPOSAL VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

describe('Asset Disposal Validation', () => {
  const validDisposal: DisposalInput = {
    assetId: '123e4567-e89b-12d3-a456-426614174000',
    disposalDate: '2026-03-15',
    disposalMethod: 'sale',
    disposalAmount: 5000,
    reason: 'End of useful life',
  };

  it('accepts valid disposal', () => {
    const result = validateDisposal(validDisposal);
    expect(result.success).toBe(true);
  });

  it('rejects disposal without asset ID', () => {
    const result = validateDisposal({ ...validDisposal, assetId: '' });
    expect(result.success).toBe(false);
  });

  it('rejects negative disposal amount', () => {
    const result = validateDisposal({ ...validDisposal, disposalAmount: -100 });
    expect(result.success).toBe(false);
  });

  it('allows zero disposal amount for write-offs', () => {
    const result = validateDisposal({
      ...validDisposal,
      disposalMethod: 'write_off',
      disposalAmount: 0,
    });
    expect(result.success).toBe(true);
  });

  it('requires reason for disposal', () => {
    const result = validateDisposal({ ...validDisposal, reason: '' });
    expect(result.success).toBe(false);
  });

  it('accepts valid disposal methods', () => {
    for (const method of ['sale', 'scrap', 'write_off', 'donation', 'theft', 'insurance_claim']) {
      const result = validateDisposal({ ...validDisposal, disposalMethod: method as any });
      expect(result.success).toBe(true);
    }
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET NUMBER GENERATION
// ═══════════════════════════════════════════════════════════════════════════

describe('Asset Number Generation', () => {
  it('generates sequential asset numbers', () => {
    const num1 = generateAssetNumber('computers', 0);
    const num2 = generateAssetNumber('computers', 1);
    expect(num1).toBe('COMP-0001');
    expect(num2).toBe('COMP-0002');
  });

  it('uses correct prefix for each category', () => {
    expect(generateAssetNumber('computers', 0)).toMatch(/^COMP-/);
    expect(generateAssetNumber('motor_vehicles', 0)).toMatch(/^VEHI-/);
    expect(generateAssetNumber('furniture', 0)).toMatch(/^FURN-/);
    expect(generateAssetNumber('office_equipment', 0)).toMatch(/^OFEQ-/);
    expect(generateAssetNumber('buildings', 0)).toMatch(/^BLDG-/);
    expect(generateAssetNumber('machinery', 0)).toMatch(/^MACH-/);
  });

  it('pads numbers to 4 digits', () => {
    expect(generateAssetNumber('computers', 0)).toBe('COMP-0001');
    expect(generateAssetNumber('computers', 99)).toBe('COMP-0100');
    expect(generateAssetNumber('computers', 999)).toBe('COMP-1000');
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// SARS WEAR-AND-TEAR TABLE
// ═══════════════════════════════════════════════════════════════════════════

describe('SARS Wear-and-Tear Categories', () => {
  it('has correct rate for computers (33.33%)', () => {
    expect(SARS_WEAR_AND_TEAR.computers).toBeDefined();
    expect(SARS_WEAR_AND_TEAR.computers.rate).toBeCloseTo(33.33, 0);
    expect(SARS_WEAR_AND_TEAR.computers.years).toBe(3);
  });

  it('has correct rate for motor vehicles (20%)', () => {
    expect(SARS_WEAR_AND_TEAR.motor_vehicles.rate).toBeCloseTo(20, 0);
    expect(SARS_WEAR_AND_TEAR.motor_vehicles.years).toBe(5);
  });

  it('has correct rate for furniture (16.67%)', () => {
    expect(SARS_WEAR_AND_TEAR.furniture.rate).toBeCloseTo(16.67, 0);
    expect(SARS_WEAR_AND_TEAR.furniture.years).toBe(6);
  });

  it('has correct rate for office equipment (20%)', () => {
    expect(SARS_WEAR_AND_TEAR.office_equipment.rate).toBeCloseTo(20, 0);
    expect(SARS_WEAR_AND_TEAR.office_equipment.years).toBe(5);
  });

  it('has correct rate for buildings (5%)', () => {
    expect(SARS_WEAR_AND_TEAR.buildings.rate).toBe(5);
    expect(SARS_WEAR_AND_TEAR.buildings.years).toBe(20);
  });

  it('has correct rate for machinery (12.5%)', () => {
    expect(SARS_WEAR_AND_TEAR.machinery.rate).toBe(12.5);
    expect(SARS_WEAR_AND_TEAR.machinery.years).toBe(8);
  });

  it('has correct rate for manufacturing equipment (25%)', () => {
    expect(SARS_WEAR_AND_TEAR.manufacturing_equipment.rate).toBe(25);
    expect(SARS_WEAR_AND_TEAR.manufacturing_equipment.years).toBe(4);
  });

  it('has correct rate for small tools (50%)', () => {
    expect(SARS_WEAR_AND_TEAR.small_tools.rate).toBe(50);
    expect(SARS_WEAR_AND_TEAR.small_tools.years).toBe(2);
  });

  it('has correct rate for aircraft (25%)', () => {
    expect(SARS_WEAR_AND_TEAR.aircraft.rate).toBe(25);
    expect(SARS_WEAR_AND_TEAR.aircraft.years).toBe(4);
  });

  it('includes description for each category', () => {
    for (const [key, val] of Object.entries(SARS_WEAR_AND_TEAR)) {
      expect(val).toHaveProperty('description');
      expect(val.description.length).toBeGreaterThan(0);
    }
  });
});

/**
 * TDD: Asset Validation & Business Rules Tests
