  bankName: string | null;
  bankAccountNumber: string | null;
  bankBranchCode: string | null;
  bankAccountType: string | null;
  financialYearStart: number;
  vatPeriod: string;
  defaultCurrency: string | null;
}

interface CompanyDocument {
  id: string;
  documentType: string;
  documentName: string;
  mimeType: string;
  fileSize: number;
  createdAt: string;
}

