/**
 * TDD: Sprint 1 — Fixed Asset Register E2E Tests
 * Written BEFORE implementation — all should FAIL initially (RED).
 * Tests page rendering, API responses, and user workflows.
 */

import { test, expect } from '@playwright/test';

// ═══════════════════════════════════════════════════════════════════════════
// NEW PAGE ROUTES — must return 200
// ═══════════════════════════════════════════════════════════════════════════

const ASSET_ROUTES = [
  '/accounting/assets',
  '/accounting/assets/new',
  '/accounting/assets/categories',
  '/accounting/assets/disposals',
  '/accounting/assets/register',
];

test.describe('Asset page routes load', () => {
  for (const route of ASSET_ROUTES) {
    test(`GET ${route} returns 200 or 307`, async ({ page }) => {
      const response = await page.goto(route);
      const status = response?.status() ?? 0;
      expect([200, 307]).toContain(status);
    });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// API ROUTES — must respond (not 404)
// ═══════════════════════════════════════════════════════════════════════════

const ASSET_API_ROUTES = [
  '/api/accounting/assets',
  '/api/accounting/assets-categories',
  '/api/accounting/assets-disposals',
  '/api/accounting/assets-register',
  '/api/accounting/assets-depreciation-schedule',
];

test.describe('Asset API routes respond', () => {
  for (const route of ASSET_API_ROUTES) {
    test(`GET ${route} does not 404`, async ({ request }) => {
      const response = await request.get(route);
      expect(response.status()).not.toBe(404);
    });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET LIST PAGE
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset List Page', () => {
  test('shows correct heading', async ({ page }) => {
    await page.goto('/accounting/assets');
    await expect(page.locator('h1', { hasText: /Fixed Assets|Asset Register/ })).toBeVisible();
  });

  test('has Add Asset button', async ({ page }) => {
    await page.goto('/accounting/assets');
    const addBtn = page.locator('a, button').filter({ hasText: /Add Asset|New Asset/ });
    await expect(addBtn.first()).toBeVisible();
  });

  test('displays asset table with correct columns', async ({ page }) => {
    await page.goto('/accounting/assets');
    const headers = ['Asset', 'Name', 'Category', 'Cost', 'Book Value', 'Status'];
    for (const header of headers) {
      await expect(page.locator('th', { hasText: header }).first()).toBeVisible();
    }
  });

  test('has category filter', async ({ page }) => {
    await page.goto('/accounting/assets');
    const filter = page.locator('select').first();
    await expect(filter).toBeVisible();
  });

  test('has status filter', async ({ page }) => {
    await page.goto('/accounting/assets');
    await expect(page.getByText(/All Status|Status/i).first()).toBeVisible();
  });

  test('has export button', async ({ page }) => {
    await page.goto('/accounting/assets');
    const exportBtn = page.locator('button', { hasText: /Export|CSV/ });
    await expect(exportBtn.first()).toBeVisible();
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// NEW ASSET FORM
// ═══════════════════════════════════════════════════════════════════════════

test.describe('New Asset Form', () => {
  test('shows correct heading', async ({ page }) => {
    await page.goto('/accounting/assets/new');
    await expect(page.locator('h1', { hasText: /New Asset|Add Asset/ })).toBeVisible();
  });

  test('has all required form fields', async ({ page }) => {
    await page.goto('/accounting/assets/new');

    // Name field
    await expect(page.locator('label', { hasText: /Name/i }).first()).toBeVisible();
    // Category selector
    await expect(page.locator('label', { hasText: /Category/i }).first()).toBeVisible();
    // Purchase date
    await expect(page.locator('label', { hasText: /Purchase Date/i }).first()).toBeVisible();
    // Cost
    await expect(page.locator('label', { hasText: /Cost|Purchase Price/i }).first()).toBeVisible();
    // Salvage value
    await expect(page.locator('label', { hasText: /Salvage|Residual/i }).first()).toBeVisible();
    // Useful life
    await expect(page.locator('label', { hasText: /Useful Life/i }).first()).toBeVisible();
    // Depreciation method
    await expect(page.locator('label', { hasText: /Depreciation Method/i }).first()).toBeVisible();
  });

  test('depreciation method dropdown has all options', async ({ page }) => {
    await page.goto('/accounting/assets/new');
    // Check for depreciation method options
    await expect(page.getByText(/Straight.Line/i).first()).toBeVisible();
  });

  test('shows SARS category selector', async ({ page }) => {
    await page.goto('/accounting/assets/new');
    await expect(page.getByText(/SARS|Wear.and.Tear/i).first()).toBeVisible();
  });

  test('has save button', async ({ page }) => {
    await page.goto('/accounting/assets/new');
    const saveBtn = page.locator('button', { hasText: /Save|Create/i });
    await expect(saveBtn.first()).toBeVisible();
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET CATEGORIES PAGE
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset Categories Page', () => {
  test('shows SARS wear-and-tear categories', async ({ page }) => {
    await page.goto('/accounting/assets/categories');
    await expect(page.locator('h1', { hasText: /Asset Categories|SARS/i })).toBeVisible();
  });

  test('displays standard SARS categories', async ({ page }) => {
    await page.goto('/accounting/assets/categories');
    const expectedCategories = ['Computers', 'Motor Vehicles', 'Furniture', 'Office Equipment'];
    for (const cat of expectedCategories) {
      await expect(page.getByText(cat).first()).toBeVisible();
    }
  });

  test('shows depreciation rates', async ({ page }) => {
    await page.goto('/accounting/assets/categories');
    // Should show percentage rates
    await expect(page.getByText(/33\.33%|33%/).first()).toBeVisible(); // Computers
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET REGISTER REPORT
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset Register Report', () => {
  test('shows register heading', async ({ page }) => {
    await page.goto('/accounting/assets/register');
    await expect(page.locator('h1', { hasText: /Asset Register/i })).toBeVisible();
  });

  test('has date range filter', async ({ page }) => {
    await page.goto('/accounting/assets/register');
    // Should have date inputs for period selection
    const dateInputs = page.locator('input[type="date"]');
    expect(await dateInputs.count()).toBeGreaterThanOrEqual(1);
  });

  test('has export functionality', async ({ page }) => {
    await page.goto('/accounting/assets/register');
    const exportBtn = page.locator('button', { hasText: /Export|CSV|PDF/ });
    await expect(exportBtn.first()).toBeVisible();
  });

  test('shows summary totals', async ({ page }) => {
    await page.goto('/accounting/assets/register');
    // Should show total cost, total accumulated depreciation, total book value
    await expect(page.getByText(/Total Cost|Total Assets/i).first()).toBeVisible();
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET DISPOSAL PAGE
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset Disposals Page', () => {
  test('shows disposals heading', async ({ page }) => {
    await page.goto('/accounting/assets/disposals');
    await expect(page.locator('h1', { hasText: /Disposal|Disposed/i })).toBeVisible();
  });

  test('shows disposal methods', async ({ page }) => {
    await page.goto('/accounting/assets/disposals');
    // Should reference disposal types
    await expect(page.getByText(/Sale|Scrap|Write.Off/i).first()).toBeVisible();
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// DEPRECIATION PAGE (existing — enhanced)
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Enhanced Depreciation Page', () => {
  test('depreciation page still loads', async ({ page }) => {
    await page.goto('/accounting/depreciation');
    await expect(page.locator('h1', { hasText: /Depreciation/ })).toBeVisible();
  });

  test('shows depreciation method selector', async ({ page }) => {
    await page.goto('/accounting/depreciation');
    // Enhanced page should allow choosing method
    await expect(page.getByText(/Straight|Method/i).first()).toBeVisible();
  });

  test('run depreciation button exists', async ({ page }) => {
    await page.goto('/accounting/depreciation');
    const btn = page.locator('button', { hasText: /Run.*Depreciation/i });
    await expect(btn.first()).toBeVisible();
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// ASSET API CRUD OPERATIONS
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset API CRUD', () => {
  test('GET /api/accounting/assets returns list', async ({ request }) => {
    const response = await request.get('/api/accounting/assets');
    expect([200, 401]).toContain(response.status());
    if (response.status() === 200) {
      const json = await response.json();
      expect(json.success).toBe(true);
      expect(Array.isArray(json.data)).toBe(true);
    }
  });

  test('POST /api/accounting/assets validates required fields', async ({ request }) => {
    const response = await request.post('/api/accounting/assets', {
      data: {}, // Empty body should fail validation
    });
    // Should get 400 (validation) or 401 (auth), never 500
    expect([400, 401, 422]).toContain(response.status());
  });

  test('GET /api/accounting/assets-categories returns SARS categories', async ({ request }) => {
    const response = await request.get('/api/accounting/assets-categories');
    expect([200, 401]).toContain(response.status());
    if (response.status() === 200) {
      const json = await response.json();
      expect(json.success).toBe(true);
      expect(json.data).toBeDefined();
    }
  });

  test('GET /api/accounting/assets-depreciation-schedule returns schedule', async ({ request }) => {
    const response = await request.get('/api/accounting/assets-depreciation-schedule');
    expect([200, 400, 401]).toContain(response.status());
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// NAVIGATION — Assets appears in nav
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Asset Navigation Integration', () => {
  test('Accountant\'s Area dropdown contains Assets link', async ({ page }) => {
    await page.goto('/accounting');
    const nav = page.locator('nav.bg-gray-900');
    const btn = nav.getByRole('button', { name: "Accountant's Area", exact: true });
    await btn.click();
    const dropdown = nav.locator('.absolute');
    await expect(dropdown.first()).toBeVisible();
    await expect(dropdown.getByText(/Assets|Fixed Assets/).first()).toBeVisible();
  });
});

