          addressLine1: c.addressLine1 ?? c.address_line1 ?? null,
          addressLine2: c.addressLine2 ?? c.address_line2 ?? null,
          city: c.city ?? null,
          province: c.province ?? null,
          postalCode: c.postalCode ?? c.postal_code ?? null,
          phone: c.phone ?? null,
          email: c.email ?? null,
