/**
 * /onboarding — 7-step company setup wizard.
 * Standalone layout (no AppLayout), matches login dark theme.
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Check, Upload, Building2, MapPin, Image, Landmark,
  Settings, FileText, ChevronLeft, ChevronRight, Loader2, X,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ───────────────────────────────────────────────────────────────────

interface WizardData {
  name: string; tradingName: string; registrationNumber: string;
  vatNumber: string; taxNumber: string;
  addressLine1: string; addressLine2: string; city: string;
  province: string; postalCode: string; country: string;
  phone: string; email: string; website: string;
  logoData: string;
  bankName: string; bankAccountNumber: string;
  bankBranchCode: string; bankAccountType: string;
  financialYearStart: number; vatPeriod: string; defaultCurrency: string;
  documents: DocFile[];
}

interface DocFile {
  type: string; name: string; data: string; mimeType: string; size: number;
}

const INITIAL: WizardData = {
  name: '', tradingName: '', registrationNumber: '', vatNumber: '', taxNumber: '',
  addressLine1: '', addressLine2: '', city: '', province: '', postalCode: '',
  country: 'South Africa', phone: '', email: '', website: '', logoData: '',
  bankName: '', bankAccountNumber: '', bankBranchCode: '', bankAccountType: 'Current',
  financialYearStart: 3, vatPeriod: 'Bi-Monthly', defaultCurrency: 'ZAR',
  documents: [],
};

const STEPS = [
  { icon: Building2, title: 'Company Details', sub: 'Tell us about your business' },
  { icon: MapPin, title: 'Address & Contact', sub: 'Where can we reach you?' },
  { icon: Image, title: 'Logo Upload', sub: 'Brand your workspace' },
  { icon: Landmark, title: 'Banking Details', sub: 'Your primary bank account' },
  { icon: Settings, title: 'Financial Preferences', sub: 'Year-end, VAT & currency' },
  { icon: FileText, title: 'Statutory Documents', sub: 'Upload key certificates' },
  { icon: Check, title: 'Review & Complete', sub: 'Confirm and get started' },
];

const PROVINCES = [
  'Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo',
  'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape',
];
const SA_BANKS = [
  'ABSA', 'Capitec', 'FNB', 'Investec', 'Nedbank', 'Standard Bank',
  'TymeBank', 'African Bank', 'Discovery Bank', 'Bank Zero',
];
const MONTHS = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
];
const DOC_SLOTS = [
  { type: 'cipc', label: 'CIPC Registration Certificate' },
  { type: 'tax_clearance', label: 'SARS Tax Clearance Certificate' },
  { type: 'bbbee', label: 'B-BBEE Certificate' },
  { type: 'vat_reg', label: 'VAT Registration Certificate' },
];

// ── Component ───────────────────────────────────────────────────────────────

export default function OnboardingWizard() {
  const router = useRouter();
  const [step, setStep] = useState(0);
  const [d, setD] = useState<WizardData>(INITIAL);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [authChecked, setAuthChecked] = useState(false);

  // Auth check
  useEffect(() => {
    apiFetch('/api/auth/me').then(async (r) => {
      if (!r.ok) { void router.replace('/login'); return; }
      const body = await r.json();
      if (body.data?.onboardingCompleted) { void router.replace('/accounting'); return; }
      setAuthChecked(true);
    }).catch(() => void router.replace('/login'));
  }, [router]);

  const set = useCallback(<K extends keyof WizardData>(k: K, v: WizardData[K]) => {
    setD(prev => ({ ...prev, [k]: v }));
  }, []);

  const canContinue = step === 0 ? d.name.trim().length > 0 : true;
  const isLast = step === STEPS.length - 1;
  const skippable = step >= 1 && step <= 5;

  const next = () => { if (canContinue) setStep(s => Math.min(s + 1, STEPS.length - 1)); };
  const back = () => setStep(s => Math.max(s - 1, 0));

  const handleSubmit = async () => {
    setSubmitting(true);
    setError('');
    try {
      // 1. Create company
      const compRes = await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: d.name, tradingName: d.tradingName,
          registrationNumber: d.registrationNumber, vatNumber: d.vatNumber,
          taxNumber: d.taxNumber, addressLine1: d.addressLine1,
          addressLine2: d.addressLine2, city: d.city, province: d.province,
          postalCode: d.postalCode, country: d.country, phone: d.phone,
          email: d.email, website: d.website, logoData: d.logoData || undefined,
          bankName: d.bankName || undefined, bankAccountNumber: d.bankAccountNumber || undefined,
          bankBranchCode: d.bankBranchCode || undefined, bankAccountType: d.bankAccountType,
          financialYearStart: d.financialYearStart, vatPeriod: d.vatPeriod,
          defaultCurrency: d.defaultCurrency,
        }),
      });
      if (!compRes.ok) throw new Error((await compRes.json()).error?.message || 'Failed to create company');
      const compData = await compRes.json();
      const companyId = compData.data?.id;

      // 2. Upload documents
      if (d.documents.length > 0 && companyId) {
        const docRes = await apiFetch('/api/onboarding/documents', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ companyId, documents: d.documents }),
        });
        if (!docRes.ok) throw new Error('Failed to upload documents');
      }

      // 3. Mark onboarding complete
      await apiFetch('/api/onboarding/complete', { method: 'POST' });

      // 4. Navigate
      void router.push('/accounting');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
      setSubmitting(false);
    }
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white px-4 py-8">
      {/* Logo */}
      <div className="max-w-2xl mx-auto mb-8">
        <img src="/logo.png" alt="ISAFlow" className="h-10 w-auto brightness-0 invert" />
      </div>

      {/* Progress */}
      <div className="max-w-2xl mx-auto mb-8">
        <div className="flex items-center justify-between">
          {STEPS.map((s, i) => (
            <div key={i} className="flex items-center flex-1 last:flex-none">
              <button
                onClick={() => i < step && setStep(i)}
                disabled={i > step}
                className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium shrink-0 transition-colors ${
                  i < step ? 'bg-teal-600 text-white cursor-pointer' :
                  i === step ? 'bg-teal-500 text-white ring-2 ring-teal-400' :
                  'bg-gray-800 text-gray-500'
                }`}
              >
                {i < step ? <Check className="w-4 h-4" /> : i + 1}
              </button>
              {i < STEPS.length - 1 && (
                <div className={`h-0.5 flex-1 mx-1 ${i < step ? 'bg-teal-600' : 'bg-gray-800'}`} />
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Card */}
      <div className="max-w-2xl mx-auto">
        <div className="mb-4">
          <h2 className="text-xl font-semibold">{STEPS[step].title}</h2>
          <p className="text-sm text-gray-400">{STEPS[step].sub}</p>
        </div>

        <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl min-h-[320px]">
          {step === 0 && <Step1 d={d} set={set} />}
          {step === 1 && <Step2 d={d} set={set} />}
          {step === 2 && <Step3 d={d} set={set} />}
          {step === 3 && <Step4 d={d} set={set} />}
          {step === 4 && <Step5 d={d} set={set} />}
          {step === 5 && <Step6 d={d} set={set} />}
          {step === 6 && <Step7 d={d} />}
        </div>

        {/* Error */}
        {error && (
          <div className="mt-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
            <p className="text-sm text-red-400">{error}</p>
          </div>
        )}

        {/* Navigation */}
        <div className="flex justify-between mt-6">
          <button
            onClick={back}
            disabled={step === 0}
            className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="w-4 h-4" /> Back
          </button>
          <div className="flex gap-3">
            {skippable && !isLast && (
              <button onClick={next} className="text-sm text-gray-400 hover:text-white transition-colors">
                Skip
              </button>
            )}
            {isLast ? (
              <button
                onClick={() => void handleSubmit()}
                disabled={submitting}
                className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 text-white font-medium text-sm px-6 py-2.5 rounded-lg transition-colors"
              >
                {submitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</> : 'Complete Setup'}
              </button>
            ) : (
              <button
                onClick={next}
                disabled={!canContinue}
                className="flex items-center gap-1.5 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-5 py-2.5 rounded-lg transition-colors"
              >
                Continue <ChevronRight className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Shared helpers ──────────────────────────────────────────────────────────

type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

const inputCls = 'w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition';
const labelCls = 'block text-xs font-medium text-gray-400 mb-1.5';

function Field({ label, value, onChange, placeholder, required, type = 'text' }: {
  label: string; value: string; onChange: (v: string) => void;
  placeholder?: string; required?: boolean; type?: string;
}) {
  return (
    <div>
      <label className={labelCls}>{label}{required && <span className="text-red-400 ml-0.5">*</span>}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)}
        placeholder={placeholder} className={inputCls} />
    </div>
  );
}

function Select({ label, value, onChange, children }: {
  label: string; value: string | number; onChange: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className={labelCls}>{label}</label>
      <select value={value} onChange={e => onChange(e.target.value)} className={inputCls}>
        {children}
      </select>
    </div>
  );
}

// ── Step Components ─────────────────────────────────────────────────────────

function Step1({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Company Name" value={d.name} onChange={v => set('name', v)} placeholder="Acme (Pty) Ltd" required />
      <Field label="Trading Name" value={d.tradingName} onChange={v => set('tradingName', v)} placeholder="Acme" />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Registration Number (CIPC)" value={d.registrationNumber} onChange={v => set('registrationNumber', v)} />
        <Field label="VAT Number" value={d.vatNumber} onChange={v => set('vatNumber', v)} />
        <Field label="Income Tax Number" value={d.taxNumber} onChange={v => set('taxNumber', v)} />
      </div>
    </div>
  );
}

function Step2({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Address Line 1" value={d.addressLine1} onChange={v => set('addressLine1', v)} />
      <Field label="Address Line 2" value={d.addressLine2} onChange={v => set('addressLine2', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="City" value={d.city} onChange={v => set('city', v)} />
        <Select label="Province" value={d.province} onChange={v => set('province', v)}>
          <option value="">Select...</option>
          {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
        </Select>
        <Field label="Postal Code" value={d.postalCode} onChange={v => set('postalCode', v)} />
      </div>
      <Field label="Country" value={d.country} onChange={v => set('country', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Phone" value={d.phone} onChange={v => set('phone', v)} type="tel" />
        <Field label="Email" value={d.email} onChange={v => set('email', v)} type="email" />
        <Field label="Website" value={d.website} onChange={v => set('website', v)} />
      </div>
    </div>
  );
}

function Step3({ d, set }: { d: WizardData; set: SetFn }) {
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return;
    if (file.size > 2 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => set('logoData', reader.result as string);
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center gap-4">
      {d.logoData ? (
        <div className="relative">
          <img src={d.logoData} alt="Logo" className="w-32 h-32 rounded-lg object-contain bg-gray-800" />
          <button onClick={() => set('logoData', '')}
            className="absolute -top-2 -right-2 bg-red-600 rounded-full p-1 hover:bg-red-500">
            <X className="w-3 h-3" />
          </button>
        </div>
      ) : (
        <div
          onDragOver={e => e.preventDefault()}
          onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) handleFile(f); }}
          className="w-full border-2 border-dashed border-gray-600 rounded-xl p-10 text-center hover:border-teal-500 transition-colors cursor-pointer"
          onClick={() => fileRef.current?.click()}
        >
          <Upload className="w-10 h-10 text-gray-500 mx-auto mb-3" />
          <p className="text-sm text-gray-400">Drag & drop your logo here, or click to browse</p>
          <p className="text-xs text-gray-500 mt-1">JPEG, PNG, or WebP. Max 2 MB</p>
        </div>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden"
        onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f); }} />
      {!d.logoData && (
        <button onClick={() => fileRef.current?.click()}
          className="text-sm text-teal-400 hover:text-teal-300 transition-colors">
          Browse files
        </button>
      )}
    </div>
  );
}

function Step4({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <div>
        <label className={labelCls}>Bank Name</label>
        <input list="sa-banks" value={d.bankName} onChange={e => set('bankName', e.target.value)}
          className={inputCls} placeholder="Select or type..." />
        <datalist id="sa-banks">
          {SA_BANKS.map(b => <option key={b} value={b} />)}
        </datalist>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <Field label="Account Number" value={d.bankAccountNumber} onChange={v => set('bankAccountNumber', v)} />
        <Field label="Branch Code" value={d.bankBranchCode} onChange={v => set('bankBranchCode', v)} />
      </div>
      <Select label="Account Type" value={d.bankAccountType} onChange={v => set('bankAccountType', v)}>
        {['Current', 'Savings', 'Transmission', 'Credit Card'].map(t =>
          <option key={t} value={t}>{t}</option>
        )}
      </Select>
    </div>
  );
}

function Step5({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Select label="Financial Year Start" value={d.financialYearStart}
        onChange={v => set('financialYearStart', parseInt(v, 10))}>
        {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
      </Select>
      <Select label="VAT Period" value={d.vatPeriod} onChange={v => set('vatPeriod', v)}>
        <option value="Monthly">Monthly</option>
        <option value="Bi-Monthly">Bi-Monthly</option>
      </Select>
      <Select label="Default Currency" value={d.defaultCurrency} onChange={v => set('defaultCurrency', v)}>
        {['ZAR', 'USD', 'EUR', 'GBP'].map(c => <option key={c} value={c}>{c}</option>)}
      </Select>
    </div>
  );
}

function Step6({ d, set }: { d: WizardData; set: SetFn }) {
  const handleDocFile = (slot: typeof DOC_SLOTS[number], file: File) => {
    if (file.size > 10 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => {
      const newDoc: DocFile = {
        type: slot.type, name: file.name,
        data: reader.result as string, mimeType: file.type, size: file.size,
      };
      set('documents', [...d.documents.filter(dd => dd.type !== slot.type), newDoc]);
    };
    reader.readAsDataURL(file);
  };

  const removeDoc = (type: string) => set('documents', d.documents.filter(dd => dd.type !== type));

  return (
    <div className="grid gap-4">
      {DOC_SLOTS.map(slot => {
        const doc = d.documents.find(dd => dd.type === slot.type);
        return (
          <div key={slot.type} className="border border-gray-700 rounded-lg p-4">
            <p className="text-sm font-medium text-gray-300 mb-2">{slot.label}</p>
            {doc ? (
              <div className="flex items-center justify-between">
                <div className="text-xs text-gray-400">
                  {doc.name} ({(doc.size / 1024).toFixed(0)} KB)
                </div>
                <button onClick={() => removeDoc(slot.type)}
                  className="text-xs text-red-400 hover:text-red-300">Remove</button>
              </div>
            ) : (
              <label className="flex items-center gap-2 cursor-pointer text-xs text-teal-400 hover:text-teal-300">
                <Upload className="w-3.5 h-3.5" /> Upload
                <input type="file" className="hidden" accept="image/*,application/pdf"
                  onChange={e => { const f = e.target.files?.[0]; if (f) handleDocFile(slot, f); }} />
              </label>
            )}
          </div>
        );
      })}
    </div>
  );
}

function Step7({ d }: { d: WizardData }) {
  const section = (title: string, items: [string, string | undefined][]) => (
    <div>
      <h3 className="text-sm font-semibold text-teal-400 mb-2">{title}</h3>
      <div className="grid gap-1">
        {items.filter(([, v]) => v).map(([k, v]) => (
          <div key={k} className="flex gap-2 text-sm">
            <span className="text-gray-500 w-36 shrink-0">{k}:</span>
            <span className="text-gray-200">{v}</span>
          </div>
        ))}
      </div>
    </div>
  );

  const addr = [d.addressLine1, d.addressLine2, d.city, d.province, d.postalCode]
    .filter(Boolean).join(', ');

  return (
    <div className="grid gap-6">
      {section('Company', [
        ['Name', d.name], ['Trading Name', d.tradingName],
        ['Registration', d.registrationNumber], ['VAT', d.vatNumber], ['Tax', d.taxNumber],
      ])}
      {section('Address & Contact', [
        ['Address', addr || undefined], ['Country', d.country],
        ['Phone', d.phone], ['Email', d.email], ['Website', d.website],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Logo</h3>
        {d.logoData ? (
          <img src={d.logoData} alt="Logo" className="w-16 h-16 rounded-lg object-contain bg-gray-800" />
        ) : (
          <p className="text-sm text-gray-500">Not uploaded</p>
        )}
      </div>
      {section('Banking', [
        ['Bank', d.bankName], ['Account', d.bankAccountNumber],
        ['Branch', d.bankBranchCode], ['Type', d.bankAccountType],
      ])}
      {section('Financial', [
        ['FY Start', MONTHS[d.financialYearStart - 1]],
        ['VAT Period', d.vatPeriod], ['Currency', d.defaultCurrency],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Documents</h3>
        {d.documents.length > 0 ? (
          <ul className="space-y-1">
            {d.documents.map(doc => (
              <li key={doc.type} className="text-sm text-gray-300">
                {DOC_SLOTS.find(s => s.type === doc.type)?.label || doc.type} — {doc.name}
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-sm text-gray-500">None uploaded</p>
        )}
      </div>
    </div>
  );
}

/**
 * /onboarding — 7-step company setup wizard.
 * Standalone layout (no AppLayout), matches login dark theme.
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Check, Upload, Building2, MapPin, Image, Landmark,
  Settings, FileText, ChevronLeft, ChevronRight, Loader2, X,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ───────────────────────────────────────────────────────────────────

interface WizardData {
  name: string; tradingName: string; registrationNumber: string;
  vatNumber: string; taxNumber: string;
  addressLine1: string; addressLine2: string; city: string;
  province: string; postalCode: string; country: string;
  phone: string; email: string; website: string;
  logoData: string;
  bankName: string; bankAccountNumber: string;
  bankBranchCode: string; bankAccountType: string;
  financialYearStart: number; vatPeriod: string; defaultCurrency: string;
  documents: DocFile[];
}

interface DocFile {
  type: string; name: string; data: string; mimeType: string; size: number;
}

const INITIAL: WizardData = {
  name: '', tradingName: '', registrationNumber: '', vatNumber: '', taxNumber: '',
  addressLine1: '', addressLine2: '', city: '', province: '', postalCode: '',
  country: 'South Africa', phone: '', email: '', website: '', logoData: '',
  bankName: '', bankAccountNumber: '', bankBranchCode: '', bankAccountType: 'Current',
  financialYearStart: 3, vatPeriod: 'Bi-Monthly', defaultCurrency: 'ZAR',
  documents: [],
};

const STEPS = [
  { icon: Building2, title: 'Company Details', sub: 'Tell us about your business' },
  { icon: MapPin, title: 'Address & Contact', sub: 'Where can we reach you?' },
  { icon: Image, title: 'Logo Upload', sub: 'Brand your workspace' },
  { icon: Landmark, title: 'Banking Details', sub: 'Your primary bank account' },
  { icon: Settings, title: 'Financial Preferences', sub: 'Year-end, VAT & currency' },
  { icon: FileText, title: 'Statutory Documents', sub: 'Upload key certificates' },
  { icon: Check, title: 'Review & Complete', sub: 'Confirm and get started' },
];

const PROVINCES = [
  'Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo',
  'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape',
];
const SA_BANKS = [
  'ABSA', 'Capitec', 'FNB', 'Investec', 'Nedbank', 'Standard Bank',
  'TymeBank', 'African Bank', 'Discovery Bank', 'Bank Zero',
];
const MONTHS = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
];
const DOC_SLOTS = [
  { type: 'cipc', label: 'CIPC Registration Certificate' },
  { type: 'tax_clearance', label: 'SARS Tax Clearance Certificate' },
  { type: 'bbbee', label: 'B-BBEE Certificate' },
  { type: 'vat_reg', label: 'VAT Registration Certificate' },
];

// ── Component ───────────────────────────────────────────────────────────────

export default function OnboardingWizard() {
  const router = useRouter();
  const [step, setStep] = useState(0);
  const [d, setD] = useState<WizardData>(INITIAL);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [authChecked, setAuthChecked] = useState(false);

  // Auth check
  useEffect(() => {
    apiFetch('/api/auth/me').then(async (r) => {
      if (!r.ok) { void router.replace('/login'); return; }
      const body = await r.json();
      if (body.data?.onboardingCompleted) { void router.replace('/accounting'); return; }
      setAuthChecked(true);
    }).catch(() => void router.replace('/login'));
  }, [router]);

  const set = useCallback(<K extends keyof WizardData>(k: K, v: WizardData[K]) => {
    setD(prev => ({ ...prev, [k]: v }));
  }, []);

  const canContinue = step === 0 ? d.name.trim().length > 0 : true;
  const isLast = step === STEPS.length - 1;
  const skippable = step >= 1 && step <= 5;

  const next = () => { if (canContinue) setStep(s => Math.min(s + 1, STEPS.length - 1)); };
  const back = () => setStep(s => Math.max(s - 1, 0));

  const handleSubmit = async () => {
    setSubmitting(true);
    setError('');
    try {
      // 1. Create company
      const compRes = await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: d.name, tradingName: d.tradingName,
          registrationNumber: d.registrationNumber, vatNumber: d.vatNumber,
          taxNumber: d.taxNumber, addressLine1: d.addressLine1,
          addressLine2: d.addressLine2, city: d.city, province: d.province,
          postalCode: d.postalCode, country: d.country, phone: d.phone,
          email: d.email, website: d.website, logoData: d.logoData || undefined,
          bankName: d.bankName || undefined, bankAccountNumber: d.bankAccountNumber || undefined,
          bankBranchCode: d.bankBranchCode || undefined, bankAccountType: d.bankAccountType,
          financialYearStart: d.financialYearStart, vatPeriod: d.vatPeriod,
          defaultCurrency: d.defaultCurrency,
        }),
      });
      if (!compRes.ok) throw new Error((await compRes.json()).error?.message || 'Failed to create company');
      const compData = await compRes.json();
      const companyId = compData.data?.id;

      // 2. Upload documents
      if (d.documents.length > 0 && companyId) {
        const docRes = await apiFetch('/api/onboarding/documents', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ companyId, documents: d.documents }),
        });
        if (!docRes.ok) throw new Error('Failed to upload documents');
      }

      // 3. Mark onboarding complete
      await apiFetch('/api/onboarding/complete', { method: 'POST' });

      // 4. Navigate
      void router.push('/accounting');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
      setSubmitting(false);
    }
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white px-4 py-8">
      {/* Logo */}
      <div className="max-w-2xl mx-auto mb-8">
        <img src="/logo.png" alt="ISAFlow" className="h-10 w-auto brightness-0 invert" />
      </div>

      {/* Progress */}
      <div className="max-w-2xl mx-auto mb-8">
        <div className="flex items-center justify-between">
          {STEPS.map((s, i) => (
            <div key={i} className="flex items-center flex-1 last:flex-none">
              <button
                onClick={() => i < step && setStep(i)}
                disabled={i > step}
                className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium shrink-0 transition-colors ${
                  i < step ? 'bg-teal-600 text-white cursor-pointer' :
                  i === step ? 'bg-teal-500 text-white ring-2 ring-teal-400' :
                  'bg-gray-800 text-gray-500'
                }`}
              >
                {i < step ? <Check className="w-4 h-4" /> : i + 1}
              </button>
              {i < STEPS.length - 1 && (
                <div className={`h-0.5 flex-1 mx-1 ${i < step ? 'bg-teal-600' : 'bg-gray-800'}`} />
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Card */}
      <div className="max-w-2xl mx-auto">
        <div className="mb-4">
          <h2 className="text-xl font-semibold">{STEPS[step].title}</h2>
          <p className="text-sm text-gray-400">{STEPS[step].sub}</p>
        </div>

        <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl min-h-[320px]">
          {step === 0 && <Step1 d={d} set={set} />}
          {step === 1 && <Step2 d={d} set={set} />}
          {step === 2 && <Step3 d={d} set={set} />}
          {step === 3 && <Step4 d={d} set={set} />}
          {step === 4 && <Step5 d={d} set={set} />}
          {step === 5 && <Step6 d={d} set={set} />}
          {step === 6 && <Step7 d={d} />}
        </div>

        {/* Error */}
        {error && (
          <div className="mt-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
            <p className="text-sm text-red-400">{error}</p>
          </div>
        )}

        {/* Navigation */}
        <div className="flex justify-between mt-6">
          <button
            onClick={back}
            disabled={step === 0}
            className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="w-4 h-4" /> Back
          </button>
          <div className="flex gap-3">
            {skippable && !isLast && (
              <button onClick={next} className="text-sm text-gray-400 hover:text-white transition-colors">
                Skip
              </button>
            )}
            {isLast ? (
              <button
                onClick={() => void handleSubmit()}
                disabled={submitting}
                className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 text-white font-medium text-sm px-6 py-2.5 rounded-lg transition-colors"
              >
                {submitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</> : 'Complete Setup'}
              </button>
            ) : (
              <button
                onClick={next}
                disabled={!canContinue}
                className="flex items-center gap-1.5 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-5 py-2.5 rounded-lg transition-colors"
              >
                Continue <ChevronRight className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Shared helpers ──────────────────────────────────────────────────────────

type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

const inputCls = 'w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition';
const labelCls = 'block text-xs font-medium text-gray-400 mb-1.5';

function Field({ label, value, onChange, placeholder, required, type = 'text' }: {
  label: string; value: string; onChange: (v: string) => void;
  placeholder?: string; required?: boolean; type?: string;
}) {
  return (
    <div>
      <label className={labelCls}>{label}{required && <span className="text-red-400 ml-0.5">*</span>}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)}
        placeholder={placeholder} className={inputCls} />
    </div>
  );
}

function Select({ label, value, onChange, children }: {
  label: string; value: string | number; onChange: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className={labelCls}>{label}</label>
      <select value={value} onChange={e => onChange(e.target.value)} className={inputCls}>
        {children}
      </select>
    </div>
  );
}

// ── Step Components ─────────────────────────────────────────────────────────

function Step1({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Company Name" value={d.name} onChange={v => set('name', v)} placeholder="Acme (Pty) Ltd" required />
      <Field label="Trading Name" value={d.tradingName} onChange={v => set('tradingName', v)} placeholder="Acme" />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Registration Number (CIPC)" value={d.registrationNumber} onChange={v => set('registrationNumber', v)} />
        <Field label="VAT Number" value={d.vatNumber} onChange={v => set('vatNumber', v)} />
        <Field label="Income Tax Number" value={d.taxNumber} onChange={v => set('taxNumber', v)} />
      </div>
    </div>
  );
}

function Step2({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Address Line 1" value={d.addressLine1} onChange={v => set('addressLine1', v)} />
      <Field label="Address Line 2" value={d.addressLine2} onChange={v => set('addressLine2', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="City" value={d.city} onChange={v => set('city', v)} />
        <Select label="Province" value={d.province} onChange={v => set('province', v)}>
          <option value="">Select...</option>
          {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
        </Select>
        <Field label="Postal Code" value={d.postalCode} onChange={v => set('postalCode', v)} />
      </div>
      <Field label="Country" value={d.country} onChange={v => set('country', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Phone" value={d.phone} onChange={v => set('phone', v)} type="tel" />
        <Field label="Email" value={d.email} onChange={v => set('email', v)} type="email" />
        <Field label="Website" value={d.website} onChange={v => set('website', v)} />
      </div>
    </div>
  );
}

function Step3({ d, set }: { d: WizardData; set: SetFn }) {
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return;
    if (file.size > 2 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => set('logoData', reader.result as string);
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center gap-4">
      {d.logoData ? (
        <div className="relative">
          <img src={d.logoData} alt="Logo" className="w-32 h-32 rounded-lg object-contain bg-gray-800" />
          <button onClick={() => set('logoData', '')}
            className="absolute -top-2 -right-2 bg-red-600 rounded-full p-1 hover:bg-red-500">
            <X className="w-3 h-3" />
          </button>
        </div>
      ) : (
        <div
          onDragOver={e => e.preventDefault()}
          onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) handleFile(f); }}
          className="w-full border-2 border-dashed border-gray-600 rounded-xl p-10 text-center hover:border-teal-500 transition-colors cursor-pointer"
          onClick={() => fileRef.current?.click()}
        >
          <Upload className="w-10 h-10 text-gray-500 mx-auto mb-3" />
          <p className="text-sm text-gray-400">Drag & drop your logo here, or click to browse</p>
          <p className="text-xs text-gray-500 mt-1">JPEG, PNG, or WebP. Max 2 MB</p>
        </div>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden"
        onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f); }} />
      {!d.logoData && (
        <button onClick={() => fileRef.current?.click()}
          className="text-sm text-teal-400 hover:text-teal-300 transition-colors">
          Browse files
        </button>
      )}
    </div>
  );
}

function Step4({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <div>
        <label className={labelCls}>Bank Name</label>
        <input list="sa-banks" value={d.bankName} onChange={e => set('bankName', e.target.value)}
          className={inputCls} placeholder="Select or type..." />
        <datalist id="sa-banks">
          {SA_BANKS.map(b => <option key={b} value={b} />)}
        </datalist>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <Field label="Account Number" value={d.bankAccountNumber} onChange={v => set('bankAccountNumber', v)} />
        <Field label="Branch Code" value={d.bankBranchCode} onChange={v => set('bankBranchCode', v)} />
      </div>
      <Select label="Account Type" value={d.bankAccountType} onChange={v => set('bankAccountType', v)}>
        {['Current', 'Savings', 'Transmission', 'Credit Card'].map(t =>
          <option key={t} value={t}>{t}</option>
        )}
      </Select>
    </div>
  );
}

function Step5({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Select label="Financial Year Start" value={d.financialYearStart}
        onChange={v => set('financialYearStart', parseInt(v, 10))}>
        {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
      </Select>
      <Select label="VAT Period" value={d.vatPeriod} onChange={v => set('vatPeriod', v)}>
        <option value="Monthly">Monthly</option>
        <option value="Bi-Monthly">Bi-Monthly</option>
      </Select>
      <Select label="Default Currency" value={d.defaultCurrency} onChange={v => set('defaultCurrency', v)}>
        {['ZAR', 'USD', 'EUR', 'GBP'].map(c => <option key={c} value={c}>{c}</option>)}
      </Select>
    </div>
  );
}

function Step6({ d, set }: { d: WizardData; set: SetFn }) {
  const handleDocFile = (slot: typeof DOC_SLOTS[number], file: File) => {
    if (file.size > 10 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => {
      const newDoc: DocFile = {
        type: slot.type, name: file.name,
        data: reader.result as string, mimeType: file.type, size: file.size,
      };
      set('documents', [...d.documents.filter(dd => dd.type !== slot.type), newDoc]);
    };
    reader.readAsDataURL(file);
  };

  const removeDoc = (type: string) => set('documents', d.documents.filter(dd => dd.type !== type));

  return (
    <div className="grid gap-4">
      {DOC_SLOTS.map(slot => {
        const doc = d.documents.find(dd => dd.type === slot.type);
        return (
          <div key={slot.type} className="border border-gray-700 rounded-lg p-4">
            <p className="text-sm font-medium text-gray-300 mb-2">{slot.label}</p>
            {doc ? (
              <div className="flex items-center justify-between">
                <div className="text-xs text-gray-400">
                  {doc.name} ({(doc.size / 1024).toFixed(0)} KB)
                </div>
                <button onClick={() => removeDoc(slot.type)}
                  className="text-xs text-red-400 hover:text-red-300">Remove</button>
              </div>
            ) : (
              <label className="flex items-center gap-2 cursor-pointer text-xs text-teal-400 hover:text-teal-300">
                <Upload className="w-3.5 h-3.5" /> Upload
                <input type="file" className="hidden" accept="image/*,application/pdf"
                  onChange={e => { const f = e.target.files?.[0]; if (f) handleDocFile(slot, f); }} />
              </label>
            )}
          </div>
        );
      })}
    </div>
  );
}

function Step7({ d }: { d: WizardData }) {
  const section = (title: string, items: [string, string | undefined][]) => (
    <div>
      <h3 className="text-sm font-semibold text-teal-400 mb-2">{title}</h3>
      <div className="grid gap-1">
        {items.filter(([, v]) => v).map(([k, v]) => (
          <div key={k} className="flex gap-2 text-sm">
            <span className="text-gray-500 w-36 shrink-0">{k}:</span>
            <span className="text-gray-200">{v}</span>
          </div>
        ))}
      </div>
    </div>
  );

  const addr = [d.addressLine1, d.addressLine2, d.city, d.province, d.postalCode]
    .filter(Boolean).join(', ');

  return (
    <div className="grid gap-6">
      {section('Company', [
        ['Name', d.name], ['Trading Name', d.tradingName],
        ['Registration', d.registrationNumber], ['VAT', d.vatNumber], ['Tax', d.taxNumber],
      ])}
      {section('Address & Contact', [
        ['Address', addr || undefined], ['Country', d.country],
        ['Phone', d.phone], ['Email', d.email], ['Website', d.website],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Logo</h3>
        {d.logoData ? (
          <img src={d.logoData} alt="Logo" className="w-16 h-16 rounded-lg object-contain bg-gray-800" />
        ) : (
          <p className="text-sm text-gray-500">Not uploaded</p>
        )}
      </div>
      {section('Banking', [
        ['Bank', d.bankName], ['Account', d.bankAccountNumber],
        ['Branch', d.bankBranchCode], ['Type', d.bankAccountType],
      ])}
      {section('Financial', [
        ['FY Start', MONTHS[d.financialYearStart - 1]],
        ['VAT Period', d.vatPeriod], ['Currency', d.defaultCurrency],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Documents</h3>
        {d.documents.length > 0 ? (
          <ul className="space-y-1">
            {d.documents.map(doc => (
              <li key={doc.type} className="text-sm text-gray-300">
                {DOC_SLOTS.find(s => s.type === doc.type)?.label || doc.type} — {doc.name}
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-sm text-gray-500">None uploaded</p>
        )}
      </div>
    </div>
  );
}

