    description: 'Motor vehicles used for business purposes',
  },
  furniture: {
    rate: 16.67,
    years: 6,
    description: 'Office furniture, desks, chairs, shelving',
  },
  office_equipment: {
    rate: 20,
    years: 5,
    description: 'Printers, copiers, telephones, fax machines',
  },
  buildings: {
    rate: 5,
    years: 20,
    description: 'Commercial buildings and improvements',
  },
  machinery: {
    rate: 12.5,
    years: 8,
    description: 'General machinery and plant equipment',
  },
  manufacturing_equipment: {
    rate: 25,
    years: 4,
    description: 'Manufacturing plant and equipment (Section 12C)',
  },
  small_tools: {
    rate: 50,
    years: 2,
    description: 'Small tools, implements, and utensils',
  },
  aircraft: {
    rate: 25,
    years: 4,
    description: 'Aircraft used for business purposes',
  },
  electronic_equipment: {
    rate: 25,
    years: 4,
    description: 'Electronic equipment, servers, networking gear',
  },
  signage: {
    rate: 10,
    years: 10,
    description: 'Business signage, billboards, displays',
  },
  leasehold_improvements: {
    rate: 20,
    years: 5,
    description: 'Leasehold improvements (or lease term if shorter)',
  },
} as const;

// ═══════════════════════════════════════════════════════════════════════════
// ASSET NUMBER GENERATION
// ═══════════════════════════════════════════════════════════════════════════

const CATEGORY_PREFIXES: Record<string, string> = {
  computers: 'COMP',
  motor_vehicles: 'VEHI',
  furniture: 'FURN',
  office_equipment: 'OFEQ',
  buildings: 'BLDG',
  machinery: 'MACH',
  manufacturing_equipment: 'MFEQ',
  small_tools: 'TOOL',
  aircraft: 'AIRC',
  electronic_equipment: 'ELEC',
  signage: 'SIGN',
  leasehold_improvements: 'LSIM',
};

export function generateAssetNumber(category: string, existingCount: number): string {
  const prefix = CATEGORY_PREFIXES[category] || 'ASST';
  const seq = String(existingCount + 1).padStart(4, '0');
  return `${prefix}-${seq}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// DEPRECIATION CALCULATIONS
// ═══════════════════════════════════════════════════════════════════════════

interface CalcInput {
  cost: number;
  salvageValue: number;
  usefulLifeYears: number;
  monthsElapsed: number;
  accumulatedDepreciation?: number;
}

export function calculateStraightLine(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, monthsElapsed, accumulatedDepreciation } = input;

  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'straight_line', remainingMonths: 0 };
  }

  const totalMonths = usefulLifeYears * 12;
  const remainingMonths = Math.max(0, totalMonths - monthsElapsed);

  if (remainingMonths <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'straight_line', remainingMonths: 0 };
  }

  const depreciableAmount = cost - salvageValue;
  const annualDep = depreciableAmount / usefulLifeYears;
  const annualRate = (annualDep / cost) * 100;
  let monthlyDep = Math.round((annualDep / 12) * 100) / 100;

  // Cap at remaining depreciable amount
  if (accumulatedDepreciation !== undefined) {
    const remaining = depreciableAmount - accumulatedDepreciation;
    if (remaining <= 0) {
      return { monthlyAmount: 0, annualAmount: 0, annualRate, method: 'straight_line', remainingMonths: 0 };
    }
    monthlyDep = Math.min(monthlyDep, Math.round(remaining * 100) / 100);
  }

  return {
    monthlyAmount: monthlyDep,
    annualAmount: Math.round(annualDep * 100) / 100,
    annualRate: Math.round(annualRate * 100) / 100,
    method: 'straight_line',
    remainingMonths,
  };
}

export function calculateReducingBalance(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, accumulatedDepreciation } = input;

  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'reducing_balance', remainingMonths: 0 };
  }

  const rate = 2 / usefulLifeYears; // Double declining rate
  const annualRate = rate * 100;
  const accum = accumulatedDepreciation ?? 0;
  const bookValue = cost - accum;
  const maxDepreciable = bookValue - salvageValue;

  if (maxDepreciable <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate, method: 'reducing_balance', remainingMonths: 0 };
  }

  const annualDep = bookValue * rate;
  let monthlyDep = Math.round((annualDep / 12) * 100) / 100;

  // Don't exceed remaining depreciable amount
  monthlyDep = Math.min(monthlyDep, Math.round(maxDepreciable * 100) / 100);

  const remainingMonths = monthlyDep > 0 ? Math.ceil(maxDepreciable / monthlyDep) : 0;

  return {
    monthlyAmount: monthlyDep,
    annualAmount: Math.round(annualDep * 100) / 100,
    annualRate: Math.round(annualRate * 100) / 100,
    method: 'reducing_balance',
    remainingMonths,
  };
}

export function calculateSumOfYears(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, monthsElapsed } = input;

  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'sum_of_years', remainingMonths: 0 };
  }

  const currentYear = Math.floor(monthsElapsed / 12) + 1;
  const totalMonths = usefulLifeYears * 12;
  const remainingMonths = Math.max(0, totalMonths - monthsElapsed);

  if (currentYear > usefulLifeYears || remainingMonths <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'sum_of_years', remainingMonths: 0 };
  }

  // Sum of years digits: n*(n+1)/2
  const sumOfDigits = (usefulLifeYears * (usefulLifeYears + 1)) / 2;
  const remainingYears = usefulLifeYears - currentYear + 1;
  const fraction = remainingYears / sumOfDigits;

  const depreciableAmount = cost - salvageValue;
  const annualDep = depreciableAmount * fraction;
  const monthlyDep = Math.round((annualDep / 12) * 100) / 100;
  const annualRate = Math.round((annualDep / cost) * 100 * 100) / 100;

  return {
    monthlyAmount: monthlyDep,
    annualAmount: Math.round(annualDep * 100) / 100,
    annualRate,
    method: 'sum_of_years',
    remainingMonths,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// DISPATCHER
// ═══════════════════════════════════════════════════════════════════════════

export function calculateDepreciation(input: DepreciationInput): DepreciationResult {
  const calcInput: CalcInput = {
    cost: input.cost,
    salvageValue: input.salvageValue,
    usefulLifeYears: input.usefulLifeYears,
    monthsElapsed: input.monthsElapsed,
    accumulatedDepreciation: input.accumulatedDepreciation,
  };

  switch (input.method) {
    case 'reducing_balance':
      return calculateReducingBalance(calcInput);
    case 'sum_of_years':
      return calculateSumOfYears(calcInput);
    case 'straight_line':
    default:
      return calculateStraightLine(calcInput);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

const VALID_DEPRECIATION_METHODS: DepreciationMethod[] = ['straight_line', 'reducing_balance', 'sum_of_years'];
const VALID_STATUSES: AssetStatus[] = ['available', 'assigned', 'in_maintenance', 'disposed', 'written_off'];
const VALID_DISPOSAL_METHODS: DisposalMethod[] = ['sale', 'scrap', 'write_off', 'donation', 'theft', 'insurance_claim'];

export function validateAsset(input: AssetInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];

  if (!input.name || input.name.trim() === '') {
    errors.push({ field: 'name', message: 'Asset name is required' });
  }

  if (input.cost === undefined || input.cost === null || input.cost <= 0) {
    errors.push({ field: 'cost', message: 'Cost must be greater than zero' });
  }

  if (input.salvageValue !== undefined && input.salvageValue > input.cost) {
    errors.push({ field: 'salvageValue', message: 'Salvage value cannot exceed cost' });
  }

  if (!input.usefulLifeYears || input.usefulLifeYears <= 0) {
    errors.push({ field: 'usefulLifeYears', message: 'Useful life must be greater than zero' });
  }

  if (input.depreciationMethod && !VALID_DEPRECIATION_METHODS.includes(input.depreciationMethod as DepreciationMethod)) {
    errors.push({ field: 'depreciationMethod', message: 'Invalid depreciation method' });
  }

  if (input.status && !VALID_STATUSES.includes(input.status as AssetStatus)) {
    errors.push({ field: 'status', message: 'Invalid asset status' });
  }

  // Date validation
  if (input.purchaseDate) {
    const parsed = new Date(input.purchaseDate);
    if (isNaN(parsed.getTime())) {
      errors.push({ field: 'purchaseDate', message: 'Invalid date format' });
    } else {
      const today = new Date();
      today.setHours(23, 59, 59, 999);
      if (parsed > today) {
        errors.push({ field: 'purchaseDate', message: 'Purchase date cannot be in the future' });
      }
    }
  }

  return {
    success: errors.length === 0,
    ...(errors.length > 0 ? { errors } : {}),
  };
}

export function validateDisposal(input: DisposalInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];

  if (!input.assetId || input.assetId.trim() === '') {
    errors.push({ field: 'assetId', message: 'Asset ID is required' });
  }

  if (input.disposalAmount < 0) {
    errors.push({ field: 'disposalAmount', message: 'Disposal amount cannot be negative' });
  }

  if (!input.reason || input.reason.trim() === '') {
    errors.push({ field: 'reason', message: 'Disposal reason is required' });
  }

  if (input.disposalMethod && !VALID_DISPOSAL_METHODS.includes(input.disposalMethod as DisposalMethod)) {
    errors.push({ field: 'disposalMethod', message: 'Invalid disposal method' });
  }

  if (input.disposalDate) {
    const parsed = new Date(input.disposalDate);
    if (isNaN(parsed.getTime())) {
      errors.push({ field: 'disposalDate', message: 'Invalid date format' });
    }
  }

  return {
    success: errors.length === 0,
    ...(errors.length > 0 ? { errors } : {}),
  };
}

