export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

// ── Company CRUD ─────────────────────────────────────────────────────────────

export async function listCompanies(): Promise<Company[]> {
  const rows = (await sql`SELECT * FROM companies WHERE is_active = true ORDER BY name`) as Row[];
  return rows.map(mapCompany);
}

export async function getCompany(id: string): Promise<Company | null> {
  const rows = (await sql`SELECT * FROM companies WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapCompany(rows[0]) : null;
}

export async function createCompany(input: {
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  email?: string;
  phone?: string;
  website?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  defaultCurrency?: string;
}, userId: string): Promise<Company> {
  const rows = (await sql`
    INSERT INTO companies (
      name, trading_name, registration_number, vat_number, tax_number,
      email, phone, website,
      address_line1, address_line2, city, province, postal_code, country,
      logo_data,
      bank_name, bank_account_number, bank_branch_code, bank_account_type,
      financial_year_start, vat_period, default_currency
    ) VALUES (
      ${input.name}, ${input.tradingName || null}, ${input.registrationNumber || null},
      ${input.vatNumber || null}, ${input.taxNumber || null}, ${input.email || null}, ${input.phone || null},
      ${input.website || null},
      ${input.addressLine1 || null}, ${input.addressLine2 || null}, ${input.city || null},
      ${input.province || null}, ${input.postalCode || null}, ${input.country || 'South Africa'},
      ${input.logoData || null},
      ${input.bankName || null}, ${input.bankAccountNumber || null}, ${input.bankBranchCode || null},
      ${input.bankAccountType || 'current'},
      ${input.financialYearStart ?? 3}, ${input.vatPeriod || 'bi-monthly'}, ${input.defaultCurrency || 'ZAR'}
    ) RETURNING *
  `) as Row[];

  // Auto-assign creator as owner
  await sql`
    INSERT INTO company_users (company_id, user_id, role, is_default)
    VALUES (${rows[0].id}::UUID, ${userId}, 'owner', false)
  `;

  log.info('Company created', { id: rows[0].id, name: input.name }, 'accounting');
  return mapCompany(rows[0]);
}

export async function updateCompany(id: string, input: Partial<Record<string, unknown>>): Promise<Company> {
  // Map camelCase keys to snake_case column names
  const fieldMap: Record<string, string> = {
    name: 'name', tradingName: 'trading_name', registrationNumber: 'registration_number',
    vatNumber: 'vat_number', taxNumber: 'tax_number',
    addressLine1: 'address_line1', addressLine2: 'address_line2',
    city: 'city', province: 'province', postalCode: 'postal_code', country: 'country',
    phone: 'phone', email: 'email', website: 'website', logoData: 'logo_data',
    bankName: 'bank_name', bankAccountNumber: 'bank_account_number',
    bankBranchCode: 'bank_branch_code', bankAccountType: 'bank_account_type',
    financialYearStart: 'financial_year_start', vatPeriod: 'vat_period', defaultCurrency: 'default_currency',
    // New fields
    lockdownEnabled: 'lockdown_enabled', lockdownDate: 'lockdown_date',
    vatSystemType: 'vat_system_type',
    entityType: 'entity_type', registeredName: 'registered_name', taxOffice: 'tax_office',
    contactName: 'contact_name', fax: 'fax', mobile: 'mobile',
    physicalAddressLine1: 'physical_address_line1', physicalAddressLine2: 'physical_address_line2',
    physicalCity: 'physical_city', physicalProvince: 'physical_province', physicalPostalCode: 'physical_postal_code',
    taxPractitionerRegNumber: 'tax_practitioner_reg_number', taxPractitionerName: 'tax_practitioner_name',
    sarsContactFirstName: 'sars_contact_first_name', sarsContactLastName: 'sars_contact_last_name',
    sarsContactCapacity: 'sars_contact_capacity', sarsContactNumber: 'sars_contact_number', sarsContactTelephone: 'sars_contact_telephone',
    logoPosition: 'logo_position', logoOnEmails: 'logo_on_emails', logoOnPortal: 'logo_on_portal',
    roundingType: 'rounding_type', roundToNearest: 'round_to_nearest',
    qtyDecimalPlaces: 'qty_decimal_places', valueDecimalPlaces: 'value_decimal_places',
    hoursDecimalPlaces: 'hours_decimal_places', costPriceDecimalPlaces: 'cost_price_decimal_places',
    sellingPriceDecimalPlaces: 'selling_price_decimal_places', currencySymbol: 'currency_symbol', dateFormat: 'date_format',
    emailUseForCommunication: 'email_use_for_communication', emailAlwaysCc: 'email_always_cc', emailUseServiceFrom: 'email_use_service_from',
    warnDuplicateCustomerRef: 'warn_duplicate_customer_ref', warnDuplicateSupplierInv: 'warn_duplicate_supplier_inv',
    displayInactiveCustomersProcessing: 'display_inactive_customers_processing', displayInactiveSuppliersProcessing: 'display_inactive_suppliers_processing',
    displayInactiveCustomersReports: 'display_inactive_customers_reports', displayInactiveSuppliersReports: 'display_inactive_suppliers_reports',
    useInclusiveProcessing: 'use_inclusive_processing', useAccountDefaultLineType: 'use_account_default_line_type',
    warnItemQtyBelowZero: 'warn_item_qty_below_zero', blockItemQtyBelowZero: 'block_item_qty_below_zero',
    warnItemCostZero: 'warn_item_cost_zero', warnItemSellingBelowCost: 'warn_item_selling_below_cost',
    displayInactiveItemsProcessing: 'display_inactive_items_processing', displayInactiveItemsReports: 'display_inactive_items_reports',
    salesOrdersReserveQty: 'sales_orders_reserve_qty', displayInactiveBundles: 'display_inactive_bundles',
    ageingMonthly: 'ageing_monthly', ageingBasedOn: 'ageing_based_on',
  };

  // Build SET clauses dynamically
  const setClauses: string[] = [];
  const values: unknown[] = [];
  let paramIdx = 1;

  for (const [camel, snake] of Object.entries(fieldMap)) {
    if (camel in input && input[camel] !== undefined) {
      setClauses.push(`${snake} = $${paramIdx}`);
      values.push(input[camel] === '' ? null : input[camel]);
      paramIdx++;
    }
  }

  if (setClauses.length === 0) {
    const existing = await getCompany(id);
    if (!existing) throw new Error(`Company ${id} not found`);
    return existing;
  }

  setClauses.push('updated_at = NOW()');
  values.push(id);

  const query = `UPDATE companies SET ${setClauses.join(', ')} WHERE id = $${paramIdx}::UUID RETURNING *`;
  const rows = (await sql(query, values)) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId} AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({
    companyId: r.company_id,
    companyName: r.company_name,
    role: r.role,
    isDefault: r.is_default,
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await sql`UPDATE company_users SET is_default = false WHERE user_id = ${userId}`;
  await sql`UPDATE company_users SET is_default = true WHERE user_id = ${userId} AND company_id = ${companyId}::UUID`;
}

export async function addUserToCompany(companyId: string, userId: string, role = 'user'): Promise<void> {
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${companyId}::UUID, ${userId}, ${role})
    ON CONFLICT (company_id, user_id) DO UPDATE SET role = ${role}
  `;
}

export async function removeUserFromCompany(companyId: string, userId: string): Promise<void> {
  await sql`DELETE FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}`;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Row): Company {
  return {
    id: r.id,
    name: r.name,
    tradingName: r.trading_name,
    registrationNumber: r.registration_number,
    vatNumber: r.vat_number,
    taxNumber: r.tax_number,
    addressLine1: r.address_line1,
    addressLine2: r.address_line2,
    city: r.city,
    province: r.province,
    postalCode: r.postal_code,
    country: r.country,
    phone: r.phone,
    email: r.email,
    website: r.website,
    logoUrl: r.logo_url,
    logoData: r.logo_data || null,
    bankName: r.bank_name,
    bankAccountNumber: r.bank_account_number,
    bankBranchCode: r.bank_branch_code,
    bankAccountType: r.bank_account_type,
    financialYearStart: r.financial_year_start,
    vatPeriod: r.vat_period,
    defaultCurrency: r.default_currency,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

