  setClauses.push('updated_at = NOW()');
  values.push(id);

  const query = `UPDATE companies SET ${setClauses.join(', ')} WHERE id = $${paramIdx}::UUID RETURNING *`;
  const rows = (await sql(query, values)) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

