/**
 * Next.js Edge Middleware
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects unauthenticated /accounting/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const PUBLIC_PATHS = ['/login', '/register', '/api/auth/login', '/api/auth/logout', '/api/auth/register', '/onboarding', '/api/onboarding'];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  // Allow public paths, static files, and API routes
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && pathname.startsWith('/accounting')) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/', '/accounting/:path*', '/onboarding/:path*'],
};

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
  compress: true,
  output: 'standalone',

  experimental: {
    optimizePackageImports: ['lucide-react'],
  },

  // Security headers
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          { key: 'X-Frame-Options', value: 'DENY' },
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
          { key: 'X-DNS-Prefetch-Control', value: 'on' },
        ],
      },
    ];
  },

  // Webpack config
  webpack: (config, { isServer }) => {
    if (!isServer) {
      config.resolve.fallback = {
        ...config.resolve.fallback,
        fs: false,
        net: false,
        tls: false,
        crypto: false,
      };
    }
    return config;
  },
};

module.exports = nextConfig;

import pg from 'pg';
import { readFileSync } from 'fs';
import { join } from 'path';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('ERROR: DATABASE_URL environment variable is required.');
  process.exit(1);
}

const client = new pg.Client({ connectionString: DATABASE_URL });

const migrations = [
  '000_users_and_auth.sql',
  '200_accounting_foundation.sql',
  '201_accounts_payable.sql',
  '202_accounts_receivable.sql',
  '203_bank_reconciliation.sql',
  '204_financial_reporting.sql',
  '205_sage_migration.sql',
  '206_phase1_sage_alignment.sql',
  '210_vat201_data_model.sql',
  '211_schema_patches.sql',
  '212_smart_categorization.sql',
  '220_multi_company_scoping.sql',
  '230_payroll.sql',
  '231_sars_efiling.sql',
  '232_invoice_emails.sql',
  '233_document_capture.sql',
  '234_approval_workflows.sql',
  '235_client_portal.sql',
  '236_multi_entity.sql',
  '237_bank_feeds.sql',
  '240_group_companies.sql',
  '241_time_tracking.sql',
  '242_payment_gateway.sql',
  '243_onboarding.sql',
  '244_fixed_assets.sql',
  '245_inventory.sql',
];

async function runMigrations() {
  console.log('=== Accounting Database Migration ===\n');

  await client.connect();
  console.log('Connected to database.\n');

  for (const migration of migrations) {
    const filePath = join(process.cwd(), 'scripts/migrations/sql', migration);
    try {
      const sqlContent = readFileSync(filePath, 'utf-8');
      console.log(`Running: ${migration}`);
      await client.query(sqlContent);
      console.log(`  ✓ Done\n`);
    } catch (error) {
      console.error(`  ✗ Failed: ${error.message}\n`);
    }
  }

  // Seed admin user
  console.log('Seeding admin user...');
  try {
    const bcrypt = await import('bcryptjs');
    const hash = await bcrypt.hash('admin123', 12);
    await client.query(`
      INSERT INTO users (id, email, password_hash, first_name, last_name, role, permissions, is_active)
      VALUES ($1, $2, $3, $4, $5, $6, $7::JSONB, $8)
      ON CONFLICT (email) DO NOTHING
    `, ['admin-001', 'admin@accounting.local', hash, 'Admin', 'User', 'super_admin', '["*"]', true]);
    console.log('  ✓ Admin user seeded (admin@accounting.local / admin123)\n');
  } catch (error) {
    console.error(`  ✗ Seed failed: ${error.message}\n`);
  }

  // Verify
  console.log('Verifying tables...');
  const result = await client.query(`
    SELECT tablename FROM pg_tables
    WHERE schemaname = 'public'
    ORDER BY tablename
  `);
  console.log(`  Found ${result.rows.length} tables:`);
  result.rows.forEach(t => console.log(`    - ${t.tablename}`));

  await client.end();
  console.log('\n=== Migration complete ===');
}

runMigrations().catch(err => {
  console.error('Fatal error:', err);
  client.end();
  process.exit(1);
});

