/**
 * Assets API — CRUD for Fixed Assets
 * GET: list assets (with filters)
 * POST: create new asset
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateAsset, generateAssetNumber, type AssetInput } from '@/modules/accounting/services/assetService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { status, category, search } = req.query;

    let rows: Row[];

    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE (a.name ILIKE ${term} OR a.asset_number ILIKE ${term} OR a.serial_number ILIKE ${term})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all' && category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.status = ${String(status)} AND (a.category = ${String(category)} OR ac.code = ${String(category)})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all') {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.status = ${String(status)}
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.category = ${String(category)} OR ac.code = ${String(category)}
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    }

    return apiResponse.success(res, rows);

/**
 * Items API — CRUD for inventory / service items
 * GET:    list items (with filters) or single item (?id=UUID)
 * POST:   create new item
 * PUT:    update existing item
 * DELETE: soft-delete (set is_active = false)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const companyId = req.companyId;

  /* ------------------------------------------------------------------ */
  /*  GET — list items or fetch single item                             */
  /* ------------------------------------------------------------------ */
  if (req.method === 'GET') {
    const { id, q, type, active, category_id } = req.query;

    // Single item by id
    if (id) {
      const rows = await sql`
        SELECT i.*, ic.name AS category_name
        FROM items i
        LEFT JOIN item_categories ic ON i.category_id = ic.id
        WHERE i.id = ${String(id)} AND i.company_id = ${companyId}
        LIMIT 1
      ` as Row[];

      if (rows.length === 0) {
        return apiResponse.notFound(res, 'Item', String(id));
      }
      return apiResponse.success(res, rows[0]);
    }

    // Build dynamic conditions
    const conditions: string[] = ['i.company_id = $1'];
    const params: unknown[] = [companyId];
    let paramIdx = 1;

    if (q) {
      paramIdx++;
      const term = `%${String(q)}%`;
      conditions.push(`(i.code ILIKE $${paramIdx} OR i.description ILIKE $${paramIdx})`);
      params.push(term);
    }

    if (type && (type === 'physical' || type === 'service')) {
      paramIdx++;
      conditions.push(`i.item_type = $${paramIdx}`);
      params.push(String(type));
    }

    if (active === 'true') {
      conditions.push('i.is_active = true');
    } else if (active === 'false') {
      conditions.push('i.is_active = false');
    }

    if (category_id) {
      paramIdx++;
      conditions.push(`i.category_id = $${paramIdx}::UUID`);
      params.push(String(category_id));
    }

    // Use tagged template for the common case (no dynamic filters beyond company)
    // For complex filtering we fall back to raw query building.
