import { NextApiRequest, NextApiResponse } from 'next';
import { apiLogger } from '@/lib/logger';

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  success: false;
  data: null;
  message: string;
  code?: string;
  details?: Record<string, unknown>;
}

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  message?: string;
}

export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Wraps an API handler with error handling
 * Generic R extends NextApiRequest to support AuthenticatedNextApiRequest
 */
export function withErrorHandler<T = unknown, R extends NextApiRequest = NextApiRequest>(
  handler: (req: R, res: NextApiResponse<ApiResponse<T>>) => Promise<void>
) {
  return async (req: R, res: NextApiResponse<ApiResponse<T>>) => {
    const startTime = Date.now();

    try {
      // Set CORS headers - restrict to known origins
      const allowedOrigins = [
        'https://fin.fibreflow.app',
        ...(process.env.NODE_ENV === 'development'
          ? ['http://localhost:3101', 'http://localhost:3004']
          : []),
      ];
      const origin = req.headers.origin;
      if (origin && allowedOrigins.includes(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      }

      // Handle OPTIONS request for CORS
      if (req.method === 'OPTIONS') {
        return res.status(200).end();
      }

      // Log incoming request
      apiLogger.info({
        type: 'request',
        method: req.method,
        url: req.url,
        query: req.query,
        body: req.method !== 'GET' ? req.body : undefined,
      }, `API Request: ${req.method} ${req.url}`);

      // Execute the actual handler
      await handler(req, res);

      // Log successful response
      const duration = Date.now() - startTime;
      apiLogger.info({
        type: 'response',
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
      }, `API Response: ${req.method} ${req.url} - ${res.statusCode} (${duration}ms)`);

    } catch (error) {
      const duration = Date.now() - startTime;

      // Log error with context
      apiLogger.error({
        type: 'error',
        method: req.method,
        url: req.url,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
        duration: `${duration}ms`,
      });

      // Check if headers were already sent
      if (res.headersSent) {
        apiLogger.warn({ method: req.method, url: req.url }, 'Headers already sent, cannot send error response');
        return;
      }

      // Send error response — mask internal details in production
      const errorMessage =
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : error instanceof Error ? error.message : 'An unexpected error occurred';

      res.status(500).json({
        success: false,
        data: null,
        message: errorMessage,
        code: 'INTERNAL_SERVER_ERROR',
        ...(process.env.NODE_ENV === 'development' && {
          details: error instanceof Error ? {
            message: error.message,
            stack: error.stack,
          } as Record<string, unknown> : { error: String(error) },
        }),
      });
    }
  };
}

/**
 * Creates a standard success response
 */
export function successResponse<T>(data: T, message?: string): ApiSuccessResponse<T> {
  return {
    success: true,
    data,
    ...(message && { message }),
  };
}

/**
 * Creates a standard error response
 */
export function errorResponse(
  message: string,
  code?: string,
  details?: Record<string, unknown>
): ApiErrorResponse {
  return {
    success: false,
    data: null,
    message,
    ...(code && { code }),
    ...(details && process.env.NODE_ENV === 'development' && { details }),
  };
}

/**
 * Common HTTP error responses
 */
export const HttpErrors = {
  BadRequest: (message = 'Bad Request') =>
    errorResponse(message, 'BAD_REQUEST'),

  Unauthorized: (message = 'Unauthorized') =>
    errorResponse(message, 'UNAUTHORIZED'),

  Forbidden: (message = 'Forbidden') =>
    errorResponse(message, 'FORBIDDEN'),

  NotFound: (message = 'Not Found') =>
    errorResponse(message, 'NOT_FOUND'),

  MethodNotAllowed: (method: string) =>
    errorResponse(`Method ${method} not allowed`, 'METHOD_NOT_ALLOWED'),

  InternalServerError: (message = 'Internal Server Error') =>
    errorResponse(message, 'INTERNAL_SERVER_ERROR'),

  DatabaseError: (message = 'Database operation failed') =>
    errorResponse(message, 'DATABASE_ERROR'),

  ValidationError: (message = 'Validation failed', details?: Record<string, unknown>) =>
    errorResponse(message, 'VALIDATION_ERROR', details),
};

/**
 * Products API — CRUD for inventory items
 * GET: list products, POST: create product
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateProduct, generateProductCode, type ProductInput } from '@/modules/accounting/services/inventoryService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { search, category, type, active } = req.query;
    let rows: Row[];
    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE (p.name ILIKE ${term} OR p.code ILIKE ${term} OR p.barcode ILIKE ${term}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (category) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.category = ${String(category)} OR pc.code = ${String(category)} ORDER BY p.name LIMIT 200` as Row[];
    } else if (type) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.product_type = ${String(type)} ORDER BY p.name LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.is_active = true ORDER BY p.name LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }
  if (req.method === 'POST') {
    const body = req.body as ProductInput;
    const validation = validateProduct(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));
    let categoryId: string | null = null;
    if (body.category) {
      const cats = await sql`SELECT id FROM product_categories WHERE code = ${body.category} LIMIT 1` as Row[];
      if (cats[0]) categoryId = String(cats[0].id);
    }
    const code = body.code || generateProductCode(body.category || 'general', 0);
    const inserted = await sql`
      INSERT INTO products (code, name, description, category_id, category, barcode, unit, product_type, cost_price, selling_price, cost_method, tax_rate, reorder_level, reorder_quantity, created_by)
      VALUES (${code}, ${body.name}, ${body.description || null}, ${categoryId}, ${body.category || null}, ${body.barcode || null}, ${body.unit || 'each'}, ${body.type || 'inventory'}, ${body.costPrice || 0}, ${body.sellingPrice || 0}, ${body.costMethod || 'weighted_average'}, ${body.taxRate || 15}, ${body.reorderLevel || 0}, ${body.reorderQuantity || 0}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];
    log.info('Product created', { code, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler as any));

/**
 * Assets API — CRUD for Fixed Assets
 * GET: list assets (with filters)
 * POST: create new asset
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateAsset, generateAssetNumber, type AssetInput } from '@/modules/accounting/services/assetService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { status, category, search } = req.query;

    let rows: Row[];

    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE (a.name ILIKE ${term} OR a.asset_number ILIKE ${term} OR a.serial_number ILIKE ${term})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all' && category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.status = ${String(status)} AND (a.category = ${String(category)} OR ac.code = ${String(category)})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all') {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.status = ${String(status)}
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.category = ${String(category)} OR ac.code = ${String(category)}
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    }

    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body as AssetInput;

    const validation = validateAsset(body);
    if (!validation.success) {
      return apiResponse.validationError(res,
        Object.fromEntries((validation.errors || []).map(e => [e.field, e.message]))
      );
    }

    let categoryId: string | null = null;
    let sarsRate: number | null = null;
    let taxLife: number | null = null;

    if (body.sarsCategory || body.category) {
      const catCode = body.sarsCategory || body.category;
      const cats = await sql`
        SELECT id, sars_rate, sars_years FROM asset_categories WHERE code = ${catCode} LIMIT 1
      ` as Row[];
      if (cats[0]) {
        categoryId = String(cats[0].id);
        sarsRate = Number(cats[0].sars_rate);
        taxLife = Number(cats[0].sars_years);
      }
    }

    const catKey = body.category || body.sarsCategory || 'general';
    const countResult = await sql`
      SELECT COUNT(*) as cnt FROM assets WHERE category = ${catKey}
    ` as Row[];
    const existingCount = Number((countResult[0] as any)?.cnt || 0);
    const assetNumber = generateAssetNumber(body.sarsCategory || body.category || 'general', existingCount);

    const inserted = await sql`
      INSERT INTO assets (
        asset_number, name, description, category_id, category,
        serial_number, location, purchase_date, purchase_price,
        salvage_value, useful_life_years, depreciation_method,
        sars_category, sars_rate, tax_useful_life_years, tax_depreciation_method,
        status, created_by
      ) VALUES (
        ${assetNumber}, ${body.name}, ${body.description || null},
        ${categoryId}, ${catKey},
        ${(body as any).serialNumber || null}, ${body.location || null},
        ${body.purchaseDate}, ${body.cost},
        ${body.salvageValue || 0}, ${body.usefulLifeYears}, ${body.depreciationMethod || 'straight_line'},
        ${body.sarsCategory || null}, ${sarsRate}, ${taxLife}, ${'straight_line'},
        ${body.status || 'available'}, ${String(req.user.id)}
      ) RETURNING *
    ` as Row[];

    log.info('Asset created', { assetNumber, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Stock Adjustments API — increase/decrease/write-off stock
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateStockAdjustment } from '@/modules/accounting/services/inventoryService';
type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const adjustments = await sql`
      SELECT sa.*, p.code as product_code, p.name as product_name
      FROM stock_adjustments sa JOIN products p ON sa.product_id = p.id
      ORDER BY sa.created_at DESC LIMIT 200
    ` as Row[];
    return apiResponse.success(res, adjustments);
  }
  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateStockAdjustment(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const countRes = await sql`SELECT COUNT(*) as cnt FROM stock_adjustments` as Row[];
    const adjNum = `ADJ-${String(Number((countRes[0] as any)?.cnt || 0) + 1).padStart(5, '0')}`;

    const inserted = await sql`
      INSERT INTO stock_adjustments (adjustment_number, product_id, warehouse_id, adjustment_type, quantity, unit_cost, reason, created_by)
      VALUES (${adjNum}, ${body.productId}, ${body.warehouseId || null}, ${body.adjustmentType}, ${body.quantity}, ${body.unitCost || 0}, ${body.reason}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    // Update product stock
    const sign = ['increase', 'count'].includes(body.adjustmentType) ? 1 : -1;
    await sql`UPDATE products SET current_stock = GREATEST(0, current_stock + ${sign * body.quantity}), updated_at = NOW() WHERE id = ${body.productId}`;

    // Record movement
    const movementType = body.adjustmentType === 'increase' ? 'adjustment_in' : body.adjustmentType === 'write_off' ? 'write_off' : 'adjustment_out';
    await sql`INSERT INTO stock_movements (product_id, warehouse_id, movement_type, quantity, unit_cost, total_cost, reference_type, reference_id, created_by) VALUES (${body.productId}, ${body.warehouseId || null}, ${movementType}, ${body.quantity}, ${body.unitCost || 0}, ${(body.unitCost || 0) * body.quantity}, 'stock_adjustment', ${String(inserted[0]?.id)}, ${String(req.user.id)})`;

    log.info('Stock adjusted', { adjNum, type: body.adjustmentType, qty: body.quantity }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler as any));

