/**
 * Payslip PDF API
 * GET /api/payroll/payslip-pdf?id=xxx  - Generate PDF payslip
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { id } = req.query;
  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Payslip ID is required');
  }

  try {
    // Get payslip with employee and run data
    const rows = (await sql`
      SELECT ps.*, e.employee_number, e.first_name, e.last_name,
        e.id_number, e.tax_number, e.department, e.position,
        e.bank_name, e.bank_account_number, e.bank_branch_code,
        pr.period_start, pr.period_end
      FROM payslips ps
      JOIN employees e ON e.id = ps.employee_id
      JOIN payroll_runs pr ON pr.id = ps.payroll_run_id
      WHERE ps.id = ${id}
    `) as Row[];

    if (rows.length === 0 || !rows[0]) {
      return apiResponse.notFound(res, 'Payslip', id);
    }

    const slip = rows[0] as Row;

    // Generate PDF using jsPDF
    const { jsPDF } = await import('jspdf');
    const doc = new jsPDF();

    const pageWidth = doc.internal.pageSize.getWidth();
    const margin = 20;
    let y = 20;

    // Company header
    doc.setFontSize(18);
    doc.setFont('helvetica', 'bold');
    doc.text('PAYSLIP', pageWidth / 2, y, { align: 'center' });
    y += 10;

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(
      `Pay Period: ${formatDate(slip.period_start)} - ${formatDate(slip.period_end)}`,
      pageWidth / 2, y, { align: 'center' }
    );
    y += 15;

    // Divider
    doc.setDrawColor(0, 128, 128);
    doc.setLineWidth(0.5);
    doc.line(margin, y, pageWidth - margin, y);
    y += 10;

    // Employee details
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.text('Employee Details', margin, y);
    y += 7;

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const empDetails = [
      ['Employee Number', String(slip.employee_number)],
      ['Name', `${slip.first_name} ${slip.last_name}`],
      ['ID Number', slip.id_number || '-'],
      ['Tax Number', slip.tax_number || '-'],
      ['Department', slip.department || '-'],
      ['Position', slip.position || '-'],
    ];

    for (const [label, value] of empDetails) {
      doc.setFont('helvetica', 'bold');
      doc.text(`${label}:`, margin, y);
      doc.setFont('helvetica', 'normal');
      doc.text(String(value), margin + 45, y);
      y += 5;
    }
    y += 5;

    // Divider
    doc.line(margin, y, pageWidth - margin, y);
    y += 10;

    // Earnings
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.text('Earnings', margin, y);
    doc.text('Amount (R)', pageWidth - margin, y, { align: 'right' });
    y += 7;

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const earnings = [
      ['Basic Salary', Number(slip.basic_salary)],
      ['Travel Allowance', Number(slip.travel_allowance)],
      ['Housing Allowance', Number(slip.housing_allowance)],
      ['Cell Allowance', Number(slip.cell_allowance)],
      ['Other Allowances', Number(slip.other_allowances)],
    ];

    for (const [label, amount] of earnings) {
      if (Number(amount) > 0) {
        doc.text(String(label), margin, y);
        doc.text(formatCurrency(Number(amount)), pageWidth - margin, y, { align: 'right' });
        y += 5;
      }
    }

    y += 2;
    doc.setFont('helvetica', 'bold');
    doc.text('Gross Pay', margin, y);
    doc.text(formatCurrency(Number(slip.gross_pay)), pageWidth - margin, y, { align: 'right' });
    y += 8;

    // Divider
    doc.line(margin, y, pageWidth - margin, y);
    y += 10;

    // Deductions
    doc.setFontSize(11);
    doc.text('Deductions', margin, y);
    doc.text('Amount (R)', pageWidth - margin, y, { align: 'right' });
    y += 7;

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const deductions = [
      ['PAYE (Income Tax)', Number(slip.paye)],
      ['UIF (Employee)', Number(slip.uif_employee)],
      ['Medical Aid', Number(slip.medical_aid)],
      ['Retirement Fund', Number(slip.retirement_fund)],
      ['Other Deductions', Number(slip.other_deductions)],
    ];

    for (const [label, amount] of deductions) {
      if (Number(amount) > 0) {
        doc.text(String(label), margin, y);
        doc.text(formatCurrency(Number(amount)), pageWidth - margin, y, { align: 'right' });
        y += 5;
      }
    }

    y += 2;
    doc.setFont('helvetica', 'bold');
    doc.text('Total Deductions', margin, y);
    doc.text(formatCurrency(Number(slip.total_deductions)), pageWidth - margin, y, { align: 'right' });
    y += 10;

    // Net Pay
    doc.setDrawColor(0, 128, 128);
    doc.setFillColor(240, 253, 250);
    doc.rect(margin, y - 2, pageWidth - 2 * margin, 12, 'F');
    doc.setFontSize(12);
    doc.text('NET PAY', margin + 5, y + 6);
    doc.text(`R ${formatCurrency(Number(slip.net_pay))}`, pageWidth - margin - 5, y + 6, { align: 'right' });
    y += 18;

    // Employer costs
    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.text('Employer Contributions:', margin, y);
    y += 5;
    doc.text(`UIF (Employer): R ${formatCurrency(Number(slip.uif_employer))}`, margin + 5, y);
    y += 5;
    doc.text(`SDL: R ${formatCurrency(Number(slip.sdl))}`, margin + 5, y);
    y += 10;

    // YTD
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.text('Year-to-Date', margin, y);
    y += 7;

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.text(`YTD Gross: R ${formatCurrency(Number(slip.ytd_gross))}`, margin, y);
    y += 5;
    doc.text(`YTD PAYE: R ${formatCurrency(Number(slip.ytd_paye))}`, margin, y);
    y += 5;
    doc.text(`YTD UIF: R ${formatCurrency(Number(slip.ytd_uif))}`, margin, y);
    y += 10;

    // Banking details
    if (slip.bank_name) {
      doc.setFontSize(9);
      doc.setFont('helvetica', 'bold');
      doc.text('Banking Details:', margin, y);
      y += 5;
      doc.setFont('helvetica', 'normal');
      doc.text(`Bank: ${slip.bank_name}`, margin, y);
      y += 5;
      doc.text(`Account: ${slip.bank_account_number || '-'}`, margin, y);
      y += 5;
      doc.text(`Branch Code: ${slip.bank_branch_code || '-'}`, margin, y);
    }

    // Output PDF
    const pdfBuffer = Buffer.from(doc.output('arraybuffer'));
    const filename = `payslip_${slip.employee_number}_${slip.period_start}_${slip.period_end}.pdf`;

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.setHeader('Content-Length', pdfBuffer.length);
    res.status(200).end(pdfBuffer);
  } catch (err) {
    log.error('payslip PDF generation failed', { id, error: err }, 'payroll-api');
    return apiResponse.internalError(res, err, 'Failed to generate payslip PDF');
  }
}

function formatCurrency(amount: number): string {
  return amount.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatDate(dateStr: string): string {
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * KPI Dashboard Service
 * Real-time financial KPIs from the general ledger, invoices, and bank accounts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ───────────────────────────────────────────────────────────────────

export interface DashboardKPIs {
  revenue: { total: number; priorTotal: number; changePercent: number };
  expenses: { total: number; priorTotal: number };
  grossProfit: { amount: number; margin: number };
  netProfit: { amount: number; margin: number };
  cash: { total: number; priorTotal: number; change: number };
  receivables: { total: number; overdue: number; avgDebtorDays: number };
  payables: { total: number; overdue: number; avgCreditorDays: number };
  activity: { invoicesIssued: number; paymentsReceived: number; journalsPosted: number };
}

export interface ChartPoint {
  month: string;
  revenue: number;
  expenses: number;
}

export interface CashFlowPoint {
  month: string;
  inflows: number;
  outflows: number;
}

export interface AgingBreakdownBucket {
  name: string;
  value: number;
}

export interface TopCustomer {
  name: string;
  revenue: number;
  invoiceCount: number;
}

export interface TopExpenseCategory {
  accountName: string;
  total: number;
  percentOfExpenses: number;
}

// ── Dashboard KPIs ──────────────────────────────────────────────────────────

export async function getDashboardKPIs(companyId: string,
  fromDate: string,
  toDate: string
): Promise<DashboardKPIs> {
  try {
    // Calculate prior period (same duration before fromDate)
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const durationMs = to.getTime() - from.getTime();
    const priorFrom = new Date(from.getTime() - durationMs);
    const priorFromStr = priorFrom.toISOString().slice(0, 10);
    const priorToStr = new Date(from.getTime() - 86400000).toISOString().slice(0, 10);

    const [
      revenueRows,
      priorRevenueRows,
      expenseRows,
      priorExpenseRows,
      cashRows,
      priorCashRows,
      arRows,
      arOverdueRows,
      arDebtorDaysRows,
      apRows,
      apOverdueRows,
      apCreditorDaysRows,
      invoicesIssuedRows,
      paymentsReceivedRows,
      journalsPostedRows,
    ] = await Promise.all([
      // Current period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current cash position (sum of all bank account balances from transactions)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
      `,
      // Prior period cash (transactions up to prior period end)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
          AND bt.transaction_date <= ${priorToStr}
      `,
      // AR total outstanding
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
      `,
      // AR overdue
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
          AND due_date < CURRENT_DATE
      `,
      // Average debtor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_date, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM customer_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // AP total outstanding
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
      `,
      // AP overdue
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
          AND due_date < CURRENT_DATE
      `,
      // Average creditor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_date, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM supplier_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // Invoices issued this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate} AND invoice_date <= ${toDate}
          AND status NOT IN ('cancelled', 'draft')
      `,
      // Payments received this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND paid_date >= ${fromDate} AND paid_date <= ${toDate}
      `,
      // Journal entries posted this period
      sql`
        SELECT COUNT(*) AS count
        FROM gl_journal_entries
        WHERE company_id = ${companyId}::UUID
          AND status = 'posted'
          AND entry_date >= ${fromDate} AND entry_date <= ${toDate}
      `,
    ]);

    const totalRevenue = Number((revenueRows as Row[])[0]?.total || 0);
    const priorRevenue = Number((priorRevenueRows as Row[])[0]?.total || 0);
    const totalExpenses = Number((expenseRows as Row[])[0]?.total || 0);
    const priorExpenses = Number((priorExpenseRows as Row[])[0]?.total || 0);
    const cashTotal = Number((cashRows as Row[])[0]?.total || 0);
    const priorCash = Number((priorCashRows as Row[])[0]?.total || 0);

    const grossProfit = totalRevenue - totalExpenses;
    const grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
    const revenueChange = priorRevenue > 0
      ? ((totalRevenue - priorRevenue) / priorRevenue) * 100
      : totalRevenue > 0 ? 100 : 0;

    return {
      revenue: { total: totalRevenue, priorTotal: priorRevenue, changePercent: revenueChange },
      expenses: { total: totalExpenses, priorTotal: priorExpenses },
      grossProfit: { amount: grossProfit, margin: grossMargin },
      netProfit: { amount: grossProfit, margin: grossMargin },
      cash: { total: cashTotal, priorTotal: priorCash, change: cashTotal - priorCash },
      receivables: {
        total: Number((arRows as Row[])[0]?.total || 0),
        overdue: Number((arOverdueRows as Row[])[0]?.total || 0),
        avgDebtorDays: Math.round(Number((arDebtorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      payables: {
        total: Number((apRows as Row[])[0]?.total || 0),
        overdue: Number((apOverdueRows as Row[])[0]?.total || 0),
        avgCreditorDays: Math.round(Number((apCreditorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      activity: {
        invoicesIssued: Number((invoicesIssuedRows as Row[])[0]?.count || 0),
        paymentsReceived: Number((paymentsReceivedRows as Row[])[0]?.count || 0),
        journalsPosted: Number((journalsPostedRows as Row[])[0]?.count || 0),
      },
    };
  } catch (err) {
    log.error('Failed to get dashboard KPIs', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Revenue Chart ───────────────────────────────────────────────────────────

export async function getRevenueChart(companyId: string, months: number): Promise<ChartPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
        COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
      FROM months m
      LEFT JOIN gl_journal_entries je
        ON je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= m.month_start
        AND je.entry_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        AND ga.account_type IN ('revenue', 'expense')
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      revenue: Math.abs(Number(r.revenue || 0)),
      expenses: Math.abs(Number(r.expenses || 0)),
    }));
  } catch (err) {
    log.error('Failed to get revenue chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Cash Flow Chart ─────────────────────────────────────────────────────────

export async function getCashFlowChart(companyId: string, months: number): Promise<CashFlowPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0) AS inflows,
        COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS outflows
      FROM months m
      LEFT JOIN bank_transactions bt
        ON bt.company_id = ${companyId}::UUID
        AND bt.transaction_date >= m.month_start
        AND bt.transaction_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        AND ga.account_subtype = 'bank' AND ga.is_active = true
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      inflows: Number(r.inflows || 0),
      outflows: Number(r.outflows || 0),
    }));
  } catch (err) {
    log.error('Failed to get cash flow chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Aging Breakdown ─────────────────────────────────────────────────────────

export async function getAgingBreakdown(companyId: string, type: 'ar' | 'ap'): Promise<AgingBreakdownBucket[]> {
  try {
    let rows: Row[];

    if (type === 'ar') {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
        GROUP BY bucket
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND balance > 0
        GROUP BY bucket
      `) as Row[];
    }

    // Ensure all buckets exist in correct order
    const bucketOrder = ['Current', '30 Days', '60 Days', '90+ Days'];
    const bucketMap = new Map<string, number>();
    for (const b of bucketOrder) bucketMap.set(b, 0);
    for (const r of rows) {
      bucketMap.set(String(r.bucket), Number(r.total || 0));
    }

    return bucketOrder.map(name => ({ name, value: bucketMap.get(name) || 0 }));
  } catch (err) {
    log.error('Failed to get aging breakdown', { error: err, type }, 'kpi-service');
    throw err;
  }
}

// ── Top Customers ───────────────────────────────────────────────────────────

export async function getTopCustomers(_companyId: string, limit: number): Promise<TopCustomer[]> {
  try {
    const rows = (await sql`
      SELECT c.company_name AS name,
        COALESCE(SUM(ci.total_amount), 0) AS revenue,
        COUNT(ci.id) AS invoice_count
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.status NOT IN ('cancelled', 'draft')
      GROUP BY c.id, c.company_name
      ORDER BY revenue DESC
      LIMIT ${limit}
    `) as Row[];

    return rows.map((r: Row) => ({
      name: String(r.name),
      revenue: Number(r.revenue || 0),
      invoiceCount: Number(r.invoice_count || 0),
    }));
  } catch (err) {
    log.error('Failed to get top customers', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Top Expense Categories ──────────────────────────────────────────────────

export async function getTopExpenseCategories(_companyId: string, limit: number): Promise<TopExpenseCategory[]> {
  try {
    const rows = (await sql`
      SELECT ga.account_name,
        COALESCE(SUM(jl.debit - jl.credit), 0) AS total
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE ga.account_type = 'expense' AND je.status = 'posted'
      GROUP BY ga.id, ga.account_name
      HAVING SUM(jl.debit - jl.credit) > 0
      ORDER BY total DESC
      LIMIT ${limit}
    `) as Row[];

    const totalExpenses = rows.reduce((s: number, r: Row) => s + Number(r.total || 0), 0);

    return rows.map((r: Row) => {
      const total = Number(r.total || 0);
      return {
        accountName: String(r.account_name),
        total,
        percentOfExpenses: totalExpenses > 0 ? (total / totalExpenses) * 100 : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get top expense categories', { error: err }, 'kpi-service');
    throw err;
  }
}

/**
 * Payroll Employees API
 * GET  /api/payroll/employees  - List employees with pay structures
 * POST /api/payroll/employees  - Create a new employee
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { listEmployees, createEmployee } from '@/modules/payroll/payrollService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { q, status } = req.query;
      const employees = await listEmployees(
        companyId,
        typeof q === 'string' ? q : undefined,
        typeof status === 'string' ? status : undefined
      );
      return apiResponse.success(res, employees);
    } catch (err) {
      log.error('payroll employees GET failed', { error: err }, 'payroll-api');
      return apiResponse.internalError(res, err, 'Failed to fetch employees');
    }
  }

  if (req.method === 'POST') {
    try {
      const {
        employee_number, first_name, last_name, id_number, tax_number,
        start_date, termination_date, bank_name, bank_account_number,
        bank_branch_code, department, position, employment_type,
        pay_frequency, status: empStatus, basic_salary, travel_allowance,
        housing_allowance, cell_allowance, other_allowances,
        medical_aid_contribution, retirement_fund_contribution_pct,
        custom_deductions,
      } = req.body;

      if (!employee_number?.trim()) {
        return apiResponse.badRequest(res, 'Employee number is required');
      }
      if (!first_name?.trim()) {
        return apiResponse.badRequest(res, 'First name is required');
      }
      if (!last_name?.trim()) {
        return apiResponse.badRequest(res, 'Last name is required');
      }
      if (!start_date) {
        return apiResponse.badRequest(res, 'Start date is required');
      }
      if (basic_salary === undefined || basic_salary === null) {
        return apiResponse.badRequest(res, 'Basic salary is required');
      }

      const employee = await createEmployee({
        employee_number: employee_number.trim(),
        first_name: first_name.trim(),
        last_name: last_name.trim(),
        id_number: id_number?.trim() || undefined,
        tax_number: tax_number?.trim() || undefined,
        start_date,
        termination_date: termination_date || undefined,
        bank_name: bank_name?.trim() || undefined,
        bank_account_number: bank_account_number?.trim() || undefined,
        bank_branch_code: bank_branch_code?.trim() || undefined,
        department: department?.trim() || undefined,
        position: position?.trim() || undefined,
        employment_type: employment_type || 'permanent',
        pay_frequency: pay_frequency || 'monthly',
        status: empStatus || 'active',
        basic_salary: Number(basic_salary),
        travel_allowance: Number(travel_allowance || 0),
        housing_allowance: Number(housing_allowance || 0),
        cell_allowance: Number(cell_allowance || 0),
        other_allowances: Number(other_allowances || 0),
        medical_aid_contribution: Number(medical_aid_contribution || 0),
        retirement_fund_contribution_pct: Number(retirement_fund_contribution_pct || 0),
        custom_deductions: custom_deductions || [],
      });

      return apiResponse.created(res, employee);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create employee';
      log.error('payroll employees POST failed', { error: err }, 'payroll-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

