        ${input.last_name},
        ${input.id_number || null},
        ${input.tax_number || null},
        ${input.start_date},
        ${input.termination_date || null},
        ${input.bank_name || null},
        ${input.bank_account_number || null},
        ${input.bank_branch_code || null},
        ${input.department || null},
        ${input.position || null},
        ${input.employment_type || 'permanent'},
