/**
 * KPI Dashboard Service
 * Real-time financial KPIs from the general ledger, invoices, and bank accounts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ───────────────────────────────────────────────────────────────────

export interface DashboardKPIs {
  revenue: { total: number; priorTotal: number; changePercent: number };
  expenses: { total: number; priorTotal: number };
  grossProfit: { amount: number; margin: number };
  netProfit: { amount: number; margin: number };
  cash: { total: number; priorTotal: number; change: number };
  receivables: { total: number; overdue: number; avgDebtorDays: number };
  payables: { total: number; overdue: number; avgCreditorDays: number };
  activity: { invoicesIssued: number; paymentsReceived: number; journalsPosted: number };
}

export interface ChartPoint {
  month: string;
  revenue: number;
  expenses: number;
}

export interface CashFlowPoint {
  month: string;
  inflows: number;
  outflows: number;
}

export interface AgingBreakdownBucket {
  name: string;
  value: number;
}

export interface TopCustomer {
  name: string;
  revenue: number;
  invoiceCount: number;
}

export interface TopExpenseCategory {
  accountName: string;
  total: number;
  percentOfExpenses: number;
}

// ── Dashboard KPIs ──────────────────────────────────────────────────────────

export async function getDashboardKPIs(companyId: string,
  fromDate: string,
  toDate: string
): Promise<DashboardKPIs> {
  try {
    // Calculate prior period (same duration before fromDate)
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const durationMs = to.getTime() - from.getTime();
    const priorFrom = new Date(from.getTime() - durationMs);
    const priorFromStr = priorFrom.toISOString().slice(0, 10);
    const priorToStr = new Date(from.getTime() - 86400000).toISOString().slice(0, 10);

    const [
      revenueRows,
      priorRevenueRows,
      expenseRows,
      priorExpenseRows,
      cashRows,
      priorCashRows,
      arRows,
      arOverdueRows,
      arDebtorDaysRows,
      apRows,
      apOverdueRows,
      apCreditorDaysRows,
      invoicesIssuedRows,
      paymentsReceivedRows,
      journalsPostedRows,
    ] = await Promise.all([
      // Current period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current cash position (sum of all bank account balances from transactions)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
      `,
      // Prior period cash (transactions up to prior period end)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
          AND bt.transaction_date <= ${priorToStr}
      `,
      // AR total outstanding
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
      `,
      // AR overdue
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
          AND due_date < CURRENT_DATE
      `,
      // Average debtor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_date, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM customer_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // AP total outstanding
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
      `,
      // AP overdue
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
          AND due_date < CURRENT_DATE
      `,
      // Average creditor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_date, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM supplier_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // Invoices issued this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate} AND invoice_date <= ${toDate}
          AND status NOT IN ('cancelled', 'draft')
      `,
      // Payments received this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND paid_date >= ${fromDate} AND paid_date <= ${toDate}
      `,
      // Journal entries posted this period
      sql`
        SELECT COUNT(*) AS count
        FROM gl_journal_entries
        WHERE company_id = ${companyId}::UUID
          AND status = 'posted'
          AND entry_date >= ${fromDate} AND entry_date <= ${toDate}
      `,
    ]);

    const totalRevenue = Number((revenueRows as Row[])[0]?.total || 0);
    const priorRevenue = Number((priorRevenueRows as Row[])[0]?.total || 0);
    const totalExpenses = Number((expenseRows as Row[])[0]?.total || 0);
    const priorExpenses = Number((priorExpenseRows as Row[])[0]?.total || 0);
    const cashTotal = Number((cashRows as Row[])[0]?.total || 0);
    const priorCash = Number((priorCashRows as Row[])[0]?.total || 0);

    const grossProfit = totalRevenue - totalExpenses;
    const grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
    const revenueChange = priorRevenue > 0
      ? ((totalRevenue - priorRevenue) / priorRevenue) * 100
      : totalRevenue > 0 ? 100 : 0;

    return {
      revenue: { total: totalRevenue, priorTotal: priorRevenue, changePercent: revenueChange },
      expenses: { total: totalExpenses, priorTotal: priorExpenses },
      grossProfit: { amount: grossProfit, margin: grossMargin },
      netProfit: { amount: grossProfit, margin: grossMargin },
      cash: { total: cashTotal, priorTotal: priorCash, change: cashTotal - priorCash },
      receivables: {
        total: Number((arRows as Row[])[0]?.total || 0),
        overdue: Number((arOverdueRows as Row[])[0]?.total || 0),
        avgDebtorDays: Math.round(Number((arDebtorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      payables: {
        total: Number((apRows as Row[])[0]?.total || 0),
        overdue: Number((apOverdueRows as Row[])[0]?.total || 0),
        avgCreditorDays: Math.round(Number((apCreditorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      activity: {
        invoicesIssued: Number((invoicesIssuedRows as Row[])[0]?.count || 0),
        paymentsReceived: Number((paymentsReceivedRows as Row[])[0]?.count || 0),
        journalsPosted: Number((journalsPostedRows as Row[])[0]?.count || 0),
      },
    };
  } catch (err) {
    log.error('Failed to get dashboard KPIs', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Revenue Chart ───────────────────────────────────────────────────────────

export async function getRevenueChart(companyId: string, months: number): Promise<ChartPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
        COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
      FROM months m
      LEFT JOIN gl_journal_entries je
        ON je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= m.month_start
        AND je.entry_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        AND ga.account_type IN ('revenue', 'expense')
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      revenue: Math.abs(Number(r.revenue || 0)),
      expenses: Math.abs(Number(r.expenses || 0)),
    }));
  } catch (err) {
    log.error('Failed to get revenue chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Cash Flow Chart ─────────────────────────────────────────────────────────

export async function getCashFlowChart(companyId: string, months: number): Promise<CashFlowPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0) AS inflows,
        COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS outflows
      FROM months m
      LEFT JOIN bank_transactions bt
        ON bt.company_id = ${companyId}::UUID
        AND bt.transaction_date >= m.month_start
        AND bt.transaction_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        AND ga.account_subtype = 'bank' AND ga.is_active = true
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      inflows: Number(r.inflows || 0),
      outflows: Number(r.outflows || 0),
    }));
  } catch (err) {
    log.error('Failed to get cash flow chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Aging Breakdown ─────────────────────────────────────────────────────────

export async function getAgingBreakdown(companyId: string, type: 'ar' | 'ap'): Promise<AgingBreakdownBucket[]> {
  try {
    let rows: Row[];

    if (type === 'ar') {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
        GROUP BY bucket
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
        GROUP BY bucket
      `) as Row[];
    }

    // Ensure all buckets exist in correct order
    const bucketOrder = ['Current', '30 Days', '60 Days', '90+ Days'];
    const bucketMap = new Map<string, number>();
    for (const b of bucketOrder) bucketMap.set(b, 0);
    for (const r of rows) {
      bucketMap.set(String(r.bucket), Number(r.total || 0));
    }

    return bucketOrder.map(name => ({ name, value: bucketMap.get(name) || 0 }));
  } catch (err) {
    log.error('Failed to get aging breakdown', { error: err, type }, 'kpi-service');
    throw err;
  }
}

// ── Top Customers ───────────────────────────────────────────────────────────

export async function getTopCustomers(companyId: string, limit: number): Promise<TopCustomer[]> {
  try {
    const rows = (await sql`
      SELECT c.company_name AS name,
        COALESCE(SUM(ci.total_amount), 0) AS revenue,
        COUNT(ci.id) AS invoice_count
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.status NOT IN ('cancelled', 'draft')
        AND ci.company_id = ${companyId}::UUID
      GROUP BY c.id, c.company_name
      ORDER BY revenue DESC
      LIMIT ${limit}
    `) as Row[];

    return rows.map((r: Row) => ({
      name: String(r.name),
      revenue: Number(r.revenue || 0),
      invoiceCount: Number(r.invoice_count || 0),
    }));
  } catch (err) {
    log.error('Failed to get top customers', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Top Expense Categories ──────────────────────────────────────────────────

export async function getTopExpenseCategories(companyId: string, limit: number): Promise<TopExpenseCategory[]> {
  try {
    const rows = (await sql`
      SELECT ga.account_name,
        COALESCE(SUM(jl.debit - jl.credit), 0) AS total
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE ga.account_type = 'expense' AND je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
      GROUP BY ga.id, ga.account_name
      HAVING SUM(jl.debit - jl.credit) > 0
      ORDER BY total DESC
      LIMIT ${limit}
    `) as Row[];

    const totalExpenses = rows.reduce((s: number, r: Row) => s + Number(r.total || 0), 0);

    return rows.map((r: Row) => {
      const total = Number(r.total || 0);
      return {
        accountName: String(r.account_name),
        total,
        percentOfExpenses: totalExpenses > 0 ? (total / totalExpenses) * 100 : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get top expense categories', { error: err }, 'kpi-service');
    throw err;
  }
}

/**
 * BankTxAttachmentsModal
 *
 * View, upload, and delete file attachments (receipts, invoices, PDFs) for a
 * single bank transaction. Files are stored as base64 data URLs in the
 * bank_transaction_attachments table (suitable for small receipts ≤ 2 MB).
 *
 * Props:
 *   bankTransactionId     — UUID of the target bank transaction
 *   transactionDescription — Optional label shown in the modal header
 *   onClose               — Dismiss callback
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { X, Paperclip, Trash2, Upload, FileImage, FileText, AlertCircle, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ─────────────────────────────────────────────────────────────────────

interface Attachment {
  id: string;
  bank_transaction_id: string;
  file_url: string;
  file_name: string;
  file_size: number | null;
  uploaded_by: string | null;
  created_at: string;
}

interface Props {
  bankTransactionId: string;
  transactionDescription?: string;
  onClose: () => void;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const MAX_BYTES = 2 * 1024 * 1024; // 2 MB
const ACCEPT = '.jpg,.jpeg,.png,.pdf';
const ACCEPTED_MIME = ['image/jpeg', 'image/png', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

function formatBytes(bytes: number | null): string {
  if (bytes === null) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

function fileIcon(name: string): 'image' | 'pdf' | 'generic' {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  if (['jpg', 'jpeg', 'png'].includes(ext)) return 'image';
  if (ext === 'pdf') return 'pdf';
  return 'generic';
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

// ── Component ─────────────────────────────────────────────────────────────────

// 🟢 WORKING: Attachment list + upload modal for bank transactions
export function BankTxAttachmentsModal({ bankTransactionId, transactionDescription, onClose }: Props) {
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Fetch attachment list ──────────────────────────────────────────────────
  const fetchAttachments = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch(
        `/api/accounting/bank-tx-attachments?bankTransactionId=${encodeURIComponent(bankTransactionId)}`,
      );
      const json = await res.json() as { success: boolean; data: Attachment[] };
      if (!res.ok || !json.success) throw new Error('Failed to load attachments');
      setAttachments(json.data);
    } catch {
      notify.error('Could not load attachments');
    } finally {
      setLoading(false);
    }
  }, [bankTransactionId]);

  useEffect(() => { void fetchAttachments(); }, [fetchAttachments]);

  // ── Upload ─────────────────────────────────────────────────────────────────
  const handleUpload = useCallback(async (file: File) => {
    if (!ACCEPTED_MIME.includes(file.type)) {
      notify.error('Only JPG, PNG and PDF files are accepted');
      return;
    }
    if (file.size > MAX_BYTES) {
      notify.error('File exceeds the 2 MB limit');
      return;
    }

    setUploading(true);
    try {
      const fileData = await readFileAsDataUrl(file);
      const res = await apiFetch('/api/accounting/bank-tx-attachments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankTransactionId,
          fileName: file.name,
          fileData,
          fileSize: file.size,
        }),
      });
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Upload failed');
      notify.success(`${file.name} uploaded`);
      await fetchAttachments();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  }, [bankTransactionId, fetchAttachments]);

  // ── File input change ──────────────────────────────────────────────────────
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleUpload(file);
    e.target.value = '';
  };

  // ── Drag-and-drop ──────────────────────────────────────────────────────────
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    if (file) void handleUpload(file);
  };

  // ── Delete ─────────────────────────────────────────────────────────────────
  const handleDelete = async (id: string, name: string) => {
    setDeletingId(id);
    try {
      const res = await apiFetch(
        `/api/accounting/bank-tx-attachments?id=${encodeURIComponent(id)}`,
        { method: 'DELETE' },
      );
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Delete failed');
      notify.success(`${name} removed`);
      setAttachments(prev => prev.filter(a => a.id !== id));
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeletingId(null);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div
        className="w-full max-w-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[85vh]"
        onClick={e => e.stopPropagation()}
      >
        {/* ── Header ─────────────────────────────────────────────────────── */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)] shrink-0">
          <div className="p-2 rounded-lg bg-blue-500/10">
            <Paperclip className="h-4 w-4 text-blue-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Attachments</h2>
            {transactionDescription && (
              <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{transactionDescription}</p>
            )}
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* ── Upload zone ────────────────────────────────────────────────── */}
        <div className="px-5 pt-4 shrink-0">
          <div
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            onClick={() => !uploading && fileInputRef.current?.click()}
            className={`relative flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed py-5 cursor-pointer transition-colors ${
              dragOver
                ? 'border-blue-400 bg-blue-500/10'
                : 'border-[var(--ff-border-light)] hover:border-[var(--ff-text-tertiary)] bg-[var(--ff-bg-primary)]'
            }`}
          >
            {uploading ? (
              <>
                <Loader2 className="h-5 w-5 text-blue-400 animate-spin" />
                <span className="text-xs text-[var(--ff-text-secondary)]">Uploading…</span>
              </>
            ) : (
              <>
                <Upload className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                <p className="text-xs text-[var(--ff-text-secondary)] text-center">
                  Drag &amp; drop or{' '}
                  <span className="text-blue-400 font-medium">click to browse</span>
                </p>
                <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                  JPG, PNG, PDF — max 2 MB
                </p>
              </>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept={ACCEPT}
              className="sr-only"
              onChange={handleFileChange}
              disabled={uploading}
            />
          </div>
        </div>

        {/* ── Attachment list ─────────────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-2">
          {loading ? (
            <div className="flex items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-xs">Loading…</span>
            </div>
          ) : attachments.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <AlertCircle className="h-5 w-5" />
              <span className="text-xs">No attachments yet</span>
            </div>
          ) : (
            attachments.map(att => {
              const icon = fileIcon(att.file_name);
              const isDeleting = deletingId === att.id;
              return (
                <div
                  key={att.id}
                  className="flex items-center gap-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] px-3 py-2.5"
                >
                  {/* File type icon */}
                  <div className="shrink-0 p-1.5 rounded bg-[var(--ff-bg-secondary)]">
                    {icon === 'image' ? (
                      <FileImage className="h-4 w-4 text-blue-400" />
                    ) : icon === 'pdf' ? (
                      <FileText className="h-4 w-4 text-orange-400" />
                    ) : (
                      <Paperclip className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                    )}
                  </div>

                  {/* Name + meta */}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-[var(--ff-text-primary)] truncate">
                      {att.file_name}
                    </p>
                    <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                      {formatBytes(att.file_size)}{att.file_size ? ' · ' : ''}{formatDate(att.created_at)}
                    </p>
                  </div>

                  {/* Download link */}
                  <a
                    href={att.file_url}
                    download={att.file_name}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="shrink-0 p-1.5 rounded hover:bg-blue-500/10 text-[var(--ff-text-tertiary)] hover:text-blue-400 transition-colors"
                    title="Download"
                    onClick={e => e.stopPropagation()}
                  >
                    <Upload className="h-3.5 w-3.5 rotate-180" />
                  </a>

                  {/* Delete */}
                  <button
                    disabled={isDeleting}
                    onClick={() => void handleDelete(att.id, att.file_name)}
                    className="shrink-0 p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 disabled:opacity-40 transition-colors"
                    title="Remove"
                  >
                    {isDeleting
                      ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      : <Trash2 className="h-3.5 w-3.5" />
                    }
                  </button>
                </div>
              );
            })
          )}
        </div>

        {/* ── Footer ─────────────────────────────────────────────────────── */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3 flex items-center justify-between shrink-0">
          <span className="text-xs text-[var(--ff-text-tertiary)]">
            {attachments.length} attachment{attachments.length !== 1 ? 's' : ''}
          </span>
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded text-xs border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

