/**
 * Bank Statement Import Page
 * PRD-060 Phase 4: CSV + PDF upload with format detection
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Upload, Loader2, AlertCircle, CheckCircle2, Landmark, FileText } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface BankAccount { id: string; account_code: string; account_name: string; bank_account_number?: string | null }

type FileType = 'csv' | 'pdf' | 'ofx' | 'qif';

interface ImportForm {
  bankAccountId: string;
  statementDate: string;
  bankFormat: string;
  /** Raw text content for CSV files */
  csvContent: string;
  /** Base64 data-URL for PDF files */
  pdfBase64: string;
  fileName: string;
  fileType: FileType | '';
}

export default function BankStatementImportPage() {
  useRouter();
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState<{
    batchId: string;
    transactionCount: number;
    errors: { row: number; error: string }[];
  } | null>(null);

  const [form, setForm] = useState<ImportForm>({
    bankAccountId: '',
    statementDate: new Date().toISOString().split('T')[0]!,
    bankFormat: 'auto',
    csvContent: '',
    pdfBase64: '',
    fileName: '',
    fileType: '',
  });

  useEffect(() => {
    apiFetch('/api/accounting/chart-of-accounts?subtype=bank')
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const accounts = Array.isArray(data) ? data : data.accounts || [];
        setBankAccounts(
          accounts.map((a: {
            id: string;
            accountCode?: string;
            account_code?: string;
            accountName?: string;
            account_name?: string;
            bankAccountNumber?: string;
            bank_account_number?: string;
          }) => ({
            id: a.id,
            account_code: a.accountCode || a.account_code || '',
            account_name: a.accountName || a.account_name || '',
            bank_account_number: a.bankAccountNumber || a.bank_account_number || null,
          })),
        );
      });
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const lower = file.name.toLowerCase();
    const isPdf = lower.endsWith('.pdf') || file.type === 'application/pdf';
    const isCsv = lower.endsWith('.csv') || file.type === 'text/csv';
    const isOfx = lower.endsWith('.ofx') || lower.endsWith('.qfx');
    const isQif = lower.endsWith('.qif');

    if (!isPdf && !isCsv && !isOfx && !isQif) {
      setError('Only CSV, PDF, OFX, and QIF files are supported.');
      return;
    }

    setError('');

    if (isPdf) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        setForm(f => ({
          ...f,
          pdfBase64: ev.target?.result as string || '',
          csvContent: '',
          fileName: file.name,
          fileType: 'pdf',
        }));
      };
      reader.readAsDataURL(file);
    } else {
      // CSV, OFX, and QIF are all read as text
      const detectedFileType: FileType = isOfx ? 'ofx' : isQif ? 'qif' : 'csv';
      const reader = new FileReader();
      reader.onload = (ev) => {
        const content = ev.target?.result as string || '';
        setForm(f => ({
          ...f,
          csvContent: content,
          pdfBase64: '',
          fileName: file.name,
          fileType: detectedFileType,
          // Auto-set bankFormat for OFX/QIF since format is unambiguous
          bankFormat: isOfx ? 'ofx' : isQif ? 'qif' : f.bankFormat,
        }));
      };
      reader.readAsText(file);
    }
  };

  const hasFile = form.fileType === 'pdf' ? !!form.pdfBase64 : !!form.csvContent;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setResult(null);
    setIsSubmitting(true);

    try {
      const body: Record<string, unknown> = {
        bankAccountId: form.bankAccountId,
        statementDate: form.statementDate,
        bankFormat: form.bankFormat === 'auto' ? undefined : form.bankFormat,
        fileType: form.fileType || 'csv',
      };

      if (form.fileType === 'pdf') {
        body.pdfBase64 = form.pdfBase64;
      } else {
        // csv, ofx, and qif all send csvContent (raw text)
        body.csvContent = form.csvContent;
      }

      const res = await apiFetch('/api/accounting/bank-transactions-import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Import failed');
      setResult(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setIsSubmitting(false);
    }
  };

  const csvRowCount = form.fileType === 'csv' ? Math.max(0, form.csvContent.split('\n').length - 1) : 0;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link
              href="/accounting/bank-reconciliation"
              className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2"
            >
              <ArrowLeft className="h-4 w-4" /> Back to Reconciliations
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Upload className="h-6 w-6 text-teal-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Import Bank Statement</h1>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {result && (
            <div className="p-4 rounded-lg bg-teal-500/10 border border-teal-500/30 space-y-2">
              <div className="flex items-center gap-2 text-teal-400 font-medium">
                <CheckCircle2 className="h-5 w-5" /> Import Successful
              </div>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Imported {result.transactionCount} transaction{result.transactionCount !== 1 ? 's' : ''}
              </p>
              {result.errors.length > 0 && (
                <div className="text-sm text-amber-400">
                  {result.errors.length} row{result.errors.length !== 1 ? 's' : ''} skipped:
                  <ul className="list-disc ml-5 mt-1 text-xs">
                    {result.errors.slice(0, 5).map((e, i) => (
                      <li key={i}>Row {e.row}: {e.error}</li>
                    ))}
                    {result.errors.length > 5 && <li>...and {result.errors.length - 5} more</li>}
                  </ul>
                </div>
              )}
              <div className="pt-2">
                <Link
                  href="/accounting/bank-reconciliation"
                  className="text-sm text-teal-500 hover:text-teal-400 font-medium"
                >
                  Start a reconciliation with these transactions
                </Link>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Statement Details</h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Bank Account *
                  </label>
                  <select
                    value={form.bankAccountId}
                    onChange={e => setForm(f => ({ ...f, bankAccountId: e.target.value }))}
                    className="ff-select w-full"
                    required
                  >
                    <option value="">Select bank account...</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>
                        {a.account_code} — {a.account_name}
                        {a.bank_account_number ? ` (****${a.bank_account_number.slice(-4)})` : ''}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Statement Date *
                  </label>
                  <input
                    type="date"
                    value={form.statementDate}
                    onChange={e => setForm(f => ({ ...f, statementDate: e.target.value }))}
                    className="ff-input w-full"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Bank Format
                  </label>
                  <select
                    value={form.bankFormat}
                    onChange={e => setForm(f => ({ ...f, bankFormat: e.target.value }))}
                    className="ff-select w-full"
                  >
                    <option value="auto">Auto-detect</option>
                    <optgroup label="CSV Formats">
                      <option value="absa">ABSA</option>
                      <option value="capitec">Capitec</option>
                      <option value="fnb">FNB</option>
                      <option value="standard_bank">Standard Bank</option>
                      <option value="nedbank">Nedbank</option>
                    </optgroup>
                    <optgroup label="Other Formats">
                      <option value="ofx">OFX / QFX (Open Financial Exchange)</option>
                      <option value="qif">QIF (Quicken Interchange Format)</option>
                    </optgroup>
                  </select>
                </div>
              </div>
            </div>

            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Statement File</h2>

              <div className="border-2 border-dashed border-[var(--ff-border-light)] rounded-lg p-8 text-center">
                {form.fileType === 'pdf' ? (
                  <FileText className="h-8 w-8 text-red-400 mx-auto mb-3" />
                ) : (
                  <Landmark className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
                )}
                <label className="block">
                  <span className="text-teal-500 hover:text-teal-400 cursor-pointer font-medium">
                    Choose CSV, PDF, OFX, or QIF file
                  </span>
                  <input
                    type="file"
                    accept=".csv,.pdf,.ofx,.qfx,.qif"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
                {form.fileName ? (
                  <p className="mt-2 text-sm text-[var(--ff-text-secondary)]">
                    {form.fileName}
                    {form.fileType && (
                      <span className="ml-2 text-xs px-1.5 py-0.5 rounded bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] uppercase">
                        {form.fileType}
                      </span>
                    )}
                  </p>
                ) : null}
                <p className="mt-1 text-xs text-[var(--ff-text-tertiary)]">
                  Supports CSV (ABSA, Capitec, FNB, Standard Bank, Nedbank), PDF, OFX/QFX, and QIF formats
                </p>
              </div>

              {form.fileType === 'csv' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  {csvRowCount} data row{csvRowCount !== 1 ? 's' : ''} detected
                </div>
              )}

              {form.fileType === 'ofx' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  OFX file loaded — transactions will be extracted on import
                </div>
              )}

              {form.fileType === 'qif' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  QIF file loaded — transactions will be extracted on import
                </div>
              )}

              {form.fileType === 'pdf' && form.pdfBase64 && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  PDF loaded — transactions will be extracted on import
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3">
              <Link
                href="/accounting/bank-reconciliation"
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting || !hasFile || !form.bankAccountId}
                className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors text-sm font-medium"
              >
                {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
                Import Statement
              </button>
            </div>
          </form>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Create Supplier Invoice Page
 * PRD-060 Phase 2: Capture invoice with line items
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Receipt, Plus, Trash2, Loader2 } from 'lucide-react';

interface LineItem {
  key: string;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  glAccountId: string;
}

import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface Supplier { id: number; name: string }
interface GLAccount { id: string; accountCode: string; accountName: string }

export default function NewSupplierInvoicePage() {
  const router = useRouter();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [glAccounts, setGLAccounts] = useState<GLAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    invoiceNumber: '',
    supplierId: '',
    invoiceDate: new Date().toISOString().split('T')[0],
    dueDate: '',
    paymentTerms: 'net30',
    reference: '',
    notes: '',
    taxRate: 15,
  });

  const [lines, setLines] = useState<LineItem[]>([
    { key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0, taxRate: 15, glAccountId: '' },
  ]);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/suppliers').then(r => r.json()),
      apiFetch('/api/accounting/chart-of-accounts').then(r => r.json()),
    ]).then(([suppRes, accRes]) => {
      const suppData = suppRes.data || suppRes;
      setSuppliers(Array.isArray(suppData) ? suppData : suppData.suppliers || []);
      const accData = accRes.data || accRes;
      setGLAccounts(Array.isArray(accData) ? accData.filter((a: GLAccount) => a.accountCode >= '5000') : []);
    });
  }, []);

  const addLine = () => {
    setLines(prev => [...prev, {
      key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0,
      taxRate: form.taxRate, glAccountId: '',
    }]);
  };

  const updateLine = (key: string, field: keyof LineItem, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };

  const removeLine = (key: string) => {
    if (lines.length <= 1) return;
    setLines(prev => prev.filter(l => l.key !== key));
  };

  const subtotal = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0);
  const totalTax = lines.reduce((sum, l) => sum + (l.quantity * l.unitPrice * l.taxRate / 100), 0);
  const total = subtotal + totalTax;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/supplier-invoices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          invoiceNumber: form.invoiceNumber,
          supplierId: form.supplierId,
          invoiceDate: form.invoiceDate,
          dueDate: form.dueDate || undefined,
          paymentTerms: form.paymentTerms || undefined,
          reference: form.reference || undefined,
          notes: form.notes || undefined,
          taxRate: form.taxRate,
          items: lines.map(l => ({
            description: l.description,
            quantity: l.quantity,
            unitPrice: l.unitPrice,
            taxRate: l.taxRate,
            glAccountId: l.glAccountId || undefined,
          })),
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error?.message || 'Failed to create invoice');
      }

      const json = await res.json();
      const invoice = json.data || json;
      router.push(`/accounting/supplier-invoices/${invoice.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create invoice');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/supplier-invoices" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-teal-600 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Supplier Invoices
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Receipt className="h-6 w-6 text-teal-500" />
            </div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Supplier Invoice</h1>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6 max-w-5xl">
          {error && (
            <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>
          )}

          {/* Invoice Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <h3 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Invoice Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Invoice Number *</label>
                <input type="text" required value={form.invoiceNumber}
                  onChange={e => setForm(f => ({ ...f, invoiceNumber: e.target.value }))}
                  className="ff-input w-full" placeholder="INV-001" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Supplier *</label>
                <select required value={form.supplierId}
                  onChange={e => setForm(f => ({ ...f, supplierId: e.target.value }))}
                  className="ff-select w-full">
                  <option value="">Select supplier...</option>
                  {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Invoice Date *</label>
                <input type="date" required value={form.invoiceDate}
                  onChange={e => setForm(f => ({ ...f, invoiceDate: e.target.value }))}
                  className="ff-input w-full" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Terms</label>
                <select value={form.paymentTerms}
                  onChange={e => setForm(f => ({ ...f, paymentTerms: e.target.value }))}
                  className="ff-select w-full">
                  <option value="">None</option>
                  <option value="immediate">Immediate</option>
                  <option value="net30">Net 30</option>
                  <option value="net60">Net 60</option>
                  <option value="net90">Net 90</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Reference</label>
                <input type="text" value={form.reference}
                  onChange={e => setForm(f => ({ ...f, reference: e.target.value }))}
                  className="ff-input w-full" placeholder="PO ref or delivery note" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">VAT Rate (%)</label>
                <input type="number" step="0.01" value={form.taxRate}
                  onChange={e => setForm(f => ({ ...f, taxRate: Number(e.target.value) }))}
                  className="ff-input w-full" />
              </div>
            </div>
          </div>

          {/* Line Items */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Line Items</h3>
              <button type="button" onClick={addLine}
                className="inline-flex items-center gap-1 text-sm text-teal-600 hover:text-teal-700 font-medium">
                <Plus className="h-4 w-4" /> Add Line
              </button>
            </div>
            <div className="space-y-3">
              {lines.map((line, idx) => (
                <div key={line.key} className="grid grid-cols-12 gap-2 items-end">
                  <div className="col-span-4">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Description *</label>}
                    <input type="text" required value={line.description}
                      onChange={e => updateLine(line.key, 'description', e.target.value)}
                      className="ff-input w-full text-sm" placeholder="Item description" />
                  </div>
                  <div className="col-span-1">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Qty</label>}
                    <input type="number" step="0.01" min="0.01" required value={line.quantity}
                      onChange={e => updateLine(line.key, 'quantity', Number(e.target.value))}
                      className="ff-input w-full text-sm text-right" />
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Unit Price</label>}
                    <input type="number" step="0.01" min="0" required value={line.unitPrice}
                      onChange={e => updateLine(line.key, 'unitPrice', Number(e.target.value))}
                      className="ff-input w-full text-sm text-right" />
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">GL Account</label>}
                    <select value={line.glAccountId}
                      onChange={e => updateLine(line.key, 'glAccountId', e.target.value)}
                      className="ff-select w-full text-sm">
                      <option value="">Default (5100)</option>
                      {glAccounts.map(a => (
                        <option key={a.id} value={a.id}>{a.accountCode} - {a.accountName}</option>
                      ))}
                    </select>
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Line Total</label>}
                    <div className="ff-input w-full text-sm text-right bg-[var(--ff-bg-tertiary)] font-mono">
                      {formatCurrency(line.quantity * line.unitPrice)}
                    </div>
                  </div>
                  <div className="col-span-1 flex justify-center">
                    {lines.length > 1 && (
                      <button type="button" onClick={() => removeLine(line.key)}
                        className="p-1 text-red-400 hover:text-red-300">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Totals */}
            <div className="mt-4 pt-4 border-t border-[var(--ff-border-light)] flex justify-end">
              <div className="w-64 space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">Subtotal</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(subtotal)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">VAT</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(totalTax)}</span>
                </div>
                <div className="flex justify-between text-base font-bold border-t border-[var(--ff-border-medium)] pt-2">
                  <span className="text-[var(--ff-text-primary)]">Total</span>
                  <span className="font-mono text-teal-500">{formatCurrency(total)}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Notes */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
            <textarea value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
              className="ff-input w-full" rows={3} placeholder="Optional notes..." />
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/supplier-invoices"
              className="px-4 py-2 border border-[var(--ff-border-medium)] rounded-lg text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium">
              Cancel
            </Link>
            <button type="submit" disabled={isSubmitting}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Invoice
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Create Customer Invoice (standalone)
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Plus, Trash2, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Client { id: string; company_name: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; incomeType: string }

export default function NewCustomerInvoicePage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const today = new Date().toISOString().split('T')[0];

  const [form, setForm] = useState({ clientId: '', invoiceDate: today, dueDate: '', billingPeriodStart: today, billingPeriodEnd: today, taxRate: 15, notes: '' });
  const [lines, setLines] = useState<LineItem[]>([{ key: '1', description: '', quantity: 1, unitPrice: 0, incomeType: 'other' }]);

  useEffect(() => {
    apiFetch('/api/clients', { credentials: 'include' }).then(r => r.json()).then(json => {
      const d = json.data || json;
      setClients(Array.isArray(d) ? d : d.clients || []);
    }).catch(() => { /* reference data load failure — non-critical, client dropdown will be empty */ });
  }, []);

  const updateLine = (key: string, field: string, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, { key: String(Date.now()), description: '', quantity: 1, unitPrice: 0, incomeType: 'other' }]);
  const removeLine = (key: string) => setLines(prev => prev.length > 1 ? prev.filter(l => l.key !== key) : prev);

  const subtotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);
  const tax = subtotal * (form.taxRate / 100);
  const total = subtotal + tax;

  const handleSubmit = async () => {
    if (!form.clientId) return setError('Select a client');
    const validLines = lines.filter(l => l.description && l.unitPrice > 0);
    if (validLines.length === 0) return setError('Add at least one line item');
    setSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/customer-invoices-create', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, items: validLines }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed to create');
      const d = json.data || json;
      router.push(`/accounting/customer-invoices/${d.id}`);
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed'); setSubmitting(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customer-invoices" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Invoices
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10"><FileText className="h-6 w-6 text-blue-500" /></div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Customer Invoice</h1>
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {error && <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Client *</label>
                <select value={form.clientId} onChange={e => setForm(p => ({ ...p, clientId: e.target.value }))} className="ff-select w-full text-sm">
                  <option value="">Select client...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">VAT Rate %</label>
                <input type="number" value={form.taxRate} onChange={e => setForm(p => ({ ...p, taxRate: Number(e.target.value) }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div className="grid grid-cols-4 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Invoice Date</label>
                <input type="date" value={form.invoiceDate} onChange={e => setForm(p => ({ ...p, invoiceDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Due Date</label>
                <input type="date" value={form.dueDate} onChange={e => setForm(p => ({ ...p, dueDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period Start</label>
                <input type="date" value={form.billingPeriodStart} onChange={e => setForm(p => ({ ...p, billingPeriodStart: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period End</label>
                <input type="date" value={form.billingPeriodEnd} onChange={e => setForm(p => ({ ...p, billingPeriodEnd: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Notes</label>
              <textarea value={form.notes} onChange={e => setForm(p => ({ ...p, notes: e.target.value }))} rows={2} className="ff-input w-full text-sm" />
            </div>
          </div>

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <div className="px-4 py-3 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">Line Items</h3>
              <button onClick={addLine} className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1"><Plus className="h-3 w-3" />Add Line</button>
            </div>
            <table className="w-full">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-3 py-2 text-left text-xs text-[var(--ff-text-secondary)]">Description</th>
                  <th className="px-3 py-2 text-center text-xs text-[var(--ff-text-secondary)]">Type</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Qty</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Unit Price</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Total</th>
                  <th className="px-3 py-2 w-8"></th>
                </tr>
              </thead>
              <tbody>
                {lines.map(l => (
                  <tr key={l.key} className="border-b border-[var(--ff-border-light)]">
                    <td className="px-3 py-2"><input value={l.description} onChange={e => updateLine(l.key, 'description', e.target.value)} placeholder="Description *" className="ff-input w-full text-sm" /></td>
                    <td className="px-3 py-2"><select value={l.incomeType} onChange={e => updateLine(l.key, 'incomeType', e.target.value)} className="ff-select text-sm">
                      <option value="activation">Activation</option><option value="bonus">Bonus</option><option value="adjustment">Adjustment</option><option value="other">Other</option>
                    </select></td>
                    <td className="px-3 py-2 w-20"><input type="number" value={l.quantity} onChange={e => updateLine(l.key, 'quantity', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    <td className="px-3 py-2 w-28"><input type="number" value={l.unitPrice} onChange={e => updateLine(l.key, 'unitPrice', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    <td className="px-3 py-2 text-right font-mono text-sm">{fmt(l.quantity * l.unitPrice)}</td>
                    <td className="px-3 py-2"><button onClick={() => removeLine(l.key)} className="text-red-400 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex items-center justify-between">
            <div className="text-sm space-y-1">
              <p className="text-[var(--ff-text-secondary)]">Subtotal: <span className="font-mono">{fmt(subtotal)}</span></p>
              <p className="text-[var(--ff-text-secondary)]">VAT ({form.taxRate}%): <span className="font-mono">{fmt(tax)}</span></p>
              <p className="text-[var(--ff-text-primary)] font-bold">Total: <span className="font-mono text-blue-400">{fmt(total)}</span></p>
            </div>
            <button onClick={handleSubmit} disabled={submitting} className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm font-medium disabled:opacity-50">
              {submitting ? <><Loader2 className="h-4 w-4 animate-spin inline mr-1" />Creating...</> : 'Create Invoice'}
            </button>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Start New Reconciliation Page
 * PRD-060 Phase 4: Create reconciliation session
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Landmark, Loader2 } from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface BankAccount { id: string; account_code: string; account_name: string; bank_account_number?: string | null }

export default function NewReconciliationPage() {
  const router = useRouter();
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    bankAccountId: '',
    statementDate: new Date().toISOString().split('T')[0],
    statementBalance: 0,
  });

  useEffect(() => {
    apiFetch('/api/accounting/chart-of-accounts?subtype=bank')
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const accounts = Array.isArray(data) ? data : data.accounts || [];
        setBankAccounts(accounts.map((a: { id: string; accountCode?: string; account_code?: string; accountName?: string; account_name?: string; bankAccountNumber?: string; bank_account_number?: string }) => ({
          id: a.id,
          account_code: a.accountCode || a.account_code || '',
          account_name: a.accountName || a.account_name || '',
          bank_account_number: a.bankAccountNumber || a.bank_account_number || null,
        })));
      });
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const res = await apiFetch('/api/accounting/bank-reconciliations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          bankAccountId: form.bankAccountId,
          statementDate: form.statementDate,
          statementBalance: form.statementBalance,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Failed to start reconciliation');
      const data = json.data || json;
      router.push(`/accounting/bank-reconciliation/${data.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start reconciliation');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/bank-reconciliation" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Reconciliations
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Landmark className="h-6 w-6 text-teal-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Start Reconciliation</h1>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-2xl space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Reconciliation Setup</h2>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Bank Account *</label>
              <select
                value={form.bankAccountId}
                onChange={e => setForm(f => ({ ...f, bankAccountId: e.target.value }))}
                className="ff-select w-full"
                required
              >
                <option value="">Select bank account...</option>
                {bankAccounts.map(a => (
                  <option key={a.id} value={a.id}>
                    {a.account_code} — {a.account_name}
                    {a.bank_account_number ? ` (****${a.bank_account_number.slice(-4)})` : ''}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Statement Date *</label>
                <input
                  type="date"
                  value={form.statementDate}
                  onChange={e => setForm(f => ({ ...f, statementDate: e.target.value }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Statement Closing Balance *</label>
                <input
                  type="number"
                  step="0.01"
                  value={form.statementBalance || ''}
                  onChange={e => setForm(f => ({ ...f, statementBalance: Number(e.target.value) }))}
                  className="ff-input w-full"
                  placeholder="e.g. 125000.00"
                  required
                />
              </div>
            </div>

            <p className="text-xs text-[var(--ff-text-tertiary)]">
              Enter the closing balance from your bank statement. The system will calculate the GL balance
              automatically and show the difference for you to reconcile.
            </p>
          </div>

          <div className="flex justify-end gap-3">
            <Link href="/accounting/bank-reconciliation" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
              Cancel
            </Link>
            <button
              type="submit"
              disabled={isSubmitting || !form.bankAccountId}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors text-sm font-medium"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Start Reconciliation
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

