/**
 * Bank Reconciliation Detail Page
 * PRD-060 Phase 4: Main reconciliation work screen
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ArrowLeft, Landmark, Loader2, AlertCircle, CheckCircle2,
  Zap, Link2, Unlink, Ban, Check,
} from 'lucide-react';
import type { BankReconciliation, BankTransaction } from '@/modules/accounting/types/bank.types';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

function TxStatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    imported: 'bg-gray-500/20 text-gray-400',
    matched: 'bg-blue-500/20 text-blue-400',
    reconciled: 'bg-teal-500/20 text-teal-400',
    excluded: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

interface GLLine {
  id: string;
  debit: number;
  credit: number;
  description: string;
  entryDate: string;
  entryNumber: string;
}

export default function ReconciliationDetailPage() {
  const router = useRouter();
  const reconId = router.query.reconId as string;

  const [recon, setRecon] = useState<BankReconciliation | null>(null);
  const [transactions, setTransactions] = useState<BankTransaction[]>([]);
  const [glLines, setGlLines] = useState<GLLine[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [actionLoading, setActionLoading] = useState('');

  // Selected items for manual matching
  const [selectedTx, setSelectedTx] = useState<string | null>(null);
  const [selectedGl, setSelectedGl] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    if (!reconId) return;
    setIsLoading(true);
    setError('');
    try {
      const [reconRes, txRes] = await Promise.all([
        apiFetch(`/api/accounting/bank-reconciliations?id=${reconId}`),
        apiFetch(`/api/accounting/bank-transactions?reconciliation_id=${reconId}&limit=500`),
      ]);

      const reconJson = await reconRes.json();
      const reconData = reconJson.data || reconJson;
      setRecon(reconData);

      const txJson = await txRes.json();
      const txData = txJson.data || txJson;
      setTransactions(txData.transactions || []);

      // Load unmatched GL lines for this bank account
      if (reconData?.bankAccountId) {
        const glRes = await apiFetch(`/api/accounting/journal-entries?gl_account_id=${reconData.bankAccountId}&status=posted&limit=200`);
        const glJson = await glRes.json();
        const entries = glJson.data?.entries || glJson.entries || [];
        const lines: GLLine[] = [];
        for (const entry of entries) {
          if (entry.lines) {
            for (const line of entry.lines) {
              if (line.glAccountId === reconData.bankAccountId || line.gl_account_id === reconData.bankAccountId) {
                lines.push({
                  id: line.id,
                  debit: Number(line.debit || 0),
                  credit: Number(line.credit || 0),
                  description: line.description || entry.description || '',
                  entryDate: entry.entryDate || entry.entry_date || '',
                  entryNumber: entry.entryNumber || entry.entry_number || '',
                });
              }
            }
          }
        }
        // Filter out already matched
        const matchedLineIds = new Set(
          transactions.filter(t => t.matchedJournalLineId).map(t => t.matchedJournalLineId)
        );
        setGlLines(lines.filter(l => !matchedLineIds.has(l.id)));
      }
    } catch {
      setError('Failed to load reconciliation data');
    } finally {
      setIsLoading(false);
    }
  }, [reconId]);

  useEffect(() => { loadData(); }, [loadData]);

  const handleAutoMatch = async () => {
    if (!recon) return;
    setActionLoading('auto_match');
    try {
      const res = await apiFetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          action: 'auto_match',
          bankAccountId: recon.bankAccountId,
          reconciliationId: reconId,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Auto-match failed');
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Auto-match failed');
    } finally {
      setActionLoading('');
    }
  };

  const handleManualMatch = async () => {
    if (!selectedTx || !selectedGl) return;
    setActionLoading('match');
    try {
      const res = await apiFetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          action: 'match',
          bankTransactionId: selectedTx,
          journalLineId: selectedGl,
          reconciliationId: reconId,
        }),
      });
      if (!res.ok) throw new Error('Match failed');
      setSelectedTx(null);
      setSelectedGl(null);
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Match failed');
    } finally {
      setActionLoading('');
    }
  };

  const handleUnmatch = async (txId: string) => {
    setActionLoading(txId);
    try {
      await apiFetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'unmatch', bankTransactionId: txId }),
      });
      await loadData();
    } catch {
      setError('Unmatch failed');
    } finally {
      setActionLoading('');
    }
  };

  const handleExclude = async (txId: string) => {
    setActionLoading(txId);
    try {
      await apiFetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'exclude', bankTransactionId: txId }),
      });
      await loadData();
    } catch {
      setError('Exclude failed');
    } finally {
      setActionLoading('');
    }
  };

  const handleComplete = async () => {
    setActionLoading('complete');
    try {
      const res = await apiFetch('/api/accounting/bank-reconciliations-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'complete', reconciliationId: reconId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Cannot complete');
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Cannot complete reconciliation');
    } finally {
      setActionLoading('');
    }
  };

  if (isLoading) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  if (!recon) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <p className="text-[var(--ff-text-secondary)]">Reconciliation not found</p>
        </div>
      </AppLayout>
    );
  }

  const unmatchedTxs = transactions.filter(t => t.status === 'imported');
  const matchedTxs = transactions.filter(t => t.status === 'matched' || t.status === 'reconciled');
  const isCompleted = recon.status === 'completed';
  const canComplete = Math.abs(recon.difference) < 0.01 && !isCompleted;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/bank-reconciliation" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Reconciliations
            </Link>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10">
                  <Landmark className="h-6 w-6 text-teal-500" />
                </div>
                <div>
                  <h1 className="text-xl font-bold text-[var(--ff-text-primary)]">
                    {recon.bankAccountName || 'Bank Reconciliation'}
                  </h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    Statement: {new Date(recon.statementDate).toLocaleDateString('en-ZA')}
                    {isCompleted && <span className="ml-2 text-teal-400">Completed</span>}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {!isCompleted && (
                  <button
                    onClick={handleAutoMatch}
                    disabled={!!actionLoading || unmatchedTxs.length === 0}
                    className="inline-flex items-center gap-2 px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors text-sm"
                  >
                    {actionLoading === 'auto_match' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Zap className="h-4 w-4" />}
                    Auto-Match
                  </button>
                )}
                {canComplete && (
                  <button
                    onClick={handleComplete}
                    disabled={!!actionLoading}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors text-sm font-medium"
                  >
                    {actionLoading === 'complete' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                    Complete Reconciliation
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
              <button onClick={() => setError('')} className="ml-auto text-xs underline">dismiss</button>
            </div>
          )}

          {/* Balances Summary */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
              <p className="text-xs text-[var(--ff-text-tertiary)]">Statement Balance</p>
              <p className="text-xl font-bold text-[var(--ff-text-primary)]">{formatCurrency(recon.statementBalance)}</p>
            </div>
            <div className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
              <p className="text-xs text-[var(--ff-text-tertiary)]">GL Balance</p>
              <p className="text-xl font-bold text-[var(--ff-text-primary)]">{formatCurrency(recon.glBalance)}</p>
            </div>
            <div className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
              <p className="text-xs text-[var(--ff-text-tertiary)]">Reconciled Balance</p>
              <p className="text-xl font-bold text-blue-400">{formatCurrency(recon.reconciledBalance)}</p>
            </div>
            <div className={`p-4 rounded-lg border ${Math.abs(recon.difference) < 0.01 ? 'bg-teal-500/10 border-teal-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
              <p className="text-xs text-[var(--ff-text-tertiary)]">Difference</p>
              <p className={`text-xl font-bold ${Math.abs(recon.difference) < 0.01 ? 'text-teal-400' : 'text-red-400'}`}>
                {formatCurrency(recon.difference)}
              </p>
              {Math.abs(recon.difference) < 0.01 && (
                <p className="text-xs text-teal-400 flex items-center gap-1 mt-1">
                  <CheckCircle2 className="h-3 w-3" /> Balanced
                </p>
              )}
            </div>
          </div>

          {/* Manual Match Controls */}
          {!isCompleted && selectedTx && selectedGl && (
            <div className="flex items-center gap-3 p-3 rounded-lg bg-blue-500/10 border border-blue-500/30">
              <Link2 className="h-4 w-4 text-blue-400" />
              <span className="text-sm text-blue-400">Ready to match selected items</span>
              <button
                onClick={handleManualMatch}
                disabled={!!actionLoading}
                className="ml-auto px-3 py-1 bg-blue-600 text-white rounded text-sm hover:bg-blue-700 disabled:opacity-50"
              >
                {actionLoading === 'match' ? <Loader2 className="h-3 w-3 animate-spin" /> : 'Match'}
              </button>
              <button
                onClick={() => { setSelectedTx(null); setSelectedGl(null); }}
                className="px-3 py-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
              >
                Cancel
              </button>
            </div>
          )}

          {/* Two-column layout: Bank Transactions | GL Lines */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Bank Transactions */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
              <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">
                  Bank Transactions ({unmatchedTxs.length} unmatched)
                </h3>
              </div>
              <div className="max-h-[500px] overflow-y-auto">
                {unmatchedTxs.length === 0 && matchedTxs.length === 0 ? (
                  <p className="p-4 text-sm text-[var(--ff-text-tertiary)]">No transactions</p>
                ) : (
                  <div className="divide-y divide-[var(--ff-border-light)]">
                    {unmatchedTxs.map(tx => (
                      <div
                        key={tx.id}
                        onClick={() => !isCompleted && setSelectedTx(tx.id === selectedTx ? null : tx.id)}
                        className={`px-4 py-2 text-sm cursor-pointer transition-colors ${
                          selectedTx === tx.id ? 'bg-blue-500/10' : 'hover:bg-[var(--ff-bg-primary)]'
                        }`}
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex-1 min-w-0">
                            <p className="text-[var(--ff-text-primary)] truncate">{tx.description || '—'}</p>
                            <p className="text-xs text-[var(--ff-text-tertiary)]">
                              {new Date(tx.transactionDate).toLocaleDateString('en-ZA')}
                              {tx.reference && ` | Ref: ${tx.reference}`}
                            </p>
                          </div>
                          <div className="flex items-center gap-2 ml-2">
                            <span className={`font-mono text-sm ${tx.amount >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                              {formatCurrency(tx.amount)}
                            </span>
                            {!isCompleted && (
                              <button
                                onClick={e => { e.stopPropagation(); handleExclude(tx.id); }}
                                className="p-1 text-[var(--ff-text-tertiary)] hover:text-red-400"
                                title="Exclude"
                              >
                                <Ban className="h-3 w-3" />
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                    {matchedTxs.length > 0 && (
                      <>
                        <div className="px-4 py-2 bg-[var(--ff-bg-primary)]">
                          <p className="text-xs font-medium text-teal-400">Matched ({matchedTxs.length})</p>
                        </div>
                        {matchedTxs.map(tx => (
                          <div key={tx.id} className="px-4 py-2 text-sm bg-teal-500/5">
                            <div className="flex items-center justify-between">
                              <div className="flex-1 min-w-0">
                                <p className="text-[var(--ff-text-primary)] truncate">{tx.description || '—'}</p>
                                <p className="text-xs text-[var(--ff-text-tertiary)]">
                                  {new Date(tx.transactionDate).toLocaleDateString('en-ZA')}
                                </p>
                              </div>
                              <div className="flex items-center gap-2 ml-2">
                                <span className="font-mono text-sm text-[var(--ff-text-primary)]">
                                  {formatCurrency(tx.amount)}
                                </span>
                                <TxStatusBadge status={tx.status} />
                                {!isCompleted && tx.status === 'matched' && (
                                  <button
                                    onClick={() => handleUnmatch(tx.id)}
                                    className="p-1 text-[var(--ff-text-tertiary)] hover:text-amber-400"
                                    title="Unmatch"
                                  >
                                    <Unlink className="h-3 w-3" />
                                  </button>
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* GL Journal Lines */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
              <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">
                  GL Lines ({glLines.length} unmatched)
                </h3>
              </div>
              <div className="max-h-[500px] overflow-y-auto">
                {glLines.length === 0 ? (
                  <p className="p-4 text-sm text-[var(--ff-text-tertiary)]">No unmatched GL lines</p>
                ) : (
                  <div className="divide-y divide-[var(--ff-border-light)]">
                    {glLines.map(line => {
                      const amount = line.debit > 0 ? line.debit : -line.credit;
                      return (
                        <div
                          key={line.id}
                          onClick={() => !isCompleted && setSelectedGl(line.id === selectedGl ? null : line.id)}
                          className={`px-4 py-2 text-sm cursor-pointer transition-colors ${
                            selectedGl === line.id ? 'bg-blue-500/10' : 'hover:bg-[var(--ff-bg-primary)]'
                          }`}
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex-1 min-w-0">
                              <p className="text-[var(--ff-text-primary)] truncate">{line.description || '—'}</p>
                              <p className="text-xs text-[var(--ff-text-tertiary)]">
                                {line.entryNumber} | {new Date(line.entryDate).toLocaleDateString('en-ZA')}
                              </p>
                            </div>
                            <span className={`font-mono text-sm ml-2 ${amount >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                              {formatCurrency(amount)}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Categorisation Rules Page
 * Phase 2: Quick entry rules + statement mapping
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Zap, Plus, Trash2, Loader2, ToggleLeft, ToggleRight, Play, Pencil, Search, X } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

type VatCode = 'none' | 'standard' | 'zero_rated' | 'exempt';

const VAT_LABELS: Record<VatCode, string> = {
  none: 'No VAT',
  standard: '15%',
  zero_rated: 'Zero Rated',
  exempt: 'Exempt',
};

interface Rule {
  id: string;
  ruleName: string;
  matchField: string;
  matchType: string;
  matchPattern: string;
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  supplierId?: string;
  supplierName?: string;
  clientId?: string;
  clientName?: string;
  descriptionTemplate?: string;
  priority: number;
  isActive: boolean;
  autoCreateEntry: boolean;
  vatCode: VatCode;
}

interface GLAccount { id: string; accountCode: string; accountName: string; defaultVatCode?: string }
interface Supplier { id: string; name: string }
interface Client { id: string; name: string }

export default function BankRulesPage() {
  const [rules, setRules] = useState<Rule[]>([]);
  const [accounts, setAccounts] = useState<GLAccount[]>([]);
  const [bankAccounts, setBankAccounts] = useState<GLAccount[]>([]);
  const [selectedBankId, setSelectedBankId] = useState('');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [applyResult, setApplyResult] = useState<{ applied: number; skipped: number } | null>(null);
  const [editingRule, setEditingRule] = useState<Rule | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [bulkDeleting, setBulkDeleting] = useState(false);
  const [search, setSearch] = useState('');
  const [previewCount, setPreviewCount] = useState<number | null>(null);
  const previewTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [form, setForm] = useState({
    ruleName: '', matchField: 'description', matchType: 'contains',
    matchPattern: '', glAccountId: '', supplierId: '', clientId: '', vatCode: '',
    descriptionTemplate: '', priority: '100',
  });

  const load = useCallback(async () => {
    const res = await apiFetch('/api/accounting/bank-rules', { credentials: 'include' });
    const json = await res.json();
    setRules(json.data?.items || []);
    setLoading(false);
    setSelected(new Set());
  }, []);

  const handleBulkDelete = async () => {
    if (selected.size === 0) return;
    if (!window.confirm(`Delete ${selected.size} selected rule${selected.size > 1 ? 's' : ''}?`)) return;
    setBulkDeleting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/bank-rules-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify({ action: 'deleteMany', ids: [...selected] }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Bulk delete failed');
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Bulk delete failed');
    } finally {
      setBulkDeleting(false);
    }
  };

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    const mapAccount = (a: Record<string, unknown>) => ({
      id: String(a.id),
      accountCode: String(a.accountCode || a.account_code || ''),
      accountName: String(a.accountName || a.account_name || ''),
    });
    apiFetch('/api/accounting/chart-of-accounts', { credentials: 'include' }).then(r => r.json()).then(res => {
      const d = res.data || res;
      const list = Array.isArray(d) ? d : d.accounts || d.items || [];
      setAccounts(list.map((a: Record<string, unknown>) => ({
        ...mapAccount(a),
        defaultVatCode: String(a.defaultVatCode || a.default_vat_code || 'none'),
      })));
    });
    apiFetch('/api/accounting/bank-accounts', { credentials: 'include' }).then(r => r.json()).then(res => {
      const list = Array.isArray(res.data) ? res.data : [];
      const mapped = list.map((a: Record<string, unknown>) => ({
        id: String(a.id),
        accountCode: String(a.accountCode || ''),
        accountName: String(a.accountName || ''),
      }));
      setBankAccounts(mapped);
      if (mapped.length > 0) setSelectedBankId(String(mapped[0].id));
    });
    apiFetch('/api/suppliers?status=active', { credentials: 'include' }).then(r => r.json()).then(res => {
      const list = Array.isArray(res.data) ? res.data : [];
      setSuppliers(list.map((s: { id: number | string; name: string }) => ({
        id: String(s.id), name: s.name,
      })));
    });
    apiFetch('/api/clients', { credentials: 'include' }).then(r => r.json()).then(res => {
      const list = Array.isArray(res.data) ? res.data : [];
      setClients(list.map((c: { id: string; name?: string; company_name?: string; companyName?: string }) => ({
        id: c.id, name: c.company_name || c.companyName || c.name || '',
      })));
    });
  }, []);

  // Debounced live preview: fetch match count 400ms after pattern/matchType/matchField changes
  useEffect(() => {
    if (!form.matchPattern.trim() || !showForm) { setPreviewCount(null); return; }
    if (previewTimer.current) clearTimeout(previewTimer.current);
    previewTimer.current = setTimeout(async () => {
      try {
        const params = new URLSearchParams({
          pattern: form.matchPattern,
          matchType: form.matchType,
          matchField: form.matchField,
          ...(selectedBankId ? { bankAccountId: selectedBankId } : {}),
        });
        const res = await apiFetch(`/api/accounting/bank-rules-preview?${params}`, { credentials: 'include' });
        const json = await res.json();
        setPreviewCount(json.data?.matchCount ?? null);
      } catch { setPreviewCount(null); }
    }, 400);
    return () => { if (previewTimer.current) clearTimeout(previewTimer.current); };
  }, [form.matchPattern, form.matchType, form.matchField, showForm, selectedBankId]);

  // Client-side filter: name, pattern, GL account code/name
  const filteredRules = search.trim()
    ? rules.filter(r => {
        const q = search.toLowerCase();
        return r.ruleName.toLowerCase().includes(q)
          || r.matchPattern.toLowerCase().includes(q)
          || (r.glAccountCode || '').toLowerCase().includes(q)
          || (r.glAccountName || '').toLowerCase().includes(q)
          || (r.supplierName || '').toLowerCase().includes(q)
          || (r.clientName || '').toLowerCase().includes(q);
      })
    : rules;

  const resetForm = () => {
    setForm({ ruleName: '', matchField: 'description', matchType: 'contains', matchPattern: '', glAccountId: '', supplierId: '', clientId: '', vatCode: 'none', descriptionTemplate: '', priority: '100' });
    setEditingRule(null);
    setShowForm(false);
    setPreviewCount(null);
  };

  const handleEdit = (rule: Rule) => {
    setForm({
      ruleName: rule.ruleName,
      matchField: rule.matchField,
      matchType: rule.matchType,
      matchPattern: rule.matchPattern,
      glAccountId: rule.glAccountId || '',
      supplierId: rule.supplierId || '',
      clientId: rule.clientId || '',
      vatCode: rule.vatCode || 'none',
      descriptionTemplate: rule.descriptionTemplate || '',
      priority: String(rule.priority),
    });
    setEditingRule(rule);
    setShowForm(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(''); setBusy('new');
    try {
      const payload = {
        ruleName: form.ruleName, matchField: form.matchField, matchType: form.matchType,
        matchPattern: form.matchPattern, glAccountId: form.glAccountId,
        supplierId: form.supplierId || undefined,
        clientId: form.clientId || undefined,
        descriptionTemplate: form.descriptionTemplate || undefined,
        priority: Number(form.priority) || 100,
        vatCode: form.vatCode || 'none',
      };

      if (editingRule) {
        const res = await apiFetch('/api/accounting/bank-rules-action', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ action: 'update', id: editingRule.id, ...payload }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to update rule');
      } else {
        const res = await apiFetch('/api/accounting/bank-rules', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify(payload),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to create rule');
      }

      resetForm();
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(''); }
  };

  const doAction = async (action: string, id?: string, extra?: Record<string, unknown>) => {
    setBusy(id || action);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/bank-rules-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify({ action, id, ...extra }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || `${action} failed`);
      if (action === 'apply' && json.data) setApplyResult(json.data);
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : `${action} failed`);
    } finally {
      setBusy('');
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/bank-reconciliation" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
            <ArrowLeft className="h-4 w-4" /> Back to Reconciliation
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-yellow-500/10"><Zap className="h-6 w-6 text-yellow-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Categorisation Rules</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Auto-categorise bank transactions by pattern matching</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {bankAccounts.length > 1 && (
                <select
                  value={selectedBankId}
                  onChange={e => setSelectedBankId(e.target.value)}
                  className="ff-select text-sm py-2 px-3"
                >
                  {bankAccounts.map(a => (
                    <option key={a.id} value={a.id}>{a.accountCode} — {a.accountName}</option>
                  ))}
                </select>
              )}
              {selected.size > 0 && (
                <button
                  onClick={handleBulkDelete}
                  disabled={bulkDeleting}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 text-sm font-medium disabled:opacity-50"
                >
                  {bulkDeleting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                  Delete {selected.size} selected
                </button>
              )}
              <button
                onClick={() => doAction('apply', undefined, { bankAccountId: selectedBankId })}
                disabled={!!busy || !selectedBankId}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50"
              >
                {busy === 'apply' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />} Apply Rules
              </button>
              <button onClick={() => { resetForm(); setShowForm(v => !v); }} className="inline-flex items-center gap-2 px-4 py-2 bg-yellow-600 text-white rounded-lg hover:bg-yellow-700 text-sm font-medium">
                <Plus className="h-4 w-4" /> New Rule
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}
          {applyResult && (
            <div className="p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm">
              Rules applied: {applyResult.applied} categorised, {applyResult.skipped} skipped
            </div>
          )}

          {showForm && (
            <form onSubmit={handleSubmit} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                {editingRule ? 'Edit Categorisation Rule' : 'New Categorisation Rule'}
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <input value={form.ruleName} onChange={e => setForm(f => ({ ...f, ruleName: e.target.value }))} className="ff-input" placeholder="Rule Name *" required />
                <select value={form.matchField} onChange={e => setForm(f => ({ ...f, matchField: e.target.value }))} className="ff-select">
                  <option value="description">Match Description</option>
                  <option value="reference">Match Reference</option>
                  <option value="both">Match Both</option>
                </select>
                <select value={form.matchType} onChange={e => setForm(f => ({ ...f, matchType: e.target.value }))} className="ff-select">
                  <option value="contains">Contains</option>
                  <option value="starts_with">Starts With</option>
                  <option value="ends_with">Ends With</option>
                  <option value="exact">Exact Match</option>
                </select>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
