                    <td className="px-4 py-3"><code className="px-2 py-0.5 rounded bg-[var(--ff-bg-primary)] text-yellow-400 text-xs">{rule.matchPattern}</code></td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] text-xs">
