                        </button>
                        <button onClick={() => doAction('delete', rule.id)} disabled={busy === rule.id} className="p-1 text-red-400 hover:text-red-300" title="Delete">
                          {busy === rule.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * VF Storage Adapter
 * Connects to the VF Server storage service (100.96.203.105:8091)
 *
 * Environment Variables:
 * - VF_STORAGE_URL: Override the base URL (default: http://100.96.203.105:8091)
 */

import { log } from '@/lib/logger';
import {
  VF_STORAGE_CONFIG,
  VFStorageUploadResponse,
  VFStorageFile,
} from '@/types/storage.types';

const VF_STORAGE_BASE_URL = process.env.VF_STORAGE_URL || VF_STORAGE_CONFIG.baseUrl;

/** VF Storage Service for file operations */
export class VFStorageService {
  private baseUrl: string;

  constructor(baseUrl?: string) {
    this.baseUrl = baseUrl || VF_STORAGE_BASE_URL;
  }

  /** Check if VF Storage server is healthy */
  async checkHealth(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/health`, {
        method: 'GET',
        headers: { Accept: 'application/json' },
      });
      return response.ok;
    } catch (error) {
      log.warn('VF Storage health check failed', { data: error }, 'vf-storage');
      return false;
    }
  }

  /**
   * Upload a file to VF Storage
   * @param file   - File or Buffer to upload
   * @param type   - Storage type (e.g., 'accounting')
   * @param category - Category within type (e.g., 'supplier_invoice')
   * @param fileName - Original filename
   */
  async uploadFile(
    file: Buffer | File | Blob,
    type: string,
    category: string,
    fileName: string
  ): Promise<VFStorageUploadResponse> {
    try {
      const formData = new FormData();

      if (file instanceof Buffer) {
        const blob = new Blob([file as unknown as BlobPart]);
        formData.append('file', blob, fileName);
      } else {
        formData.append('file', file as Blob, fileName);
      }

      const url = `${this.baseUrl}/upload/${type}/${encodeURIComponent(category)}`;
      log.info(`Uploading to VF Storage: ${url}`, undefined, 'vf-storage');

      const response = await fetch(url, { method: 'POST', body: formData });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Upload failed: ${response.status} - ${errorText}`);
      }

      const result = await response.json();
      const actualFilename = (result.filename as string) || fileName;
      const actualPath = (result.path as string) || `${type}/${category}/${actualFilename}`;
      const actualUrl = `/storage/${actualPath}`;

      return {
        success: true,
        filename: actualFilename,
        path: actualPath,
        url: actualUrl,
        size: (result.size as number) || (file instanceof Buffer ? file.length : 0),
      };
    } catch (error) {
      log.error('VF Storage upload error', { data: error }, 'vf-storage');
      throw error;
    }
  }

  /** List files in a directory */
  async listFiles(type: string, category: string): Promise<VFStorageFile[]> {
    try {
      const url = `${this.baseUrl}/list/${type}/${category}`;
      const response = await fetch(url, {
        method: 'GET',
        headers: { Accept: 'application/json' },
      });

      if (!response.ok) {
        throw new Error(`List failed: ${response.status}`);
      }

      const result = await response.json();
      return (result.files as VFStorageFile[]) || [];
    } catch (error) {
      log.error('VF Storage list error', { data: error }, 'vf-storage');
      return [];
    }
  }

  /** Delete a file from VF Storage */
  async deleteFile(type: string, category: string, filename: string): Promise<boolean> {
    try {
      const url = `${this.baseUrl}/delete/${type}/${category}/${filename}`;
      const response = await fetch(url, { method: 'DELETE' });

      if (!response.ok) {
        throw new Error(`Delete failed: ${response.status}`);
      }

      return true;
    } catch (error) {
      log.error('VF Storage delete error', { data: error }, 'vf-storage');
      return false;
    }
  }

  /** Get the full URL for a stored file (public HTTPS URL via /storage/ proxy) */
  getFileUrl(type: string, category: string, filename: string): string {
    return `/storage/${type}/${category}/${filename}`;
  }
}

// Singleton instance
export const vfStorage = new VFStorageService();

/**
 * Normalize a storage URL to ensure it uses the /storage/ proxy path.
 * Handles legacy URLs that were stored without the /storage/ prefix.
 */
export function normalizeStorageUrl(url: string | undefined | null): string | undefined {
  if (!url) return undefined;

  const vfDomains = ['vf.fibreflow.app', 'dev.fibreflow.app', 'app.fibreflow.app'];
  const isVFUrl = vfDomains.some((domain) => url.includes(domain));
  if (!isVFUrl) return url;

  if (url.includes('/storage/')) return url;

  const storagePaths = ['/procurement/', '/accounting/', '/staff/', '/fleet/', '/contractors/', '/assets/'];
  const needsStorage = storagePaths.some((path) => url.includes(path));
  if (!needsStorage) return url;

  for (const path of storagePaths) {
    if (url.includes(path)) {
      return url.replace(path, `/storage${path}`);
    }
  }

  return url;
}

export default VFStorageService;

/**
 * SARS Compliance Dashboard
 * Overview of upcoming deadlines, quick links, and recent submissions.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  Building2, FileText, Calendar, Clock,
  CheckCircle2, AlertTriangle, XCircle,
  Loader2, ChevronRight,
} from 'lucide-react';
import { formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface ComplianceEvent {
  id?: string;
  eventType: string;
  dueDate: string;
  description: string;
  status: 'pending' | 'completed' | 'overdue';
  submissionId?: string;
}

interface Submission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  submissionReference: string | null;
  submittedAt: string | null;
  createdAt: string;
}

const statusBadge = (status: string) => {
  switch (status) {
    case 'completed':
    case 'submitted':
    case 'accepted':
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400">
          <CheckCircle2 className="h-3 w-3" /> {status}
        </span>
      );
    case 'overdue':
    case 'rejected':
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-500/10 text-red-400">
          <XCircle className="h-3 w-3" /> {status}
        </span>
      );
    case 'pending':
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-500/10 text-amber-400">
          <Clock className="h-3 w-3" /> {status}
        </span>
      );
    default:
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-gray-500/10 text-gray-400">
          {status}
        </span>
      );
  }
};

const daysUntil = (d: string) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(d);
  due.setHours(0, 0, 0, 0);
  return Math.ceil((due.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
};

export default function SARSDashboard() {
  const [events, setEvents] = useState<ComplianceEvent[]>([]);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [compRes, subRes] = await Promise.all([
        apiFetch('/api/accounting/sars/sars-compliance', { credentials: 'include' }),
        apiFetch('/api/accounting/sars/sars-submissions', { credentials: 'include' }),
      ]);
      const compJson = await compRes.json();
      const subJson = await subRes.json();
      setEvents(compJson.data?.events || []);
      setSubmissions(subJson.data?.items || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  // Filter upcoming events (next 90 days + overdue)
  const upcomingEvents = events.filter((e) => {
    const days = daysUntil(e.dueDate);
    return e.status === 'overdue' || (e.status === 'pending' && days <= 90);
  });

  const overdueCount = events.filter((e) => e.status === 'overdue').length;
  const pendingCount = upcomingEvents.filter((e) => e.status === 'pending').length;
  const completedCount = events.filter((e) => e.status === 'completed').length;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Building2 className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">SARS eFiling</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Tax compliance dashboard — VAT201, EMP201, and submission tracking
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
              <span className="ml-2 text-[var(--ff-text-secondary)]">Loading compliance data...</span>
            </div>
          ) : (
            <>
              {/* Summary Cards */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <SummaryCard
                  label="Overdue"
                  value={overdueCount}
                  color="red"
                  icon={<XCircle className="h-5 w-5" />}
                />
                <SummaryCard
                  label="Upcoming (90 days)"
                  value={pendingCount}
                  color="amber"
                  icon={<AlertTriangle className="h-5 w-5" />}
                />
                <SummaryCard
                  label="Completed"
                  value={completedCount}
                  color="emerald"
                  icon={<CheckCircle2 className="h-5 w-5" />}
                />
                <SummaryCard
                  label="Submissions"
                  value={submissions.length}
                  color="teal"
                  icon={<FileText className="h-5 w-5" />}
                />
              </div>

              {/* Quick Actions */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <QuickAction
                  href="/accounting/sars/vat201"
                  title="Generate VAT201"
                  description="VAT return for bi-monthly period"
                  icon={<FileText className="h-5 w-5 text-teal-500" />}
                />
                <QuickAction
                  href="/accounting/sars/emp201"
                  title="Generate EMP201"
                  description="Monthly PAYE, UIF and SDL return"
                  icon={<FileText className="h-5 w-5 text-blue-500" />}
                />
                <QuickAction
                  href="/accounting/sars/submissions"
                  title="Submission History"
                  description="View all past SARS submissions"
                  icon={<Calendar className="h-5 w-5 text-purple-500" />}
                />
              </div>

              {/* Compliance Calendar */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
                <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] flex items-center gap-2">
                    <Calendar className="h-5 w-5 text-teal-500" />
                    Upcoming Deadlines
                  </h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                        <th className="px-4 py-3">Type</th>
                        <th className="px-4 py-3">Description</th>
                        <th className="px-4 py-3">Due Date</th>
                        <th className="px-4 py-3">Days</th>
                        <th className="px-4 py-3">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {upcomingEvents.length === 0 && (
                        <tr>
                          <td colSpan={5} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                            No upcoming deadlines in the next 90 days.
                          </td>
                        </tr>
                      )}
                      {upcomingEvents.map((evt, idx) => {
                        const days = daysUntil(evt.dueDate);
                        return (
                          <tr
                            key={`${evt.eventType}-${evt.dueDate}-${idx}`}
                            className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50"
                          >
                            <td className="px-4 py-3">
                              <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-teal-500/10 text-teal-400">
                                {evt.eventType.replace('_DUE', '').replace('_', ' ')}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-primary)]">{evt.description}</td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{formatDate(evt.dueDate)}</td>
                            <td className="px-4 py-3">
                              <span className={`font-medium ${
                                days < 0 ? 'text-red-400' : days <= 14 ? 'text-amber-400' : 'text-[var(--ff-text-secondary)]'
                              }`}>
                                {days < 0 ? `${Math.abs(days)}d overdue` : days === 0 ? 'Today' : `${days}d`}
                              </span>
                            </td>
                            <td className="px-4 py-3">{statusBadge(evt.status)}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Recent Submissions */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
                <div className="px-4 py-3 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] flex items-center gap-2">
                    <FileText className="h-5 w-5 text-teal-500" />
                    Recent Submissions
                  </h2>
                  <Link
