/**
 * PRD-060: FibreFlow Accounting Module
 * Payment Allocation Validation
 *
 * Validates that payment allocations across invoices are correct:
 * - No overpayment per invoice
 * - Total allocations don't exceed payment amount
 * - No duplicate invoice allocations
 * - All referenced invoices exist
 */

import type {
  PaymentAllocationInput,
  PaymentAllocationResult,
  InvoiceForAllocation,
} from '../types/ap.types';

/**
 * Validate payment allocations against invoices.
 */
export function validatePaymentAllocations(
  paymentAmount: number,
  allocations: PaymentAllocationInput[],
  invoices: InvoiceForAllocation[]
): PaymentAllocationResult {
  const errors: string[] = [];
  const invoiceMap = new Map(invoices.map(inv => [inv.id, inv]));
  const resultAllocations: PaymentAllocationResult['allocations'] = [];

  // Check for duplicate invoice IDs
  const invoiceIds = allocations.map(a => a.invoiceId);
  const duplicates = invoiceIds.filter((id, i) => invoiceIds.indexOf(id) !== i);
  if (duplicates.length > 0) {
    errors.push(`Duplicate invoice allocations: ${duplicates.join(', ')}`);
    return {
      valid: false,
      allocations: [],
      totalAllocated: 0,
      unallocated: paymentAmount,
      errors,
    };
  }

  let totalAllocated = 0;

  for (const alloc of allocations) {
    // Validate amount is positive
    if (alloc.amount <= 0) {
      errors.push(`Allocation amount must be positive (invoice: ${alloc.invoiceId}, amount: ${alloc.amount})`);
      continue;
    }

    // Validate invoice exists
    const invoice = invoiceMap.get(alloc.invoiceId);
    if (!invoice) {
      errors.push(`Invoice not found: ${alloc.invoiceId}`);
      continue;
    }

    // Validate doesn't exceed invoice balance
    if (alloc.amount > invoice.balance) {
      errors.push(
        `Allocation R${alloc.amount.toFixed(2)} exceeds invoice ${invoice.invoiceNumber} balance of R${invoice.balance.toFixed(2)}`
      );
      continue;
    }

    const newBalance = Math.round((invoice.balance - alloc.amount) * 100) / 100;

    resultAllocations.push({
      invoiceId: alloc.invoiceId,
      amount: alloc.amount,
      newBalance,
      fullyPaid: newBalance === 0,
    });

    totalAllocated += alloc.amount;
  }

  // Check total allocations don't exceed payment amount
  totalAllocated = Math.round(totalAllocated * 100) / 100;
  if (totalAllocated > paymentAmount) {
    errors.push(
      `Total allocations R${totalAllocated.toFixed(2)} exceed payment amount R${paymentAmount.toFixed(2)}`
    );
  }

  const unallocated = Math.round((paymentAmount - totalAllocated) * 100) / 100;

  return {
    valid: errors.length === 0,
    allocations: resultAllocations,
    totalAllocated,
    unallocated: Math.max(0, unallocated),
    errors,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * 3-Way Match Validation (PO ↔ GRN ↔ Invoice)
 *
 * Validates that a supplier invoice aligns with the
 * purchase order and goods receipt note.
 */

import type { ThreeWayMatchInput, ThreeWayMatchResult, InvoiceMatchStatus } from '../types/ap.types';

const DEFAULT_TOLERANCE_PERCENT = 2;

/**
 * Validate 3-way match between PO, GRN, and supplier invoice.
 *
 * Checks:
 * 1. Invoice quantity matches PO quantity
 * 2. Invoice unit price matches PO unit price (within tolerance)
 * 3. GRN received quantity matches invoice quantity
 */
export function validateThreeWayMatch(input: ThreeWayMatchInput): ThreeWayMatchResult {
  const tolerance = input.tolerancePercent ?? DEFAULT_TOLERANCE_PERCENT;
  const mismatches: string[] = [];

  // Check quantity match: Invoice vs PO
  const quantityMatch = input.invoiceQuantity === input.poQuantity;
  if (!quantityMatch) {
    mismatches.push(
      `Invoice quantity (${input.invoiceQuantity}) does not match PO quantity (${input.poQuantity})`
    );
  }

  // Check price match: Invoice vs PO (within tolerance)
  const priceDiffPercent =
    input.poUnitPrice > 0
      ? Math.abs(input.invoiceUnitPrice - input.poUnitPrice) / input.poUnitPrice * 100
      : input.invoiceUnitPrice > 0 ? 100 : 0;

  const priceMatch = priceDiffPercent <= tolerance;
  if (!priceMatch) {
    mismatches.push(
      `Invoice unit price (${input.invoiceUnitPrice}) differs from PO price (${input.poUnitPrice}) by ${priceDiffPercent.toFixed(1)}%, exceeds ${tolerance}% tolerance`
    );
  }

  // Check GRN match: GRN received vs Invoice quantity
  const grnMatch = input.grnQuantityReceived === input.invoiceQuantity;
  if (!grnMatch) {
    mismatches.push(
      `GRN received quantity (${input.grnQuantityReceived}) does not match invoice quantity (${input.invoiceQuantity})`
    );
  }

  // Determine overall status
  let status: InvoiceMatchStatus;
  if (quantityMatch && priceMatch && grnMatch) {
    status = 'fully_matched';
  } else if (quantityMatch && priceMatch && !grnMatch) {
    status = 'po_matched';
  } else if (grnMatch && (!quantityMatch || !priceMatch)) {
    status = 'grn_matched';
  } else {
    status = 'unmatched';
  }

  return {
    status,
    quantityMatch,
    priceMatch,
    grnMatch,
    mismatches,
  };
}

