/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getRecurringInvoices(_companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      WHERE ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      WHERE ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(_companyId: string, 
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(_companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(_companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id}`) as Row[];

/**
 * Supplier Batch Payment Service
 * Phase 1 Sage Alignment: Bulk supplier payment processing
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getAccountByCode } from './chartOfAccountsService';
import type { SupplierPaymentBatch, BatchPaymentCreateInput } from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getBatches(_companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: SupplierPaymentBatch[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM supplier_payment_batches WHERE status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM supplier_payment_batches WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM supplier_payment_batches
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_payment_batches`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function getBatchById(_companyId: string, id: string): Promise<SupplierPaymentBatch | null> {
  const rows = (await sql`SELECT * FROM supplier_payment_batches WHERE id = ${id}`) as Row[];
  if (!rows[0]) return null;
  return mapRow(rows[0]);
}

export async function createBatch(_companyId: string, 
  input: BatchPaymentCreateInput,
  userId: string
): Promise<SupplierPaymentBatch> {
  let totalAmount = 0;
  const paymentMethod = input.paymentMethod || 'eft';

  // Create batch record first
  const batchRows = (await sql`
    INSERT INTO supplier_payment_batches (
      batch_date, payment_method, bank_account_id, notes,
      payment_count, total_amount, created_by
    ) VALUES (
      ${input.batchDate || new Date().toISOString().split('T')[0]},
      ${paymentMethod}, ${input.bankAccountId || null}, ${input.notes || null},
      ${input.payments.length}, 0, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  const batchId = String(batchRows[0]!.id);

  // Create individual payments linked to batch
  for (const p of input.payments) {
    const payTotal = p.invoiceAllocations.reduce((s, a) => s + a.amount, 0);
    totalAmount += payTotal;

    const payRows = (await sql`
      INSERT INTO supplier_payments (
        supplier_id, payment_date, total_amount, payment_method,
        status, batch_id, created_by
      ) VALUES (
        ${p.supplierId}::UUID, ${input.batchDate || new Date().toISOString().split('T')[0]},
        ${payTotal}, ${paymentMethod}, 'draft', ${batchId}::UUID, ${userId}::UUID
      ) RETURNING id
    `) as Row[];

    const paymentId = String(payRows[0]!.id);
    for (const alloc of p.invoiceAllocations) {
      await sql`
        INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
        VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
      `;
    }
  }

  // Update batch total
  await sql`
    UPDATE supplier_payment_batches SET total_amount = ${totalAmount} WHERE id = ${batchId}
  `;

/**
 * Create Batch Payment Page
 * Phase 1 Sage Alignment: Select suppliers and invoices for bulk payment
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Layers, Plus, Trash2, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface Supplier { id: string; company_name: string }
interface Invoice { id: string; invoice_number: string; total_amount: number; amount_paid: number; supplier_id: string }
interface BatchLine { key: string; supplierId: string; invoiceId: string; amount: number }

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

export default function NewBatchPaymentPage() {
  const router = useRouter();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [lines, setLines] = useState<BatchLine[]>([{ key: crypto.randomUUID(), supplierId: '', invoiceId: '', amount: 0 }]);
  const [method, setMethod] = useState('eft');
  const [notes, setNotes] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    apiFetch('/api/suppliers', { credentials: 'include' }).then(r => r.json()).then(res => {
      const d = res.data || res;
      setSuppliers(Array.isArray(d) ? d : d.suppliers || []);
    });
    apiFetch('/api/accounting/supplier-invoices?status=approved&status=partially_paid', { credentials: 'include' }).then(r => r.json()).then(res => {
      const d = res.data || res;
      const list = Array.isArray(d) ? d : d.invoices || d.items || [];
      setInvoices(list.filter((inv: Invoice) => Number(inv.total_amount) - Number(inv.amount_paid) > 0.01));
    });
  }, []);

  const total = lines.reduce((s, l) => s + (l.amount || 0), 0);

  const addLine = () => setLines(p => [...p, { key: crypto.randomUUID(), supplierId: '', invoiceId: '', amount: 0 }]);
  const removeLine = (key: string) => setLines(p => p.filter(l => l.key !== key));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(''); setBusy(true);

    // Group by supplier
    const grouped: Record<string, { invoiceId: string; amount: number }[]> = {};
    for (const l of lines) {
      if (!l.supplierId || !l.invoiceId || l.amount <= 0) continue;
      if (!grouped[l.supplierId]) grouped[l.supplierId] = [];
      grouped[l.supplierId]!.push({ invoiceId: l.invoiceId, amount: l.amount });
    }

    const payments = Object.entries(grouped).map(([supplierId, allocs]) => ({
      supplierId,
      invoiceAllocations: allocs,
    }));

    if (payments.length === 0) { setError('Add at least one payment'); setBusy(false); return; }

    try {
      const res = await apiFetch('/api/accounting/batch-payments', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ paymentMethod: method, notes: notes || undefined, payments }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      router.push('/accounting/batch-payments');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">

/**
 * Payroll Employee Detail API
 * GET /api/payroll/employees-detail?id=xxx  - Get single employee
 * PUT /api/payroll/employees-detail?id=xxx  - Update employee
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getEmployee,
  updateEmployee,
  getEmployeePayHistory,
  getEmployeePayslips,
} from '@/modules/payroll/payrollService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { id } = req.query;
  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Employee ID is required');
  }

  if (req.method === 'GET') {
    try {
      const employee = await getEmployee(id);
      if (!employee) {
        return apiResponse.notFound(res, 'Employee', id);
      }

      const payHistory = await getEmployeePayHistory(id);
      const payslips = await getEmployeePayslips(id);

      return apiResponse.success(res, {
        ...employee,
        pay_history: payHistory,
        payslip_history: payslips,
      });
    } catch (err) {
      log.error('employee detail GET failed', { id, error: err }, 'payroll-api');
      return apiResponse.internalError(res, err, 'Failed to fetch employee');
    }
  }

  if (req.method === 'PUT') {
    try {
      const employee = await updateEmployee(id, req.body);
      return apiResponse.success(res, employee);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update employee';
      log.error('employee detail PUT failed', { id, error: err }, 'payroll-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Document Capture API
 * POST /api/accounting/document-capture  — Upload PDF, extract data, save
 * GET  /api/accounting/document-capture  — List captured documents
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { Writable } from 'stream';
import formidable from 'formidable';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf } from '@/modules/accounting/services/ocrService';
import type { CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

/** In-memory file buffer attached to formidable file objects */
const fileBuffers = new WeakMap<formidable.File, Buffer>();

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        return part.mimetype === 'application/pdf' || part.mimetype === null || part.mimetype === undefined;
      },
      // Write to memory instead of disk to avoid read-only filesystem issues
      fileWriteStreamHandler: (file) => {
        const chunks: Buffer[] = [];
        const writable = new Writable({
          write(chunk, _encoding, callback) {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            callback();
          },
          final(callback) {
            fileBuffers.set(file as unknown as formidable.File, Buffer.concat(chunks));
            callback();
          },
        });
        return writable;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
