function getConfig() {
  const baseUrl = process.env.VLLM_BASE_URL;
  if (!baseUrl) return null;
  return {
    baseUrl: baseUrl.replace(/\/+$/, ''),
    model: process.env.VLLM_MODEL || 'Qwen/Qwen3-VL-8B',
    apiKey: process.env.VLLM_API_KEY || 'EMPTY',
