// THREE-WAY MATCHING (PO → GRN → Invoice)
// ═══════════════════════════════════════════════════════════════════════════

describe('Three-Way Match', () => {
  it('fully matches when all quantities and prices align', () => {
    const result = calculateThreeWayMatch({
      poQuantity: 100,
      poUnitPrice: 50,
