/**
 * Onboarding wizard step components (Steps 1-7).
 */

import { useRef } from 'react';
import { Upload, X } from 'lucide-react';

// ── Types ───────────────────────────────────────────────────────────────────

export interface DocFile {
  type: string; name: string; data: string; mimeType: string; size: number;
}

export interface WizardData {
  name: string; tradingName: string; registrationNumber: string;
  vatNumber: string; taxNumber: string;
  addressLine1: string; addressLine2: string; city: string;
  province: string; postalCode: string; country: string;
  phone: string; email: string; website: string;
  logoData: string;
  bankName: string; bankAccountNumber: string;
  bankBranchCode: string; bankAccountType: string;
  financialYearStart: number; vatPeriod: string; defaultCurrency: string;
  documents: DocFile[];
}

export const INITIAL_WIZARD: WizardData = {
  name: '', tradingName: '', registrationNumber: '', vatNumber: '', taxNumber: '',
  addressLine1: '', addressLine2: '', city: '', province: '', postalCode: '',
  country: 'South Africa', phone: '', email: '', website: '', logoData: '',
  bankName: '', bankAccountNumber: '', bankBranchCode: '', bankAccountType: 'Current',
  financialYearStart: 3, vatPeriod: 'Bi-Monthly', defaultCurrency: 'ZAR',
  documents: [],
};

export type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

// ── Constants ───────────────────────────────────────────────────────────────

const PROVINCES = [
  'Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo',
  'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape',
];
const SA_BANKS = [
  'ABSA', 'Capitec', 'FNB', 'Investec', 'Nedbank', 'Standard Bank',
  'TymeBank', 'African Bank', 'Discovery Bank', 'Bank Zero',
];
export const MONTHS = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
];
export const DOC_SLOTS = [
  { type: 'cipc', label: 'CIPC Registration Certificate' },
  { type: 'tax_clearance', label: 'SARS Tax Clearance Certificate' },
  { type: 'bbbee', label: 'B-BBEE Certificate' },
  { type: 'vat_reg', label: 'VAT Registration Certificate' },
];

// ── Shared UI ───────────────────────────────────────────────────────────────

const inputCls = 'w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition';
const labelCls = 'block text-xs font-medium text-gray-400 mb-1.5';

function Field({ label, value, onChange, placeholder, required, type = 'text' }: {
  label: string; value: string; onChange: (v: string) => void;
  placeholder?: string; required?: boolean; type?: string;
}) {
  return (
    <div>
      <label className={labelCls}>{label}{required && <span className="text-red-400 ml-0.5">*</span>}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)}
        placeholder={placeholder} className={inputCls} />
    </div>
  );
}

function Select({ label, value, onChange, children }: {
  label: string; value: string | number; onChange: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className={labelCls}>{label}</label>
      <select value={value} onChange={e => onChange(e.target.value)} className={inputCls}>
        {children}
      </select>
    </div>
  );
}

// ── Step 1: Company Details ─────────────────────────────────────────────────

export function Step1({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Company Name" value={d.name} onChange={v => set('name', v)} placeholder="Acme (Pty) Ltd" required />
      <Field label="Trading Name" value={d.tradingName} onChange={v => set('tradingName', v)} placeholder="Acme" />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Registration Number (CIPC)" value={d.registrationNumber} onChange={v => set('registrationNumber', v)} />
        <Field label="VAT Number" value={d.vatNumber} onChange={v => set('vatNumber', v)} />
        <Field label="Income Tax Number" value={d.taxNumber} onChange={v => set('taxNumber', v)} />
      </div>
    </div>
  );
}

// ── Step 2: Address & Contact ───────────────────────────────────────────────

export function Step2({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Address Line 1" value={d.addressLine1} onChange={v => set('addressLine1', v)} />
      <Field label="Address Line 2" value={d.addressLine2} onChange={v => set('addressLine2', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="City" value={d.city} onChange={v => set('city', v)} />
        <Select label="Province" value={d.province} onChange={v => set('province', v)}>
          <option value="">Select...</option>
          {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
        </Select>
        <Field label="Postal Code" value={d.postalCode} onChange={v => set('postalCode', v)} />
      </div>
      <Field label="Country" value={d.country} onChange={v => set('country', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Phone" value={d.phone} onChange={v => set('phone', v)} type="tel" />
        <Field label="Email" value={d.email} onChange={v => set('email', v)} type="email" />
        <Field label="Website" value={d.website} onChange={v => set('website', v)} />
      </div>
    </div>
  );
}

// ── Step 3: Logo Upload ─────────────────────────────────────────────────────

export function Step3({ d, set }: { d: WizardData; set: SetFn }) {
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return;
    if (file.size > 2 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => set('logoData', reader.result as string);
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center gap-4">
      {d.logoData ? (
        <div className="relative">
          <img src={d.logoData} alt="Logo" className="w-32 h-32 rounded-lg object-contain bg-gray-800" />
          <button onClick={() => set('logoData', '')}
            className="absolute -top-2 -right-2 bg-red-600 rounded-full p-1 hover:bg-red-500">
            <X className="w-3 h-3" />
          </button>
        </div>
      ) : (
        <div
          onDragOver={e => e.preventDefault()}
          onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) handleFile(f); }}
          className="w-full border-2 border-dashed border-gray-600 rounded-xl p-10 text-center hover:border-teal-500 transition-colors cursor-pointer"
          onClick={() => fileRef.current?.click()}
        >
          <Upload className="w-10 h-10 text-gray-500 mx-auto mb-3" />
          <p className="text-sm text-gray-400">Drag & drop your logo here, or click to browse</p>
          <p className="text-xs text-gray-500 mt-1">JPEG, PNG, or WebP. Max 2 MB</p>
        </div>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden"
        onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f); }} />
      {!d.logoData && (
        <button onClick={() => fileRef.current?.click()}
          className="text-sm text-teal-400 hover:text-teal-300 transition-colors">
          Browse files
        </button>
      )}
    </div>
  );
}

// ── Step 4: Banking Details ─────────────────────────────────────────────────

export function Step4({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <div>
        <label className={labelCls}>Bank Name</label>
        <input list="sa-banks" value={d.bankName} onChange={e => set('bankName', e.target.value)}
          className={inputCls} placeholder="Select or type..." />
        <datalist id="sa-banks">
          {SA_BANKS.map(b => <option key={b} value={b} />)}
        </datalist>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <Field label="Account Number" value={d.bankAccountNumber} onChange={v => set('bankAccountNumber', v)} />
        <Field label="Branch Code" value={d.bankBranchCode} onChange={v => set('bankBranchCode', v)} />
      </div>
      <Select label="Account Type" value={d.bankAccountType} onChange={v => set('bankAccountType', v)}>
        {['Current', 'Savings', 'Transmission', 'Credit Card'].map(t =>
          <option key={t} value={t}>{t}</option>
        )}
      </Select>
    </div>
  );
}

// ── Step 5: Financial Preferences ───────────────────────────────────────────

export function Step5({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Select label="Financial Year Start" value={d.financialYearStart}
        onChange={v => set('financialYearStart', parseInt(v, 10))}>
        {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
      </Select>
      <Select label="VAT Period" value={d.vatPeriod} onChange={v => set('vatPeriod', v)}>
        <option value="Monthly">Monthly</option>
        <option value="Bi-Monthly">Bi-Monthly</option>
      </Select>
      <Select label="Default Currency" value={d.defaultCurrency} onChange={v => set('defaultCurrency', v)}>
        {['ZAR', 'USD', 'EUR', 'GBP'].map(c => <option key={c} value={c}>{c}</option>)}
      </Select>
    </div>
  );
}

// ── Step 6: Statutory Documents ─────────────────────────────────────────────

export function Step6({ d, set }: { d: WizardData; set: SetFn }) {
  const handleDocFile = (slot: typeof DOC_SLOTS[number], file: File) => {
    if (file.size > 10 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => {
      const newDoc: DocFile = {
        type: slot.type, name: file.name,
        data: reader.result as string, mimeType: file.type, size: file.size,
      };
      set('documents', [...d.documents.filter(dd => dd.type !== slot.type), newDoc]);
    };
    reader.readAsDataURL(file);
  };

  const removeDoc = (type: string) => set('documents', d.documents.filter(dd => dd.type !== type));

  return (
    <div className="grid gap-4">
      {DOC_SLOTS.map(slot => {
        const doc = d.documents.find(dd => dd.type === slot.type);
        return (
          <div key={slot.type} className="border border-gray-700 rounded-lg p-4">
            <p className="text-sm font-medium text-gray-300 mb-2">{slot.label}</p>
            {doc ? (
              <div className="flex items-center justify-between">
                <div className="text-xs text-gray-400">
                  {doc.name} ({(doc.size / 1024).toFixed(0)} KB)
                </div>
                <button onClick={() => removeDoc(slot.type)}
                  className="text-xs text-red-400 hover:text-red-300">Remove</button>
              </div>
            ) : (
              <label className="flex items-center gap-2 cursor-pointer text-xs text-teal-400 hover:text-teal-300">
                <Upload className="w-3.5 h-3.5" /> Upload
                <input type="file" className="hidden" accept="image/*,application/pdf"
                  onChange={e => { const f = e.target.files?.[0]; if (f) handleDocFile(slot, f); }} />
              </label>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Step 7: Review & Complete ───────────────────────────────────────────────

export function Step7({ d }: { d: WizardData }) {
  const section = (title: string, items: [string, string | undefined][]) => {
    const filtered = items.filter(([, v]) => v);
    if (filtered.length === 0) return null;
    return (
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">{title}</h3>
        <div className="grid gap-1">
          {filtered.map(([k, v]) => (
            <div key={k} className="flex gap-2 text-sm">
              <span className="text-gray-500 w-36 shrink-0">{k}:</span>
              <span className="text-gray-200">{v}</span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const addr = [d.addressLine1, d.addressLine2, d.city, d.province, d.postalCode]
    .filter(Boolean).join(', ');

  return (
    <div className="grid gap-6">
      {section('Company', [
        ['Name', d.name], ['Trading Name', d.tradingName],
        ['Registration', d.registrationNumber], ['VAT', d.vatNumber], ['Tax', d.taxNumber],
      ])}
      {section('Address & Contact', [
        ['Address', addr || undefined], ['Country', d.country],
        ['Phone', d.phone], ['Email', d.email], ['Website', d.website],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Logo</h3>
        {d.logoData ? (
          <img src={d.logoData} alt="Logo" className="w-16 h-16 rounded-lg object-contain bg-gray-800" />
        ) : (
          <p className="text-sm text-gray-500">Not uploaded</p>
        )}
      </div>
      {section('Banking', [
        ['Bank', d.bankName], ['Account', d.bankAccountNumber],
        ['Branch', d.bankBranchCode], ['Type', d.bankAccountType],
      ])}
      {section('Financial', [
        ['FY Start', MONTHS[d.financialYearStart - 1]],
        ['VAT Period', d.vatPeriod], ['Currency', d.defaultCurrency],
      ])}
      <div>
        <h3 className="text-sm font-semibold text-teal-400 mb-2">Documents</h3>
        {d.documents.length > 0 ? (
          <ul className="space-y-1">
            {d.documents.map(doc => (
              <li key={doc.type} className="text-sm text-gray-300">
                {DOC_SLOTS.find(s => s.type === doc.type)?.label || doc.type} — {doc.name}
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-sm text-gray-500">None uploaded</p>
        )}
      </div>
    </div>
  );
}

import { useState, useRef } from 'react';
import {
  FileText,
  Image as ImageIcon,
  File,
  Upload,
  Trash2,
  Download,
  Loader2,
  AlertCircle,
  X,
  Link2,
} from 'lucide-react';
import { useAccountingDocuments } from './useAccountingDocuments';
import {
  ACCOUNTING_DOCUMENT_TYPE_LABELS,
  DOCUMENT_TYPE_LABELS,
  type AccountingDocumentType,
  type AccountingEntityType,
} from '@/types/procurement/document.types';
import { formatDisplayDate } from '@/utils/dateFormat';

interface DocumentTypeOption {
  value: AccountingDocumentType;
  label: string;
}

interface AccountingDocumentPanelProps {
  entityType: AccountingEntityType;
  entityId: string;
  allowedTypes?: DocumentTypeOption[];
  readOnly?: boolean;
}

const DEFAULT_ALLOWED_TYPES: DocumentTypeOption[] = Object.entries(ACCOUNTING_DOCUMENT_TYPE_LABELS).map(
  ([value, label]) => ({ value: value as AccountingDocumentType, label })
);

function getFileIcon(mimeType?: string) {
  if (!mimeType) return File;
  if (mimeType === 'application/pdf') return FileText;
  if (mimeType.startsWith('image/')) return ImageIcon;
  return File;
}

function formatFileSize(bytes?: number): string {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getTypeLabel(docType: string): string {
  return (ACCOUNTING_DOCUMENT_TYPE_LABELS as Record<string, string>)[docType]
    || (DOCUMENT_TYPE_LABELS as Record<string, string>)[docType]
    || docType;
}

const LINK_REASON_LABELS: Record<string, string> = {
  po_invoice_link: 'Linked from PO',
  grn_invoice_link: 'Linked from GRN',
  manual: 'Manually linked',
};

export function AccountingDocumentPanel({
  entityType,
  entityId,
  allowedTypes = DEFAULT_ALLOWED_TYPES,
  readOnly = false,
}: AccountingDocumentPanelProps) {
  const { documents, loading, error, uploadDocument, deleteDocument, uploading } =
    useAccountingDocuments(entityType, entityId);

  const [showUpload, setShowUpload] = useState(false);
  const [selectedType, setSelectedType] = useState<AccountingDocumentType>(
    allowedTypes[0]?.value || 'other'
  );
  const [notes, setNotes] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;
    try {
      await uploadDocument(selectedFile, selectedType, notes || undefined);
      setShowUpload(false);
      setSelectedFile(null);
      setNotes('');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch {
      // Error handled by hook
    }
  };

  const handleDelete = async (docId: string, docName: string) => {
    if (!confirm(`Delete "${docName}"? This cannot be undone.`)) return;
    await deleteDocument(docId);
  };

  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--ff-border-light)]">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-blue-400" />
          <h3 className="font-semibold text-[var(--ff-text-primary)]">
            Documents {documents.length > 0 && `(${documents.length})`}
          </h3>
        </div>
        {!readOnly && (
          <button
            onClick={() => setShowUpload(!showUpload)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Upload className="h-4 w-4" />
            Upload
          </button>
        )}
      </div>

      {/* Upload Form */}
      {showUpload && (
        <div className="px-5 py-4 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
          <div className="space-y-3">
            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">File</label>
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"
                onChange={handleFileSelect}
                className="block w-full text-sm text-[var(--ff-text-secondary)] file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-sm file:bg-blue-600 file:text-white hover:file:bg-blue-700 file:cursor-pointer"
              />
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                PDF, JPEG, PNG, DOCX, XLSX — max 20MB
              </p>
            </div>

            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Document Type</label>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value as AccountingDocumentType)}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              >
                {allowedTypes.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">
                Notes <span className="text-[var(--ff-text-tertiary)]">(optional)</span>
              </label>
              <input
                type="text"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="e.g. Scanned invoice from supplier"
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm placeholder:text-[var(--ff-text-tertiary)]"
              />
            </div>

            <div className="flex items-center gap-2 pt-1">
              <button
                onClick={handleUpload}
                disabled={!selectedFile || uploading}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {uploading ? (
                  <><Loader2 className="h-4 w-4 animate-spin" /> Uploading...</>
                ) : (
                  <><Upload className="h-4 w-4" /> Upload Document</>
                )}
              </button>
              <button
                onClick={() => { setShowUpload(false); setSelectedFile(null); setNotes(''); }}
                className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <X className="h-4 w-4" /> Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="px-5 py-3 bg-red-500/10 border-b border-red-500/30 flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {/* Document List */}
      <div className="divide-y divide-[var(--ff-border-light)]">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-5 w-5 animate-spin text-blue-400" />
          </div>
        ) : documents.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="h-10 w-10 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
            <p className="text-sm text-[var(--ff-text-secondary)]">No documents uploaded yet</p>
          </div>
        ) : (
          documents.map((doc) => {
            const Icon = getFileIcon(doc.mimeType);
            const typeLabel = getTypeLabel(doc.documentType);
            const isLinked = doc.source === 'linked';

            return (
              <div
                key={`${doc.id}-${doc.source}`}
                className="flex items-center gap-3 px-5 py-3 hover:bg-[var(--ff-bg-hover)] transition-colors"
              >
                <div className={`p-2 rounded-lg shrink-0 ${isLinked ? 'bg-purple-500/10' : 'bg-blue-500/10'}`}>
                  <Icon className={`h-5 w-5 ${isLinked ? 'text-purple-400' : 'text-blue-400'}`} />
                </div>

                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                    {doc.documentName}
                  </p>
                  <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                    <span className="px-1.5 py-0.5 rounded bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]">
                      {typeLabel}
                    </span>
                    {isLinked && doc.linkReason && (
                      <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-purple-500/10 text-purple-400">
                        <Link2 className="h-3 w-3" />
                        {LINK_REASON_LABELS[doc.linkReason] || doc.linkReason}
                      </span>
                    )}
                    {doc.fileSize && <span>{formatFileSize(doc.fileSize)}</span>}
                    <span>{formatDisplayDate(doc.uploadedAt)}</span>
                    {doc.uploadedByName && <span>by {doc.uploadedByName}</span>}
                  </div>
                  {doc.notes && (
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5 truncate">{doc.notes}</p>
                  )}
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  <a
                    href={doc.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1.5 hover:bg-[var(--ff-bg-tertiary)] rounded-lg transition-colors"
                    title="Download"
                  >
                    <Download className="h-4 w-4 text-[var(--ff-text-secondary)]" />
                  </a>
                  {!readOnly && !isLinked && (
                    <button
                      onClick={() => handleDelete(doc.id, doc.documentName)}
                      className="p-1.5 hover:bg-red-500/10 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="h-4 w-4 text-red-400" />
                    </button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/**
 * Document Capture Hub
 * Upload PDFs, extract invoice/receipt data via OCR, review and act on results.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, Upload, Loader2, AlertCircle, FileText, CheckCircle2,
  XCircle, Eye, RefreshCw, ChevronRight,
} from 'lucide-react';
import { notify } from '@/utils/toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCapturePage() {
  const [documents, setDocuments] = useState<CapturedDocument[]>([]);
  const [total, setTotal] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  // Upload state
  const [isUploading, setIsUploading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadResult, setUploadResult] = useState<{ document: CapturedDocument; extracted: ExtractedDocument } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Review form state (after upload)
  const [reviewVendor, setReviewVendor] = useState('');
  const [reviewDate, setReviewDate] = useState('');
  const [reviewRef, setReviewRef] = useState('');
  const [reviewTotal, setReviewTotal] = useState('');
  const [reviewVat, setReviewVat] = useState('');
  const [reviewDocType, setReviewDocType] = useState('');
  const [reviewNotes, setReviewNotes] = useState('');

  const loadDocuments = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      const res = await apiFetch(`/api/accounting/document-capture?${params}`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');
      setDocuments(json.data || []);
      setTotal(json.pagination?.total || 0);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load documents');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { loadDocuments(); }, [loadDocuments]);

  // Populate review form when upload completes
  useEffect(() => {
    if (uploadResult) {
      const ex = uploadResult.extracted;
      setReviewVendor(ex.vendorName || '');
      setReviewDate(ex.date || '');
      setReviewRef(ex.referenceNumber || '');
      setReviewTotal(ex.totalAmount !== null ? String(ex.totalAmount) : '');
      setReviewVat(ex.vatAmount !== null ? String(ex.vatAmount) : '');
      setReviewDocType(ex.documentType || 'unknown');
      setReviewNotes('');
    }
  }, [uploadResult]);

  async function handleUpload(file: File) {
    const allowedExts = ['.pdf', '.jpg', '.jpeg', '.png', '.webp', '.tiff', '.tif'];
    const ext = file.name.toLowerCase().substring(file.name.lastIndexOf('.'));
    if (!allowedExts.includes(ext)) {
      notify.error('Supported formats: PDF, JPEG, PNG, WebP, TIFF');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      notify.error('File too large. Maximum size is 10MB.');
      return;
    }

    setIsUploading(true);
    setUploadResult(null);
    setError('');

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res = await apiFetch('/api/accounting/document-capture', {
        method: 'POST',
        body: formData,
      });

      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Upload failed');

      setUploadResult(json.data);
      notify.success('Document uploaded and processed');
      loadDocuments();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Upload failed';
      notify.error(msg);
      setError(msg);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) handleUpload(file);
  }

  function handleDragOver(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(true);
  }

  function handleDragLeave(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
  }

  async function handleConfirm() {
    if (!uploadResult) return;
    try {
      const res = await apiFetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'confirm',
          data: {
            vendorName: reviewVendor || null,
            documentDate: reviewDate || null,
            referenceNumber: reviewRef || null,
            totalAmount: reviewTotal ? parseFloat(reviewTotal) : null,
            vatAmount: reviewVat ? parseFloat(reviewVat) : null,
            documentType: reviewDocType || null,
            notes: reviewNotes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      notify.success('Document confirmed');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Confirm failed');
    }
  }

  async function handleReject() {
    if (!uploadResult) return;
    try {
      const res = await apiFetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'reject',
          data: { notes: reviewNotes || 'Rejected during review' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      notify.success('Document rejected');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Reject failed');
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Document Capture</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Upload invoices and receipts for automated data extraction
                </p>
              </div>
            </div>
            <button
              onClick={() => loadDocuments()}
              className="inline-flex items-center gap-2 px-3 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <RefreshCw className="h-4 w-4" />
              Refresh
            </button>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {/* Upload Zone */}
          <div
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            className={`relative border-2 border-dashed rounded-xl p-8 text-center transition-all cursor-pointer ${
              isDragging
                ? 'border-teal-500 bg-teal-500/5'
                : 'border-[var(--ff-border-light)] hover:border-teal-500/50 hover:bg-[var(--ff-bg-secondary)]'
            }`}
            onClick={() => fileInputRef.current?.click()}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,application/pdf,image/jpeg,image/png,image/webp,image/tiff"
              className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleUpload(file);
              }}
            />
            {isUploading ? (
              <div className="flex flex-col items-center gap-3">
                <Loader2 className="h-10 w-10 text-teal-500 animate-spin" />
                <p className="text-sm text-[var(--ff-text-secondary)]">Processing document...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                <Upload className="h-10 w-10 text-[var(--ff-text-tertiary)]" />
                <div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    Drop a document here or click to browse
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Invoices, receipts, credit notes — PDF or image up to 10MB
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Extraction Review Panel */}
          {uploadResult && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <FileText className="h-5 w-5 text-teal-500" />
                  <div>
                    <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                      Extraction Results
                    </h2>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      {uploadResult.document.fileName}
                    </p>
                  </div>
                </div>
                <ConfidenceBadge confidence={uploadResult.extracted.confidence} />
              </div>

              {/* Warnings */}
              {uploadResult.extracted.warnings.length > 0 && (
                <div className="px-6 py-3 bg-amber-500/5 border-b border-[var(--ff-border-light)]">
                  {uploadResult.extracted.warnings.map((w, i) => (
                    <div key={i} className="flex items-start gap-2 text-xs text-amber-400">
