/**
 * PRD-060: FibreFlow Accounting Module
 * Bank PDF Statement Parser
 *
 * Extracts transactions from bank PDF statements using pdf-parse.
 * Primary target: ABSA PDF statements.
 *
 * ABSA PDF transaction line format:
 *   15 Jan 2026  POS Purchase Woolworths  -1,234.56  45,678.90
 */

import { log } from '@/lib/logger';
import type { BankCsvParseResult, ParsedBankTransaction } from '../types/bank.types';

// pdf-parse uses export= (CommonJS), so we use require() at runtime.
// Type definition for the parsed result.
interface PdfParseResult {
  text: string;
  numpages: number;
}
type PdfParseFunction = (buffer: Buffer) => Promise<PdfParseResult>;

// Month name lookup for ABSA PDF date parsing ("15 Jan 2026")
const MONTH_MAP: Record<string, string> = {
  jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06',
  jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12',
};

/**
 * Parse a currency string that may contain commas, spaces, and a leading minus.
 * Examples: "-1,234.56", "45 678.90", "1234.56"
 */
function parsePdfAmount(raw: string): number | null {
  const cleaned = raw.replace(/\s/g, '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

/**
 * Parse ABSA-style date string "15 Jan 2026" → "2026-01-15".
 */
function parseAbsaDate(day: string, mon: string, year: string): string | null {
  const monthNum = MONTH_MAP[mon.toLowerCase()];
  if (!monthNum) return null;
  const d = parseInt(day, 10);
  const y = parseInt(year, 10);
  if (isNaN(d) || isNaN(y) || d < 1 || d > 31 || y < 2000 || y > 2099) return null;
  return `${y}-${monthNum}-${String(d).padStart(2, '0')}`;
}

/**
 * Parse ABSA PDF transaction lines from extracted text.
 *
 * ABSA PDF lines follow this pattern:
 *   <day> <Mon> <year>  <description text>  <signed-amount>  <balance>
 *
 * The regex captures:
 *   - date: "15 Jan 2026"
 *   - description: arbitrary text (greedy, trimmed)
 *   - amount: "-1,234.56" or "1,234.56"
 *   - balance (optional): second numeric at end of line
 */
function parseAbsaTextLines(text: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'absa',
  };

  // Match lines that start with a date pattern: "15 Jan 2026"
  // Then description, then one or two signed/unsigned numeric amounts
  const linePattern =
    /^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})\s+(.+?)\s+([-]?\d[\d,\s]*\.\d{2})\s+([-]?\d[\d,\s]*\.\d{2})?$/im;

  const lines = text.split('\n');
  let lineNum = 0;

  for (const rawLine of lines) {
    lineNum++;
    const line = rawLine.trim();
    if (!line) continue;

    const match = line.match(linePattern);
    if (!match) continue;

    const [, day, mon, year, desc, amountRaw, balanceRaw] = match;

    const transactionDate = parseAbsaDate(day!, mon!, year!);
    if (!transactionDate) {
      result.errors.push({ row: lineNum, error: `Invalid date: ${day} ${mon} ${year}` });
      continue;
    }

    const amount = parsePdfAmount(amountRaw!);
    if (amount === null) {
      result.errors.push({ row: lineNum, error: `Invalid amount: ${amountRaw}` });
      continue;
    }

    const tx: ParsedBankTransaction = {
      transactionDate,
      amount,
      description: desc!.trim(),
      balance: balanceRaw ? parsePdfAmount(balanceRaw) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

/**
 * Detect the bank from raw PDF text content.
 * Returns the detected format string or 'unknown'.
 */
function detectPdfBankFormat(text: string): string {
  const sample = text.substring(0, 2000).toLowerCase();

  if (sample.includes('absa') || sample.includes('amalgamated banks')) return 'absa';
  if (sample.includes('first national bank') || sample.includes('fnb')) return 'fnb';
  if (sample.includes('standard bank')) return 'standard_bank';
  if (sample.includes('nedbank')) return 'nedbank';

  return 'unknown';
}

/**
 * Parse a bank statement PDF and extract transactions.
 *
 * Accepts a Buffer of PDF bytes. Uses pdf-parse to extract text, then
 * applies bank-specific regex patterns to identify transaction lines.
 *
 * @param pdfBuffer - Raw PDF file bytes
 * @param bankFormat - Optional hint for which bank format to use
 * @returns Parsed transactions and any row-level errors
 */
export async function parseBankPdf(
  pdfBuffer: Buffer,
  bankFormat?: string,
): Promise<BankCsvParseResult> {
  let pdfParse: PdfParseFunction;

  try {
    // Dynamic require: pdf-parse uses CommonJS export= and cannot be ESM-imported.
    pdfParse = require('pdf-parse') as PdfParseFunction; // eslint-disable-line @typescript-eslint/no-var-requires
  } catch {
    log.error('pdf-parse module not available', {}, 'accounting-pdf');
    return {
      transactions: [],
      errors: [{ row: 0, error: 'PDF parsing library not available. Please upload a CSV file instead.' }],
      bankFormat: bankFormat || 'unknown',
    };
  }

  let parsed: { text: string; numpages: number };
  try {
    parsed = await pdfParse(pdfBuffer);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to read PDF';
    log.error('Failed to parse PDF buffer', { error: err }, 'accounting-pdf');
    return {
      transactions: [],
      errors: [{ row: 0, error: `PDF read error: ${message}` }],
      bankFormat: bankFormat || 'unknown',
    };
  }

  const text = parsed.text;
  if (!text || text.trim().length === 0) {
    return {
      transactions: [],
      errors: [{ row: 0, error: 'No text content found in PDF. The file may be image-based (scanned). Please use a CSV export instead.' }],
      bankFormat: bankFormat || 'unknown',
    };
  }

  const detectedFormat = bankFormat && bankFormat !== 'unknown'
    ? bankFormat
    : detectPdfBankFormat(text);

  log.info('Parsing bank PDF', {
    pages: parsed.numpages,
    textLength: text.length,
    format: detectedFormat,
  }, 'accounting-pdf');

  // Route to the appropriate parser based on detected format
  if (detectedFormat === 'absa') {
    return parseAbsaTextLines(text);
  }

  // Fallback: attempt generic ABSA-style date-amount pattern for unknown formats
  // This covers cases where the bank couldn't be detected but the format is similar
  const fallback = parseAbsaTextLines(text);
  if (fallback.transactions.length > 0) {
    log.info('PDF parsed using ABSA fallback pattern', {
      count: fallback.transactions.length,
    }, 'accounting-pdf');
    return { ...fallback, bankFormat: detectedFormat };
  }

  return {
    transactions: [],
    errors: [{
      row: 0,
      error: `Could not parse transactions from ${detectedFormat === 'unknown' ? 'unknown bank' : detectedFormat} PDF. ` +
        'Please download the statement as a CSV and import that instead.',
    }],
    bankFormat: detectedFormat,
  };
}

/**
 * OCR Service — Document data extraction with VLM + regex fallback
 *
 * Primary:  Qwen3 VLM on vLLM (handles images AND text-based PDFs)
 * Fallback: Pattern-based regex extraction for PDFs with text layers
 *
 * Optimised for South African invoices and receipts.
 */

import { log } from '@/lib/logger';
import type { ExtractedDocument, ExtractedLineItem } from '@/modules/accounting/types/documentCapture.types';
import { extractWithVlm, extractPdfWithVlm, isVlmAvailable } from './vlmService';

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract structured data from a PDF buffer.
 * Tries VLM first (if configured), then falls back to regex-based extraction.
 */
export async function extractFromPdf(buffer: Buffer): Promise<ExtractedDocument> {
  let rawText = '';
  const warnings: string[] = [];

  // Always attempt text extraction — used by VLM as context and as regex fallback
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const pdfParse = require('pdf-parse');
    const data = await pdfParse(buffer);
    rawText = data.text || '';
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('PDF text extraction failed', { error: msg }, 'ocr-service');
    warnings.push(`PDF parsing failed: ${msg}`);
  }

  // --- VLM path ---
  if (isVlmAvailable()) {
    try {
      const vlmResult = await extractPdfWithVlm(buffer, rawText);
      if (vlmResult) {
        vlmResult.warnings.push(...warnings);
        return vlmResult;
      }
      warnings.push('VLM extraction returned no result — falling back to regex.');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log.warn('VLM extraction failed, falling back to regex', { error: msg }, 'ocr-service');
      warnings.push(`VLM extraction failed: ${msg}`);
    }
  }

  // --- Regex fallback ---
  if (!rawText.trim()) {
    warnings.push('No text found in PDF — the document may be image-based. Manual entry recommended.');
    return emptyResult(rawText, warnings);
  }

  return extractFromText(rawText, warnings);
}

/**
 * Extract structured data from an image buffer (JPEG/PNG).
 * Requires VLM — no regex fallback for images.
 */
export async function extractFromImage(
  imageBuffer: Buffer,
  mimeType: string,
): Promise<ExtractedDocument> {
  const warnings: string[] = [];

  if (!isVlmAvailable()) {
    warnings.push('VLM not configured — cannot extract from images. Set VLLM_BASE_URL in environment.');
    return emptyResult('', warnings);
  }

  try {
    const base64 = imageBuffer.toString('base64');
    const vlmResult = await extractWithVlm(base64, mimeType);
    if (vlmResult) return vlmResult;
    warnings.push('VLM returned no result for image.');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('VLM image extraction failed', { error: msg }, 'ocr-service');
    warnings.push(`VLM image extraction failed: ${msg}`);
  }

  return emptyResult('', warnings);
}

/**
 * Extract structured data from raw text (e.g. pasted or OCR output).
 * Uses VLM if available (sends text as prompt), otherwise regex.
 */
export async function extractFromText(
  rawText: string,
  existingWarnings: string[] = [],
): Promise<ExtractedDocument> {
  const warnings = [...existingWarnings];
  const lines = rawText.split(/\n/).map(l => l.trim()).filter(Boolean);

  if (lines.length === 0) {
    warnings.push('Empty text provided');
    return emptyResult(rawText, warnings);
  }

  // --- Regex extraction ---
  const documentType = detectDocumentType(rawText);
  const vendorName = extractVendorName(lines);
  const vendorVatNumber = extractVatRegistration(rawText);
  const date = extractDate(rawText);
  const referenceNumber = extractReferenceNumber(rawText);
  const amounts = extractAmounts(rawText);
  const lineItems = extractLineItems(lines);

  const confidence = computeConfidence({
    vendorName,
    date,
    referenceNumber,
    totalAmount: amounts.totalAmount,
    vatAmount: amounts.vatAmount,
    lineItems,
  });

  if (confidence < 0.3) {
    warnings.push('Low extraction confidence — please review all fields carefully.');
  }

  return {
    documentType,
    vendorName,
    vendorVatNumber,
    vendorAddress: null,
    vendorBankDetails: null,
    customerName: null,
    customerVatNumber: null,
    date,
    dueDate: null,
    paymentTerms: null,
    referenceNumber,
    purchaseOrderRef: null,
    currency: 'ZAR',
    subtotal: amounts.subtotal,
    vatAmount: amounts.vatAmount,
    vatRate: amounts.vatAmount && amounts.subtotal ? Math.round((amounts.vatAmount / amounts.subtotal) * 100) : null,
    totalAmount: amounts.totalAmount,
    lineItems: lineItems.map(li => ({
      ...li,
      vatAmount: null,
      vatClassification: null,
      glAccountSuggestion: null,
    })),
    rawText,
    confidence,
    warnings,
    extractionMethod: 'regex',
  };
}

// ---------------------------------------------------------------------------
// Document type detection
// ---------------------------------------------------------------------------

function detectDocumentType(text: string): ExtractedDocument['documentType'] {
  const upper = text.toUpperCase();

  if (/CREDIT\s*NOTE/i.test(upper)) return 'credit_note';
  if (/PURCHASE\s*ORDER/i.test(upper)) return 'purchase_order';
  if (/DELIVERY\s*NOTE/i.test(upper)) return 'delivery_note';
  if (/TAX\s*INVOICE/i.test(upper)) return 'invoice';
  if (/INVOICE/i.test(upper)) return 'invoice';
  if (/STATEMENT/i.test(upper)) return 'statement';
  if (/RECEIPT/i.test(upper) || /PROOF\s*OF\s*PAYMENT/i.test(upper)) return 'receipt';

  return 'unknown';
}

// ---------------------------------------------------------------------------
// Vendor name extraction
// ---------------------------------------------------------------------------

function extractVendorName(lines: string[]): string | null {
  const skipPatterns = [
    /^(TAX\s*)?INVOICE$/i,
    /^CREDIT\s*NOTE$/i,
    /^STATEMENT$/i,
    /^RECEIPT$/i,
    /^(page|date|ref|invoice|tel|fax|email|vat|tax|reg)/i,
    /^\d{1,2}[/-]\d{1,2}[/-]\d{2,4}$/,
    /^P\.?O\.?\s*BOX/i,
    /^\d+\s+(street|road|avenue|drive|lane|crescent)/i,
  ];

  for (let i = 0; i < Math.min(lines.length, 8); i++) {
    const line = lines[i];
    if (!line || line.length < 3 || line.length > 80) continue;
    if (skipPatterns.some(p => p.test(line))) continue;
    if (/^\d+$/.test(line)) continue;
    if (/\b\d{4}\b.*\b(South Africa|SA|RSA)\b/i.test(line)) continue;

    return line;
  }

  const fromMatch = lines.join('\n').match(/(?:From|Supplier|Vendor|Company)\s*[:-]\s*(.+)/i);
  if (fromMatch && fromMatch[1]) return fromMatch[1].trim();

  return null;
}

// ---------------------------------------------------------------------------
// VAT registration number
// ---------------------------------------------------------------------------

function extractVatRegistration(text: string): string | null {
  const patterns = [
    /VAT\s*(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number|#)\s*[:-]?\s*(\d{10})/i,
    /VAT\s*[:-]?\s*(\d{10})/i,
    /(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number)\s*[:-]?\s*(\d{10})/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1];
  }

  return null;
}

// ---------------------------------------------------------------------------
// Date extraction
// ---------------------------------------------------------------------------

function extractDate(text: string): string | null {
  const months: Record<string, string> = {
    jan: '01', january: '01',
    feb: '02', february: '02',
    mar: '03', march: '03',
    apr: '04', april: '04',
    may: '05',
    jun: '06', june: '06',
    jul: '07', july: '07',
    aug: '08', august: '08',
    sep: '09', september: '09',
    oct: '10', october: '10',
    nov: '11', november: '11',
    dec: '12', december: '12',
  };

  const labelledPatterns = [
    /(?:Invoice|Document|Tax Invoice|Statement)\s*Date\s*[:-]?\s*(.+)/i,
    /Date\s*[:-]\s*(.+)/i,
    /Dated?\s*[:-]\s*(.+)/i,
  ];

  for (const pattern of labelledPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      const parsed = parseDateString(match[1].trim(), months);
      if (parsed) return parsed;
    }
  }

  const slashDate = text.match(/\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b/);
  if (slashDate) {
    const [, d, m, y] = slashDate;
    const day = d!.padStart(2, '0');
    const month = m!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${y}-${month}-${day}`;
    }
  }

  const isoDate = text.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (isoDate) {
    return `${isoDate[1]}-${isoDate[2]}-${isoDate[3]}`;
  }

  const longDate = text.match(/\b(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})\b/i);
  if (longDate) {
    const day = longDate[1]!.padStart(2, '0');
    const monthNum = months[longDate[2]!.toLowerCase()];
    if (monthNum) return `${longDate[3]}-${monthNum}-${day}`;
  }

  return null;
}

function parseDateString(str: string, months: Record<string, string>): string | null {
  const slashMatch = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (slashMatch) {
    const day = slashMatch[1]!.padStart(2, '0');
    const month = slashMatch[2]!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${slashMatch[3]}-${month}-${day}`;
    }
  }

  const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;

  const longMatch = str.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})/);
  if (longMatch) {
    const monthKey = longMatch[2]!.toLowerCase();
    const monthNum = months[monthKey];
    if (monthNum) {
      const day = longMatch[1]!.padStart(2, '0');
      return `${longMatch[3]}-${monthNum}-${day}`;
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Reference / invoice number extraction
// ---------------------------------------------------------------------------

function extractReferenceNumber(text: string): string | null {
  const patterns = [
    /Invoice\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Ref(?:erence)?\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /(?:INV|REF|CN|CR)\s*[-#]?\s*(\d{3,})/i,
    /Document\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Order\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Receipt\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1] && match[1].length >= 3) {
      return match[1].trim();
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Amount extraction (Total, VAT, Subtotal)
// ---------------------------------------------------------------------------

interface ExtractedAmounts {
  subtotal: number | null;
  vatAmount: number | null;
  totalAmount: number | null;
}

function extractAmounts(text: string): ExtractedAmounts {
  const result: ExtractedAmounts = {
    subtotal: null,
    vatAmount: null,
    totalAmount: null,
  };

  const totalPatterns = [
    /(?:Grand\s*)?Total\s*(?:Due|Amount|Payable)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /(?:Amount|Balance)\s*(?:Due|Owing|Payable)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Incl(?:uding)?\.?\s*(?:VAT|Tax))?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of totalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.totalAmount = parseAmount(match[1]);
      break;
    }
  }

  const vatPatterns = [
    /VAT\s*(?:@\s*\d+%?)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Tax\s*(?:Amount)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /VAT\s*\(\s*15\s*%\s*\)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of vatPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.vatAmount = parseAmount(match[1]);
      break;
    }
  }

  const subtotalPatterns = [
    /Sub\s*[-\s]?Total\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Excl(?:uding)?\.?\s*(?:VAT|Tax))\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Nett?\s*(?:Amount|Total)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of subtotalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.subtotal = parseAmount(match[1]);
      break;
    }
  }

  if (result.totalAmount !== null && result.vatAmount !== null && result.subtotal === null) {
    result.subtotal = Math.round((result.totalAmount - result.vatAmount) * 100) / 100;
  }

  if (result.subtotal !== null && result.vatAmount !== null && result.totalAmount === null) {
    result.totalAmount = Math.round((result.subtotal + result.vatAmount) * 100) / 100;
  }

  return result;
}

function parseAmount(str: string): number {
  const cleaned = str.replace(/[\s,]/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : Math.round(num * 100) / 100;
}

// ---------------------------------------------------------------------------
// Line item extraction
// ---------------------------------------------------------------------------

interface RegexLineItem {
  description: string;
  quantity: number | null;
  unitPrice: number | null;
  total: number | null;
}

function extractLineItems(lines: string[]): RegexLineItem[] {
  const items: RegexLineItem[] = [];

  const lineItemPattern = /^(.+?)\s+(\d+(?:\.\d+)?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;
  const simpleLinePattern = /^(.{3,}?)\s{2,}(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;

  let itemsStarted = false;
  const headerPattern = /(?:description|item|product|service)\s.*(?:qty|quantity|amount|price|total)/i;

  for (const line of lines) {
    if (headerPattern.test(line)) {
      itemsStarted = true;
      continue;
    }

    if (!itemsStarted && items.length === 0) {
      const match = lineItemPattern.exec(line);
      if (match) itemsStarted = true;
    }

    if (!itemsStarted) continue;

    if (/^(Sub\s*[-\s]?Total|Total|VAT|Tax|Amount\s*Due|Balance\s*Due|Grand\s*Total)/i.test(line)) {
      break;
    }

    const fullMatch = lineItemPattern.exec(line);
    if (fullMatch) {
      items.push({
        description: fullMatch[1]!.trim(),
        quantity: parseFloat(fullMatch[2]!),
        unitPrice: parseAmount(fullMatch[3]!),
        total: parseAmount(fullMatch[4]!),
      });
      continue;
    }

    const simpleMatch = simpleLinePattern.exec(line);
    if (simpleMatch) {
      items.push({
        description: simpleMatch[1]!.trim(),
        quantity: null,
        unitPrice: null,
        total: parseAmount(simpleMatch[2]!),
      });
    }
  }

  return items;
}

// ---------------------------------------------------------------------------
// Confidence scoring
// ---------------------------------------------------------------------------

function computeConfidence(fields: {
  vendorName: string | null;
  date: string | null;
  referenceNumber: string | null;
  totalAmount: number | null;
  vatAmount: number | null;
  lineItems: RegexLineItem[];
}): number {
  let score = 0;
  const weights = {
    vendorName: 0.2,
    date: 0.2,
    referenceNumber: 0.15,
    totalAmount: 0.25,
    vatAmount: 0.1,
    lineItems: 0.1,
  };

  if (fields.vendorName) score += weights.vendorName;
  if (fields.date) score += weights.date;
  if (fields.referenceNumber) score += weights.referenceNumber;
  if (fields.totalAmount !== null && fields.totalAmount > 0) score += weights.totalAmount;
  if (fields.vatAmount !== null && fields.vatAmount > 0) score += weights.vatAmount;
  if (fields.lineItems.length > 0) score += weights.lineItems;

  return Math.round(score * 100) / 100;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function emptyResult(rawText: string, warnings: string[]): ExtractedDocument {
  return {
    documentType: 'unknown',
    vendorName: null,
    vendorVatNumber: null,
    vendorAddress: null,
    vendorBankDetails: null,
    customerName: null,
    customerVatNumber: null,
    date: null,
    dueDate: null,
    paymentTerms: null,
    referenceNumber: null,
    purchaseOrderRef: null,
    currency: null,
    subtotal: null,
    vatAmount: null,
    vatRate: null,
    totalAmount: null,
    lineItems: [],
    rawText,
    confidence: 0,
    warnings,
    extractionMethod: 'regex',
  };
}

/**
 * Approval Workflow Service
 * Configurable approval rules for financial documents.
 * Checks if documents require approval before processing.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type DocumentType = 'customer_invoice' | 'supplier_invoice' | 'payment' | 'journal_entry' | 'credit_note';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'cancelled';

export interface ApprovalRule {
  id: string;
  name: string;
  documentType: DocumentType;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
  priority: number;
  createdAt: string;
}

export interface ApprovalRequest {
  id: string;
  ruleId: string;
  ruleName?: string;
  documentType: DocumentType;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: ApprovalStatus;
  requestedBy: string;
  requestedByName?: string;
  requestedAt: string;
  decidedBy: string | null;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

export interface ApprovalCheckResult {
  requiresApproval: boolean;
  matchedRule: ApprovalRule | null;
  existingRequest: ApprovalRequest | null;
}

// ── Rule CRUD ────────────────────────────────────────────────────────────────

export async function listRules(_companyId?: string): Promise<ApprovalRule[]> {
  const rows = (await sql`
    SELECT * FROM approval_rules ORDER BY priority ASC, name ASC
  `) as Row[];
  return rows.map(mapRule);
}

export async function createRule(_companyId: string, input: {
  name: string;
  documentType: DocumentType;
  conditionField?: string;
  conditionOperator?: string;
  conditionValue?: number;
  approverRole?: string;
}): Promise<ApprovalRule> {
  const rows = (await sql`
    INSERT INTO approval_rules (name, document_type, condition_field, condition_operator, condition_value, approver_role)
    VALUES (
      ${input.name}, ${input.documentType},
      ${input.conditionField || 'total'}, ${input.conditionOperator || 'greater_than'},
      ${input.conditionValue || 0}, ${input.approverRole || 'admin'}
    ) RETURNING *
  `) as Row[];
  log.info('Created approval rule', { id: rows[0].id, name: input.name }, 'accounting');
  return mapRule(rows[0]);
}

export async function updateRule(_companyId: string, id: string, input: Partial<{
  name: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}>): Promise<ApprovalRule> {
  const rows = (await sql`
    UPDATE approval_rules SET
      name = COALESCE(${input.name ?? null}, name),
      condition_field = COALESCE(${input.conditionField ?? null}, condition_field),
      condition_operator = COALESCE(${input.conditionOperator ?? null}, condition_operator),
      condition_value = COALESCE(${input.conditionValue ?? null}, condition_value),
      approver_role = COALESCE(${input.approverRole ?? null}, approver_role),
      is_active = COALESCE(${input.isActive ?? null}, is_active),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRule(rows[0]);
}

export async function deleteRule(_companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM approval_rules WHERE id = ${id}::UUID`;
}

// ── Approval Check ───────────────────────────────────────────────────────────

/** Check if a document requires approval based on active rules */
export async function checkApproval(
  _companyId: string,
  documentType: DocumentType,
  documentId: string,
  amount: number
): Promise<ApprovalCheckResult> {
  // Check for existing pending request
  const existing = (await sql`
    SELECT ar.*, rl.name AS rule_name
    FROM approval_requests ar
    LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
    WHERE ar.document_type = ${documentType}
      AND ar.document_id = ${documentId}::UUID
      AND ar.status = 'pending'
    LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    return {
      requiresApproval: true,
      matchedRule: null,
      existingRequest: mapRequest(existing[0]),
    };
  }

  // Find matching active rules
  const rules = (await sql`
    SELECT * FROM approval_rules
    WHERE document_type = ${documentType}
      AND is_active = true
    ORDER BY priority ASC
  `) as Row[];

  for (const rule of rules) {
    const r = mapRule(rule);
    let matches = false;

    switch (r.conditionOperator) {
      case 'any':
        matches = true;
        break;
      case 'greater_than':
        matches = amount > r.conditionValue;
        break;
      case 'greater_equal':
        matches = amount >= r.conditionValue;
        break;
    }

    if (matches) {
      return {
        requiresApproval: true,
        matchedRule: r,
        existingRequest: null,
      };
    }
  }

  return { requiresApproval: false, matchedRule: null, existingRequest: null };
}

// ── Approval Requests ────────────────────────────────────────────────────────

/** Create an approval request for a document */
export async function requestApproval(_companyId: string, input: {
  ruleId: string;
  documentType: DocumentType;
  documentId: string;
  documentReference?: string;
  amount?: number;
  requestedBy: string;
}): Promise<ApprovalRequest> {
  const rows = (await sql`
    INSERT INTO approval_requests (rule_id, document_type, document_id, document_reference, amount, requested_by)
    VALUES (
      ${input.ruleId}::UUID, ${input.documentType}, ${input.documentId}::UUID,
      ${input.documentReference || null}, ${input.amount || null}, ${input.requestedBy}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Approval requested', {
    id: rows[0].id,
    documentType: input.documentType,
    documentId: input.documentId,
  }, 'accounting');
  return mapRequest(rows[0]);
}

/** List approval requests with optional status filter */
export async function listRequests(_companyId: string, status?: ApprovalStatus): Promise<ApprovalRequest[]> {
  const rows = status
    ? (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by
        LEFT JOIN users u2 ON u2.id = ar.decided_by
        WHERE ar.status = ${status}
        ORDER BY ar.created_at DESC
      `) as Row[]
    : (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by
        LEFT JOIN users u2 ON u2.id = ar.decided_by
        ORDER BY ar.created_at DESC
      `) as Row[];
  return rows.map(mapRequest);
}

/** Approve or reject a request */
export async function decideRequest(_companyId: string, 
  requestId: string,
  decision: 'approved' | 'rejected',
  decidedBy: string,
  notes?: string
): Promise<ApprovalRequest> {
  const rows = (await sql`
    UPDATE approval_requests SET
      status = ${decision},
      decided_by = ${decidedBy}::UUID,
      decided_at = NOW(),
      decision_notes = ${notes || null}
    WHERE id = ${requestId}::UUID AND status = 'pending'
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Request ${requestId} not found or already decided`);
  log.info('Approval decided', { id: requestId, decision }, 'accounting');
  return mapRequest(rows[0]);
}

/** Get pending approval count for dashboard badge */
export async function getPendingCount(_companyId?: string): Promise<number> {
  const rows = (await sql`
    SELECT COUNT(*) AS count FROM approval_requests WHERE status = 'pending'
  `) as Row[];
  return Number(rows[0]?.count ?? 0);
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapRule(r: Row): ApprovalRule {
  return {
    id: r.id,
    name: r.name,
    documentType: r.document_type,
    conditionField: r.condition_field,
    conditionOperator: r.condition_operator,
    conditionValue: Number(r.condition_value),
    approverRole: r.approver_role,
    isActive: r.is_active,
    priority: r.priority,
    createdAt: r.created_at,
  };
}

function mapRequest(r: Row): ApprovalRequest {
  return {
    id: r.id,
    ruleId: r.rule_id,
    ruleName: r.rule_name || undefined,
    documentType: r.document_type,
    documentId: r.document_id,
    documentReference: r.document_reference,
    amount: r.amount ? Number(r.amount) : null,
    status: r.status,
    requestedBy: r.requested_by,
    requestedByName: r.requested_by_name || undefined,
    requestedAt: r.requested_at,
    decidedBy: r.decided_by,
    decidedByName: r.decided_by_name || undefined,
    decidedAt: r.decided_at,
    decisionNotes: r.decision_notes,
  };
}

/**
 * SARS eFiling Integration Service
 * Generates VAT201 and EMP201 form data from accounting records.
 * Manages tax periods and compliance calendar for South African tax obligations.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const SA_VAT_RATE = 0.15;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface VAT201Data {
  periodStart: string;
  periodEnd: string;
  field1_standardRatedSupplies: number;
  field2_zeroRatedSupplies: number;
  field3_exemptSupplies: number;
  field4_totalImports: number;
  field5_outputVAT: number;
  field6_capitalGoods: number;
  field7_otherGoods: number;
  field8_services: number;
  field9_imports: number;
  field10_totalInputVAT: number;
  field11_vatPayableOrRefundable: number;
  outputInvoices: VAT201Invoice[];
  inputInvoices: VAT201Invoice[];
}

export interface VAT201Invoice {
  id: string;
  invoiceNumber: string;
  counterpartyName: string;
  invoiceDate: string;
  totalExclVat: number;
  vatAmount: number;
  vatType: string;
}

export interface EMP201Data {
  periodStart: string;
  periodEnd: string;
  totalPAYE: number;
  totalUIF_employee: number;
  totalUIF_employer: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
  totalTaxableRemuneration: number;
  totalDeductions: number;
  payrollRuns: EMP201PayrollRun[];
}

export interface EMP201PayrollRun {
  id: string;
  runDate: string;
  employeeCount: number;
  grossPay: number;
  paye: number;
  uif: number;
  sdl: number;
}

export interface TaxPeriod {
  type: 'VAT' | 'PAYE';
  periodStart: string;
  periodEnd: string;
  dueDate: string;
  label: string;
}

export interface ComplianceEvent {
  id?: string;
  eventType: string;
  dueDate: string;
  description: string;
