/**
 * Smart Categorization Service
 * AI-powered bank transaction categorization using rules, patterns, and historical learning
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW';

export interface CategorizationInput {
  description: string;
  amount: number;
  reference?: string;
}

export interface CategorizationResult {
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  category?: string;
  vatCode?: string;
  confidence: number;
  confidenceLevel: ConfidenceLevel;
  matchSource: 'rule' | 'pattern' | 'historical';
  matchDetail?: string;
}

export interface BulkCategorizationResult {
  categorized: number;
  skipped: number;
  results: Array<{
    transactionId: string;
    result: CategorizationResult | null;
  }>;
}

// ── Confidence helpers ───────────────────────────────────────────────────────

function toConfidenceLevel(score: number): ConfidenceLevel {
  if (score >= 0.85) return 'HIGH';
  if (score >= 0.60) return 'MEDIUM';
  return 'LOW';
}

// ── Core: Categorize a single transaction ────────────────────────────────────

export async function categorizeBankTransaction(_companyId: string, 
  tx: CategorizationInput
): Promise<CategorizationResult | null> {
  const description = (tx.description || '').toUpperCase().trim();
  const reference = (tx.reference || '').toUpperCase().trim();

  if (!description && !reference) return null;

  // 1. Check existing bank_categorisation_rules (highest priority)
  const ruleMatch = await matchAgainstRules(description, reference);
  if (ruleMatch) return ruleMatch;

  // 2. Check categorization_patterns table (system + learned patterns)
  const patternMatch = await matchAgainstPatterns(description, reference);
  if (patternMatch) return patternMatch;

  // 3. Learn from historical allocations (similar past transactions)
  const historicalMatch = await matchFromHistory(description, tx.amount);
  if (historicalMatch) return historicalMatch;

  return null;
}

// ── Strategy 1: Match against bank_categorisation_rules ──────────────────────

async function matchAgainstRules(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const rules = (await sql`
      SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
      WHERE r.is_active = true
      ORDER BY r.priority ASC
    `) as Row[];

    for (const rule of rules) {
      const pattern = String(rule.match_pattern).toUpperCase();
      const matchType = String(rule.match_type);
      const matchField = String(rule.match_field);

      const targets: string[] = [];
      if (matchField === 'description' || matchField === 'both') targets.push(description);
      if (matchField === 'reference' || matchField === 'both') targets.push(reference);

      const matched = targets.some(target => {
        switch (matchType) {
          case 'contains': return target.includes(pattern);
          case 'starts_with': return target.startsWith(pattern);
          case 'ends_with': return target.endsWith(pattern);
          case 'exact': return target === pattern;
          default: return target.includes(pattern);
        }
      });

      if (matched) {
        return {
          glAccountId: rule.gl_account_id ? String(rule.gl_account_id) : undefined,
          glAccountCode: rule.gl_account_code ? String(rule.gl_account_code) : undefined,
          glAccountName: rule.gl_account_name ? String(rule.gl_account_name) : undefined,
          category: String(rule.rule_name),
          vatCode: String(rule.vat_code || 'none'),
          confidence: 0.95,
          confidenceLevel: 'HIGH',
          matchSource: 'rule',
          matchDetail: `Rule: ${rule.rule_name} (${matchType} "${rule.match_pattern}")`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: rule matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 2: Match against categorization_patterns ────────────────────────

async function matchAgainstPatterns(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const patterns = (await sql`
      SELECT cp.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM categorization_patterns cp
      LEFT JOIN gl_accounts ga ON ga.id = cp.gl_account_id
      ORDER BY cp.confidence DESC, cp.usage_count DESC
    `) as Row[];

    const combined = `${description} ${reference}`;

    for (const p of patterns) {
      const pat = String(p.pattern).toUpperCase();
      const matchType = String(p.match_type);

      let matched = false;
      switch (matchType) {
        case 'contains':
          matched = combined.includes(pat);
          break;
        case 'starts_with':
          matched = description.startsWith(pat) || reference.startsWith(pat);
          break;
        case 'regex':
          try {
            const re = new RegExp(p.pattern, 'i');
            matched = re.test(description) || re.test(reference);
          } catch {
            // WORKING: invalid regex patterns are safely skipped
            matched = false;
          }
          break;
        default:
          matched = combined.includes(pat);
      }

      if (matched) {
        const confidence = Number(p.confidence) || 0.80;

        // Update usage stats (fire-and-forget)
        sql`
          UPDATE categorization_patterns
          SET usage_count = usage_count + 1, last_used_at = NOW()
          WHERE id = ${p.id}::UUID
        `.catch(() => {});

        return {
          glAccountId: p.gl_account_id ? String(p.gl_account_id) : undefined,
          glAccountCode: p.gl_account_code ? String(p.gl_account_code) : undefined,
          glAccountName: p.gl_account_name ? String(p.gl_account_name) : undefined,
          category: p.category ? String(p.category) : undefined,
          vatCode: String(p.vat_code || 'standard'),
          confidence,
          confidenceLevel: toConfidenceLevel(confidence),
          matchSource: 'pattern',
          matchDetail: `Pattern: "${p.pattern}" (${p.source})`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: pattern matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 3: Learn from historical allocations ────────────────────────────

async function matchFromHistory(
  description: string,
  _amount: number
): Promise<CategorizationResult | null> {
  if (!description || description.length < 3) return null;

  try {
    // Extract significant words (3+ chars, skip common banking noise)
    const noiseWords = new Set([
      'THE', 'AND', 'FOR', 'FROM', 'WITH', 'PAYMENT', 'TRANSFER',
      'DEBIT', 'CREDIT', 'ORDER', 'REF', 'POS', 'PURCHASE', 'CARD',
    ]);
    const words = description
      .split(/[\s/\\,.-]+/)
      .filter(w => w.length >= 3 && !noiseWords.has(w) && !/^\d+$/.test(w));

    if (words.length === 0) return null;

    // Build search: look for allocated transactions with similar descriptions
    // Use the first 2-3 significant words for matching
    const searchWords = words.slice(0, 3);
    const likePattern = `%${searchWords.join('%')}%`;

    const historicalRows = (await sql`
      SELECT
        bt.suggested_gl_account_id,
        bt.suggested_category,
        bt.suggested_vat_code,
        bt.allocation_type,
        ga.account_code AS gl_account_code,
        ga.account_name AS gl_account_name,
        COUNT(*) AS match_count
      FROM bank_transactions bt
      LEFT JOIN gl_accounts ga ON ga.id = bt.suggested_gl_account_id
      WHERE bt.status IN ('matched', 'reconciled')
        AND bt.matched_journal_line_id IS NOT NULL
        AND bt.suggested_gl_account_id IS NOT NULL
        AND UPPER(bt.description) ILIKE ${likePattern}
      GROUP BY bt.suggested_gl_account_id, bt.suggested_category,
               bt.suggested_vat_code, bt.allocation_type,
               ga.account_code, ga.account_name
      ORDER BY match_count DESC
      LIMIT 1
    `) as Row[];

    if (historicalRows.length > 0) {
      const row = historicalRows[0];
      const matchCount = Number(row.match_count);
      // Scale confidence based on how many historical matches we found
      const baseConfidence = matchCount >= 5 ? 0.70 : matchCount >= 2 ? 0.55 : 0.40;

      return {
        glAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
        glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
        glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
        category: row.suggested_category ? String(row.suggested_category) : undefined,
        vatCode: String(row.suggested_vat_code || 'none'),
        confidence: baseConfidence,
        confidenceLevel: toConfidenceLevel(baseConfidence),
        matchSource: 'historical',
        matchDetail: `Historical: ${matchCount} similar transaction(s)`,
      };
    }
  } catch (err) {
    log.error('Smart categorization: historical matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Learn from user allocation ───────────────────────────────────────────────

export async function learnFromAllocation(_companyId: string, 
  txId: string,
  glAccountId: string,
  category: string,
  vatCode?: string
): Promise<void> {
  try {
    // Get the transaction description
    const txRows = (await sql`
      SELECT description FROM bank_transactions WHERE id = ${txId}::UUID
    `) as Row[];

    if (txRows.length === 0) return;

    const description = String(txRows[0].description || '').trim();
    if (description.length < 3) return;

    // Extract a clean pattern from the description
    // Remove trailing numbers, dates, and references to get the merchant/payee name
    const pattern = extractLearningPattern(description);
    if (!pattern || pattern.length < 3) return;

    // Check if we already have this pattern
    const existing = (await sql`
      SELECT id, usage_count FROM categorization_patterns
      WHERE UPPER(pattern) = ${pattern.toUpperCase()}
        AND source = 'learned'
      LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      // Update existing pattern — increase confidence with use
      const newCount = Number(existing[0].usage_count) + 1;
      const newConfidence = Math.min(0.95, 0.60 + newCount * 0.05);
      await sql`
        UPDATE categorization_patterns
        SET gl_account_id = ${glAccountId}::UUID,
            category = ${category},
            vat_code = ${vatCode || 'standard'},
            usage_count = ${newCount},
            confidence = ${newConfidence},
            last_used_at = NOW()
        WHERE id = ${existing[0].id}::UUID
      `;
    } else {
      // Create new learned pattern
      await sql`
        INSERT INTO categorization_patterns (pattern, match_type, gl_account_id, category, vat_code, confidence, usage_count, last_used_at, source)
        VALUES (${pattern}, 'contains', ${glAccountId}::UUID, ${category}, ${vatCode || 'standard'}, 0.65, 1, NOW(), 'learned')
      `;
    }

    log.info('Learned categorization pattern', { pattern, category, glAccountId }, 'accounting');
  } catch (err) {
    log.error('Failed to learn from allocation', { txId, error: err }, 'accounting');
    // Non-critical: don't throw — learning failures should not break allocation flow
  }
}

/**
 * Extract a clean pattern from a bank transaction description.
 * Strips trailing reference numbers, dates, card numbers, etc.
 */
function extractLearningPattern(description: string): string {
  let clean = description.toUpperCase();

  // Remove common suffixes: card numbers, dates, reference numbers
  clean = clean.replace(/\b\d{4}\*+\d{4}\b/g, '');      // Card number masks
  clean = clean.replace(/\b\d{2}\/\d{2}\/\d{2,4}\b/g, ''); // Dates
  clean = clean.replace(/\b\d{6,}\b/g, '');               // Long number sequences
  clean = clean.replace(/\bREF\s*:?\s*\S+/gi, '');        // REF: xxx
  clean = clean.replace(/\bPOS\b/g, '');                   // POS prefix
  clean = clean.replace(/\bPURCHASE\b/g, '');              // PURCHASE label

  // Trim and collapse whitespace
  clean = clean.replace(/\s+/g, ' ').trim();

  // Take the first meaningful part (usually merchant name)
  const parts = clean.split(/\s{2,}/);
  return parts[0]?.trim() || clean;
}

// ── Bulk categorize ──────────────────────────────────────────────────────────

export async function bulkCategorize(_companyId: string, 
  transactionIds: string[]
): Promise<BulkCategorizationResult> {
  if (transactionIds.length === 0) {
    return { categorized: 0, skipped: 0, results: [] };
  }

  // Fetch all requested transactions
  const txRows = (await sql`
    SELECT id, description, amount, reference
    FROM bank_transactions
    WHERE id = ANY(${transactionIds}::UUID[])
      AND status IN ('imported', 'allocated')
  `) as Row[];

  let categorized = 0;
  let skipped = 0;
  const results: BulkCategorizationResult['results'] = [];

  for (const tx of txRows) {
    const txId = String(tx.id);
    const input: CategorizationInput = {
      description: String(tx.description || ''),
      amount: Number(tx.amount),
      reference: tx.reference ? String(tx.reference) : undefined,
    };

    const result = await categorizeBankTransaction('', input);

    if (result) {
      // Write suggestion back to the transaction
      await sql`
        UPDATE bank_transactions SET
          suggested_gl_account_id = COALESCE(${result.glAccountId || null}::UUID, suggested_gl_account_id),
          suggested_category = COALESCE(${result.category || null}, suggested_category),
          suggested_vat_code = COALESCE(${result.vatCode || null}, suggested_vat_code),
          suggested_confidence = ${result.confidence}
        WHERE id = ${txId}::UUID
          AND suggested_gl_account_id IS NULL
      `;
      categorized++;
      results.push({ transactionId: txId, result });
    } else {
      skipped++;
      results.push({ transactionId: txId, result: null });
    }
  }

  log.info('Bulk smart categorization complete', { categorized, skipped, total: txRows.length }, 'accounting');

  return { categorized, skipped, results };
}

// ── Categorize all uncategorized transactions for a bank account ──────────────

export async function smartCategorizeForAccount(_companyId: string, 
  bankAccountId: string
): Promise<BulkCategorizationResult> {
  // Get all uncategorized transactions for this bank account
  const txRows = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND status IN ('imported', 'allocated')
      AND suggested_gl_account_id IS NULL
      AND suggested_category IS NULL
    ORDER BY transaction_date DESC
    LIMIT 500
  `) as Row[];

  const ids = txRows.map((r: Row) => String(r.id));
  return bulkCategorize('', ids);
}

/**
 * PRD-060: FibreFlow Accounting Module
 * 3-Way Match Validation (PO ↔ GRN ↔ Invoice)
 *
 * Validates that a supplier invoice aligns with the
 * purchase order and goods receipt note.
 */

import type { ThreeWayMatchInput, ThreeWayMatchResult, InvoiceMatchStatus } from '../types/ap.types';

const DEFAULT_TOLERANCE_PERCENT = 2;

/**
 * Validate 3-way match between PO, GRN, and supplier invoice.
 *
 * Checks:
 * 1. Invoice quantity matches PO quantity
 * 2. Invoice unit price matches PO unit price (within tolerance)
 * 3. GRN received quantity matches invoice quantity
 */
export function validateThreeWayMatch(input: ThreeWayMatchInput): ThreeWayMatchResult {
  const tolerance = input.tolerancePercent ?? DEFAULT_TOLERANCE_PERCENT;
  const mismatches: string[] = [];

  // Check quantity match: Invoice vs PO
  const quantityMatch = input.invoiceQuantity === input.poQuantity;
  if (!quantityMatch) {
    mismatches.push(
      `Invoice quantity (${input.invoiceQuantity}) does not match PO quantity (${input.poQuantity})`
    );
  }

  // Check price match: Invoice vs PO (within tolerance)
  const priceDiffPercent =
    input.poUnitPrice > 0
      ? Math.abs(input.invoiceUnitPrice - input.poUnitPrice) / input.poUnitPrice * 100
      : input.invoiceUnitPrice > 0 ? 100 : 0;

  const priceMatch = priceDiffPercent <= tolerance;
  if (!priceMatch) {
    mismatches.push(
      `Invoice unit price (${input.invoiceUnitPrice}) differs from PO price (${input.poUnitPrice}) by ${priceDiffPercent.toFixed(1)}%, exceeds ${tolerance}% tolerance`
    );
  }

  // Check GRN match: GRN received vs Invoice quantity
  const grnMatch = input.grnQuantityReceived === input.invoiceQuantity;
  if (!grnMatch) {
    mismatches.push(
      `GRN received quantity (${input.grnQuantityReceived}) does not match invoice quantity (${input.invoiceQuantity})`
    );
  }

  // Determine overall status
  let status: InvoiceMatchStatus;
  if (quantityMatch && priceMatch && grnMatch) {
    status = 'fully_matched';
  } else if (quantityMatch && priceMatch && !grnMatch) {
    status = 'po_matched';
  } else if (grnMatch && (!quantityMatch || !priceMatch)) {
    status = 'grn_matched';
  } else {
    status = 'unmatched';
  }

  return {
    status,
    quantityMatch,
    priceMatch,
    grnMatch,
    mismatches,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank Transaction Auto-Match Algorithm
 *
 * Four-tier matching strategy:
 *   Tier 0: Rule-based match via bank_categorisation_rules (confidence 1.0)
 *   Tier 1: Exact reference match (confidence 1.0)
 *   Tier 2: Amount + date within 3 days (confidence 0.9)
 *   Tier 3: Amount only match (confidence 0.7)
 */

import type { AutoMatchCandidate } from '../types/bank.types';

interface BankTxForMatch {
  id: string;
  amount: number;
  transactionDate: string;
  reference?: string;
  description?: string;
}

interface JournalLineForMatch {
  id: string;
  debit: number;
  credit: number;
  description?: string;
  entryDate: string;
  entryNumber?: string;
  sourceDocumentId?: string;
}

/**
 * Find match candidates for a single bank transaction against unmatched GL journal lines.
 * Returns candidates sorted by confidence DESC.
 */
export function findMatchCandidates(
  bankTx: BankTxForMatch,
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): AutoMatchCandidate[] {
  const candidates: AutoMatchCandidate[] = [];
  const txAmount = Math.abs(bankTx.amount);
  const isDeposit = bankTx.amount > 0;

  for (const line of glLines) {
    // For deposits, match against credit lines; for withdrawals, match against debit lines
    const lineAmount = isDeposit ? line.credit : line.debit;
    if (lineAmount <= 0) continue;

    const amountMatch = Math.abs(txAmount - lineAmount) < 0.02;
    if (!amountMatch) continue;

    // Tier 1: Exact reference match
    if (bankTx.reference && bankTx.reference.trim().length > 2) {
      const ref = bankTx.reference.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      const entryNum = (line.entryNumber || '').toLowerCase();
      const sourceDoc = (line.sourceDocumentId || '').toLowerCase();

      if (lineDesc.includes(ref) || entryNum.includes(ref) || ref.includes(entryNum) || sourceDoc.includes(ref)) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 1.0,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Check description-based reference match
    if (bankTx.description && bankTx.description.trim().length > 3) {
      const desc = bankTx.description.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      if (lineDesc.length > 3 && (desc.includes(lineDesc) || lineDesc.includes(desc))) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 0.95,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Tier 2: Amount + date within 3 days
    const daysDiff = Math.abs(dateDiffDays(bankTx.transactionDate, line.entryDate));
    if (daysDiff <= 3) {
      candidates.push({
        bankTransactionId: bankTx.id,
        journalLineId: line.id,
        confidence: 0.9,
        matchReason: 'amount_date',
      });
      continue;
    }

    // Tier 3: Amount only
    candidates.push({
      bankTransactionId: bankTx.id,
      journalLineId: line.id,
      confidence: 0.7,
      matchReason: 'amount_only',
    });
  }

  return candidates
    .filter(c => c.confidence >= threshold)
    .sort((a, b) => b.confidence - a.confidence);
}

/**
 * Run auto-match across multiple bank transactions.
 * Returns best single match per bank transaction (highest confidence).
 * Prevents duplicate GL line matches.
 */
export function runAutoMatch(
  bankTxs: BankTxForMatch[],
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): { matches: AutoMatchCandidate[]; unmatched: string[] } {
  const matches: AutoMatchCandidate[] = [];
  const usedGlLines = new Set<string>();
  const unmatched: string[] = [];

  // Sort bank transactions by amount DESC for better matching priority
  const sorted = [...bankTxs].sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));

  for (const tx of sorted) {
    const availableLines = glLines.filter(l => !usedGlLines.has(l.id));
    const candidates = findMatchCandidates(tx, availableLines, threshold);

    if (candidates.length > 0) {
      const best = candidates[0]!;
      matches.push(best);
      usedGlLines.add(best.journalLineId);
    } else {
      unmatched.push(tx.id);
    }
  }

  return { matches, unmatched };
}

function dateDiffDays(dateA: string, dateB: string): number {
  const a = new Date(dateA);
  const b = new Date(dateB);
  return Math.round((a.getTime() - b.getTime()) / (1000 * 60 * 60 * 24));
}

import pg from 'pg';
import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('ERROR: DATABASE_URL environment variable is required.');
  process.exit(1);
}

const client = new pg.Client({ connectionString: DATABASE_URL });

async function runMigrations() {
  console.log('=== Accounting Database Migration ===\n');

  await client.connect();
  console.log('Connected to database.\n');

  // Create migration tracking table
  await client.query(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      filename TEXT PRIMARY KEY,
      applied_at TIMESTAMPTZ DEFAULT NOW()
    )
  `);

  // Get already-applied migrations
  const applied = await client.query('SELECT filename FROM schema_migrations ORDER BY filename');
  const appliedSet = new Set(applied.rows.map(r => r.filename));

  // Discover all migration files in order
  const migrationsDir = join(process.cwd(), 'scripts/migrations/sql');
  const allFiles = readdirSync(migrationsDir)
    .filter(f => f.endsWith('.sql'))
    .sort();

  let newCount = 0;

  for (const migration of allFiles) {
    if (appliedSet.has(migration)) {
      continue; // Already applied
    }

    const filePath = join(migrationsDir, migration);
    try {
      const sqlContent = readFileSync(filePath, 'utf-8');
      console.log(`Running: ${migration}`);
      await client.query(sqlContent);
      await client.query('INSERT INTO schema_migrations (filename) VALUES ($1)', [migration]);
      console.log(`  ✓ Done\n`);
      newCount++;
    } catch (error) {
      console.error(`  ✗ Failed: ${error.message}\n`);
      // Fail fast on migration errors — don't leave schema in partial state
      console.error(`ABORTING: Fix the migration and re-run.`);
      await client.end();
      process.exit(1);
    }
  }

/**
 * Document Capture API
 * POST /api/accounting/document-capture  — Upload PDF or image, extract data, save
 * GET  /api/accounting/document-capture  — List captured documents
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { Writable } from 'stream';
import formidable from 'formidable';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf, extractFromImage } from '@/modules/accounting/services/ocrService';
import type { CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

const ALLOWED_MIME_TYPES: Record<string, string> = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpeg',
  'image/jpg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/tiff': 'tiff',
};

/** In-memory file buffer attached to formidable file objects */
const fileBuffers = new WeakMap<formidable.File, Buffer>();

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        const mime = part.mimetype || '';
        return mime in ALLOWED_MIME_TYPES || !mime;
      },
      fileWriteStreamHandler: (file) => {
        const chunks: Buffer[] = [];
        const writable = new Writable({
          write(chunk, _encoding, callback) {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            callback();
          },
          final(callback) {
            fileBuffers.set(file as unknown as formidable.File, Buffer.concat(chunks));
            callback();
          },
        });
        return writable;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
    referenceNumber: row.reference_number as string | null,
    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
    status: (row.status as CapturedDocument['status']) || 'pending',
    matchedInvoiceId: row.matched_invoice_id as string | null,
    matchedBankTxId: row.matched_bank_tx_id as string | null,
    notes: row.notes as string | null,
    uploadedBy: row.uploaded_by as string | null,
    createdAt: new Date(row.created_at as string).toISOString(),
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

/** GET — List captured documents */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const status = req.query.status as string | undefined;
  const page = Math.max(1, parseInt(String(req.query.page || '1'), 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(String(req.query.pageSize || '25'), 10)));
  const offset = (page - 1) * pageSize;

  let rows: Record<string, unknown>[];
  let countResult: Record<string, unknown>[];

  if (status) {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE status = ${status} AND company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE status = ${status} AND company_id = ${companyId}
    ` as Record<string, unknown>[];
  } else {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE company_id = ${companyId}
    ` as Record<string, unknown>[];
  }

  const total = (countResult[0]?.total as number) || 0;
  const documents = rows.map(r => mapRow(r));

  return apiResponse.paginated(res, documents, { page, pageSize, total });
}

/** POST — Upload a PDF or image, extract data, save to captured_documents */
async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const user = (req as NextApiRequest & { user: { id: string } }).user;
  try {
    const { files } = await parseForm(req);

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;

    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded. Please select a PDF or image file.');
    }

    const mimeType = file.mimetype || '';
    const fileTypeKey = ALLOWED_MIME_TYPES[mimeType];

    if (!fileTypeKey) {
      const supported = Object.keys(ALLOWED_MIME_TYPES).join(', ');
      return apiResponse.badRequest(res, `Unsupported file type: ${mimeType}. Supported: ${supported}`);
    }

    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    const buffer = fileBuffers.get(file);
    if (!buffer || buffer.length === 0) {
      return apiResponse.badRequest(res, 'Failed to read uploaded file');
    }

    // Validate file magic bytes
    const hex = buffer.subarray(0, 4).toString('hex').toUpperCase();
    const isPdf = hex.startsWith('25504446'); // %PDF
    const isJpeg = hex.startsWith('FFD8FF');
    const isPng = hex.startsWith('89504E47');
    const isWebp = buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP';
    const isTiff = hex.startsWith('49492A00') || hex.startsWith('4D4D002A');

    if (!isPdf && !isJpeg && !isPng && !isWebp && !isTiff) {
      return apiResponse.badRequest(res, 'File does not appear to be a valid PDF or image');
    }

    log.info('Starting document capture extraction', {
      fileName: file.originalFilename,
      fileSize: file.size,
      mimeType,
      fileType: fileTypeKey,
    }, 'document-capture');

    // Extract data based on file type
    let extracted;
    if (isPdf) {
      extracted = await extractFromPdf(buffer);
    } else {
      extracted = await extractFromImage(buffer, mimeType);
    }

    // Save to database
    const fileName = file.originalFilename || `capture_${Date.now()}.${fileTypeKey}`;

    const [row] = await sql`
      INSERT INTO captured_documents (
        company_id, file_name, file_type, file_size, document_type,
        extracted_data, vendor_name, document_date, reference_number,
        total_amount, vat_amount, status, uploaded_by
      ) VALUES (
        ${companyId},
        ${fileName},
        ${fileTypeKey},
        ${file.size},
        ${extracted.documentType},
        ${JSON.stringify(extracted)}::jsonb,
        ${extracted.vendorName},
        ${extracted.date ? extracted.date : null}::date,
        ${extracted.referenceNumber},
        ${extracted.totalAmount},
        ${extracted.vatAmount},
        'pending',
        ${user?.id || null}::uuid
      )
      RETURNING *
    ` as Record<string, unknown>[];

    log.info('Document captured successfully', {
      id: row?.id,
      confidence: extracted.confidence,
      documentType: extracted.documentType,
      extractionMethod: extracted.extractionMethod,
    }, 'document-capture');

    return apiResponse.created(res, {
      document: mapRow(row as Record<string, unknown>),
      extracted,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Document capture failed', { error: msg }, 'document-capture');

    if (msg.includes('maxFileSize')) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    return apiResponse.internalError(res, err, `Document capture failed: ${msg}`);
  }
}

