      employeeData: sampleData,
      employeeName: 'Test',
      idNumber: '8501015009081',
      taxNumber: '1234567890',
      employerName: 'Test Co',
      employerPayeRef: '7001234567',
      taxYear: 2026,
      periodStart: '2025-03-01',
      periodEnd: '2026-02-28',
