/**
 * TDD: Enhanced Reporting Engine Tests
 * RED phase — written before implementation.
 */

import { describe, it, expect } from 'vitest';
import {
  calculateFinancialRatios,
  buildComparativeData,
  buildManagementPack,
  formatReportNumber,
  calculateVariance,
  type FinancialData,
  type RatioResult,
