// COMPARATIVE DATA
// ═══════════════════════════════════════════════════════════════════════════

describe('Comparative Data Building', () => {
  it('builds period-over-period comparison', () => {
    const current = [
      { account: 'Revenue', amount: 100000 },
      { account: 'Expenses', amount: 60000 },
