// ═══════════════════════════════════════════════════════════════════════════
// STRATEGY SELECTION (Rules → Patterns → LLM)
// ═══════════════════════════════════════════════════════════════════════════

describe('Categorization Strategy Selection', () => {
  it('selects rules strategy when rule match exists', () => {
    const strategy = selectCategorizationStrategy({
      hasRuleMatch: true,
      hasPatternMatch: false,
      ruleConfidence: 1.0,
