/**
 * Smart Categorization Service
 * AI-powered bank transaction categorization using rules, patterns, and historical learning
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW';

export interface CategorizationInput {
  description: string;
  amount: number;
  reference?: string;
}

export interface CategorizationResult {
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  category?: string;
  vatCode?: string;
  confidence: number;
  confidenceLevel: ConfidenceLevel;
  matchSource: 'rule' | 'pattern' | 'historical';
  matchDetail?: string;
}

export interface BulkCategorizationResult {
  categorized: number;
  skipped: number;
  results: Array<{
    transactionId: string;
    result: CategorizationResult | null;
  }>;
}

// ── Confidence helpers ───────────────────────────────────────────────────────

function toConfidenceLevel(score: number): ConfidenceLevel {
  if (score >= 0.85) return 'HIGH';
  if (score >= 0.60) return 'MEDIUM';
  return 'LOW';
}

// ── Core: Categorize a single transaction ────────────────────────────────────

export async function categorizeBankTransaction(_companyId: string, 
  tx: CategorizationInput
): Promise<CategorizationResult | null> {
  const description = (tx.description || '').toUpperCase().trim();
  const reference = (tx.reference || '').toUpperCase().trim();

  if (!description && !reference) return null;

  // 1. Check existing bank_categorisation_rules (highest priority)
  const ruleMatch = await matchAgainstRules(description, reference);
  if (ruleMatch) return ruleMatch;

  // 2. Check categorization_patterns table (system + learned patterns)
  const patternMatch = await matchAgainstPatterns(description, reference);
  if (patternMatch) return patternMatch;

  // 3. Learn from historical allocations (similar past transactions)
  const historicalMatch = await matchFromHistory(description, tx.amount);
  if (historicalMatch) return historicalMatch;

  return null;
}

// ── Strategy 1: Match against bank_categorisation_rules ──────────────────────

async function matchAgainstRules(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const rules = (await sql`
      SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
      WHERE r.is_active = true
      ORDER BY r.priority ASC
    `) as Row[];

    for (const rule of rules) {
      const pattern = String(rule.match_pattern).toUpperCase();
      const matchType = String(rule.match_type);
      const matchField = String(rule.match_field);

      const targets: string[] = [];
      if (matchField === 'description' || matchField === 'both') targets.push(description);
      if (matchField === 'reference' || matchField === 'both') targets.push(reference);

      const matched = targets.some(target => {
        switch (matchType) {
          case 'contains': return target.includes(pattern);
          case 'starts_with': return target.startsWith(pattern);
          case 'ends_with': return target.endsWith(pattern);
          case 'exact': return target === pattern;
          default: return target.includes(pattern);
        }
      });

      if (matched) {
        return {
          glAccountId: rule.gl_account_id ? String(rule.gl_account_id) : undefined,
          glAccountCode: rule.gl_account_code ? String(rule.gl_account_code) : undefined,
          glAccountName: rule.gl_account_name ? String(rule.gl_account_name) : undefined,
          category: String(rule.rule_name),
          vatCode: String(rule.vat_code || 'none'),
          confidence: 0.95,
          confidenceLevel: 'HIGH',
          matchSource: 'rule',
          matchDetail: `Rule: ${rule.rule_name} (${matchType} "${rule.match_pattern}")`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: rule matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 2: Match against categorization_patterns ────────────────────────

async function matchAgainstPatterns(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const patterns = (await sql`
      SELECT cp.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM categorization_patterns cp
      LEFT JOIN gl_accounts ga ON ga.id = cp.gl_account_id
      ORDER BY cp.confidence DESC, cp.usage_count DESC
    `) as Row[];

    const combined = `${description} ${reference}`;

    for (const p of patterns) {
      const pat = String(p.pattern).toUpperCase();
      const matchType = String(p.match_type);

      let matched = false;
      switch (matchType) {
        case 'contains':
          matched = combined.includes(pat);
          break;
        case 'starts_with':
          matched = description.startsWith(pat) || reference.startsWith(pat);
          break;
        case 'regex':
          try {
            const re = new RegExp(p.pattern, 'i');
            matched = re.test(description) || re.test(reference);
          } catch {
            // WORKING: invalid regex patterns are safely skipped
            matched = false;
          }
          break;
        default:
          matched = combined.includes(pat);
      }

      if (matched) {
        const confidence = Number(p.confidence) || 0.80;

        // Update usage stats (fire-and-forget)
        sql`
          UPDATE categorization_patterns
          SET usage_count = usage_count + 1, last_used_at = NOW()
          WHERE id = ${p.id}::UUID
        `.catch(() => {});

        return {
          glAccountId: p.gl_account_id ? String(p.gl_account_id) : undefined,
          glAccountCode: p.gl_account_code ? String(p.gl_account_code) : undefined,
          glAccountName: p.gl_account_name ? String(p.gl_account_name) : undefined,
          category: p.category ? String(p.category) : undefined,
          vatCode: String(p.vat_code || 'standard'),
          confidence,
          confidenceLevel: toConfidenceLevel(confidence),
          matchSource: 'pattern',
          matchDetail: `Pattern: "${p.pattern}" (${p.source})`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: pattern matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 3: Learn from historical allocations ────────────────────────────

async function matchFromHistory(
  description: string,
  _amount: number
): Promise<CategorizationResult | null> {
  if (!description || description.length < 3) return null;

  try {
    // Extract significant words (3+ chars, skip common banking noise)
    const noiseWords = new Set([
      'THE', 'AND', 'FOR', 'FROM', 'WITH', 'PAYMENT', 'TRANSFER',
      'DEBIT', 'CREDIT', 'ORDER', 'REF', 'POS', 'PURCHASE', 'CARD',
    ]);
    const words = description
      .split(/[\s/\\,.-]+/)
      .filter(w => w.length >= 3 && !noiseWords.has(w) && !/^\d+$/.test(w));

    if (words.length === 0) return null;

    // Build search: look for allocated transactions with similar descriptions
    // Use the first 2-3 significant words for matching
    const searchWords = words.slice(0, 3);
    const likePattern = `%${searchWords.join('%')}%`;

    const historicalRows = (await sql`
      SELECT
        bt.suggested_gl_account_id,
        bt.suggested_category,
        bt.suggested_vat_code,
        bt.allocation_type,
        ga.account_code AS gl_account_code,
        ga.account_name AS gl_account_name,
        COUNT(*) AS match_count
      FROM bank_transactions bt
      LEFT JOIN gl_accounts ga ON ga.id = bt.suggested_gl_account_id
      WHERE bt.status IN ('matched', 'reconciled')
        AND bt.matched_journal_line_id IS NOT NULL
        AND bt.suggested_gl_account_id IS NOT NULL
        AND UPPER(bt.description) ILIKE ${likePattern}
      GROUP BY bt.suggested_gl_account_id, bt.suggested_category,
               bt.suggested_vat_code, bt.allocation_type,
               ga.account_code, ga.account_name
      ORDER BY match_count DESC
      LIMIT 1
    `) as Row[];

    if (historicalRows.length > 0) {
      const row = historicalRows[0];
      const matchCount = Number(row.match_count);
      // Scale confidence based on how many historical matches we found
      const baseConfidence = matchCount >= 5 ? 0.70 : matchCount >= 2 ? 0.55 : 0.40;

      return {
        glAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
        glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
        glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
        category: row.suggested_category ? String(row.suggested_category) : undefined,
        vatCode: String(row.suggested_vat_code || 'none'),
        confidence: baseConfidence,
        confidenceLevel: toConfidenceLevel(baseConfidence),
        matchSource: 'historical',
        matchDetail: `Historical: ${matchCount} similar transaction(s)`,
      };
    }
  } catch (err) {
    log.error('Smart categorization: historical matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Learn from user allocation ───────────────────────────────────────────────

export async function learnFromAllocation(_companyId: string, 
  txId: string,
  glAccountId: string,
  category: string,
  vatCode?: string
): Promise<void> {
  try {
    // Get the transaction description
    const txRows = (await sql`
      SELECT description FROM bank_transactions WHERE id = ${txId}::UUID
    `) as Row[];

    if (txRows.length === 0) return;

    const description = String(txRows[0].description || '').trim();
    if (description.length < 3) return;

    // Extract a clean pattern from the description
    // Remove trailing numbers, dates, and references to get the merchant/payee name
    const pattern = extractLearningPattern(description);
    if (!pattern || pattern.length < 3) return;

    // Check if we already have this pattern
    const existing = (await sql`
      SELECT id, usage_count FROM categorization_patterns
      WHERE UPPER(pattern) = ${pattern.toUpperCase()}
        AND source = 'learned'
      LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      // Update existing pattern — increase confidence with use
      const newCount = Number(existing[0].usage_count) + 1;
      const newConfidence = Math.min(0.95, 0.60 + newCount * 0.05);
      await sql`
        UPDATE categorization_patterns
        SET gl_account_id = ${glAccountId}::UUID,
            category = ${category},
            vat_code = ${vatCode || 'standard'},
            usage_count = ${newCount},
            confidence = ${newConfidence},
            last_used_at = NOW()
        WHERE id = ${existing[0].id}::UUID
      `;
    } else {
      // Create new learned pattern
      await sql`
        INSERT INTO categorization_patterns (pattern, match_type, gl_account_id, category, vat_code, confidence, usage_count, last_used_at, source)
        VALUES (${pattern}, 'contains', ${glAccountId}::UUID, ${category}, ${vatCode || 'standard'}, 0.65, 1, NOW(), 'learned')
      `;
    }

    log.info('Learned categorization pattern', { pattern, category, glAccountId }, 'accounting');
  } catch (err) {
    log.error('Failed to learn from allocation', { txId, error: err }, 'accounting');
    // Non-critical: don't throw — learning failures should not break allocation flow
  }
}

/**
 * Extract a clean pattern from a bank transaction description.
 * Strips trailing reference numbers, dates, card numbers, etc.
 */
function extractLearningPattern(description: string): string {
  let clean = description.toUpperCase();

  // Remove common suffixes: card numbers, dates, reference numbers
  clean = clean.replace(/\b\d{4}\*+\d{4}\b/g, '');      // Card number masks
  clean = clean.replace(/\b\d{2}\/\d{2}\/\d{2,4}\b/g, ''); // Dates
  clean = clean.replace(/\b\d{6,}\b/g, '');               // Long number sequences
  clean = clean.replace(/\bREF\s*:?\s*\S+/gi, '');        // REF: xxx
  clean = clean.replace(/\bPOS\b/g, '');                   // POS prefix
  clean = clean.replace(/\bPURCHASE\b/g, '');              // PURCHASE label

  // Trim and collapse whitespace
  clean = clean.replace(/\s+/g, ' ').trim();

  // Take the first meaningful part (usually merchant name)
  const parts = clean.split(/\s{2,}/);
  return parts[0]?.trim() || clean;
}

// ── Bulk categorize ──────────────────────────────────────────────────────────

export async function bulkCategorize(_companyId: string, 
  transactionIds: string[]
): Promise<BulkCategorizationResult> {
  if (transactionIds.length === 0) {
    return { categorized: 0, skipped: 0, results: [] };
  }

  // Fetch all requested transactions
  const txRows = (await sql`
    SELECT id, description, amount, reference
    FROM bank_transactions
    WHERE id = ANY(${transactionIds}::UUID[])
      AND status IN ('imported', 'allocated')
  `) as Row[];

  let categorized = 0;
  let skipped = 0;
  const results: BulkCategorizationResult['results'] = [];

  for (const tx of txRows) {
    const txId = String(tx.id);
    const input: CategorizationInput = {
      description: String(tx.description || ''),
      amount: Number(tx.amount),
      reference: tx.reference ? String(tx.reference) : undefined,
    };

    const result = await categorizeBankTransaction('', input);

    if (result) {
      // Write suggestion back to the transaction
      await sql`
        UPDATE bank_transactions SET
          suggested_gl_account_id = COALESCE(${result.glAccountId || null}::UUID, suggested_gl_account_id),
          suggested_category = COALESCE(${result.category || null}, suggested_category),
          suggested_vat_code = COALESCE(${result.vatCode || null}, suggested_vat_code),
          suggested_confidence = ${result.confidence}
        WHERE id = ${txId}::UUID
          AND suggested_gl_account_id IS NULL
      `;
      categorized++;
      results.push({ transactionId: txId, result });
    } else {
      skipped++;
      results.push({ transactionId: txId, result: null });
    }
  }

  log.info('Bulk smart categorization complete', { categorized, skipped, total: txRows.length }, 'accounting');

  return { categorized, skipped, results };
}

// ── Categorize all uncategorized transactions for a bank account ──────────────

export async function smartCategorizeForAccount(_companyId: string, 
  bankAccountId: string
): Promise<BulkCategorizationResult> {
  // Get all uncategorized transactions for this bank account
  const txRows = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND status IN ('imported', 'allocated')
      AND suggested_gl_account_id IS NULL
      AND suggested_category IS NULL
    ORDER BY transaction_date DESC
    LIMIT 500
  `) as Row[];

  const ids = txRows.map((r: Row) => String(r.id));
  return bulkCategorize('', ids);
}

/**
 * AI Transaction Categorization Service
 * Tiered approach: Rules (free) → Patterns → LLM (Claude API)
 * Pure business logic for prompt building, parsing, strategy selection.
 * Actual LLM calls are made by the API layer.
 */

export interface TransactionContext {
  description: string;
  amount: number;
  date: string;
  isDebit: boolean;
  bankName?: string;
  reference?: string;
}

export interface ChartOfAccountEntry {
  code: string;
  name: string;
  type: string;
}

export interface CategorizationResult {
  accountCode: string;
  accountName: string;
  confidence: number;
  reason: string;
  strategy: CategorizationStrategy;
}

export type CategorizationStrategy = 'rules' | 'patterns' | 'llm';

export interface ConfidenceLevel {
  level: 'HIGH' | 'MEDIUM' | 'LOW';
  color: 'green' | 'amber' | 'gray';
  score: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// PROMPT BUILDING
// ═══════════════════════════════════════════════════════════════════════════

export function buildCategorizationPrompt(
  tx: TransactionContext,
  accounts: ChartOfAccountEntry[],
): string {
  const direction = tx.isDebit ? 'debit (money out)' : 'credit (money in)';
  const accountList = accounts
    .map(a => `  ${a.code} - ${a.name} (${a.type})`)
    .join('\n');

  return `You are a South African bookkeeper. Categorize this bank transaction to the correct GL account.

Transaction:
- Description: ${tx.description}
- Amount: R${Math.abs(tx.amount).toFixed(2)}
- Direction: ${direction}
- Date: ${tx.date}
${tx.reference ? `- Reference: ${tx.reference}` : ''}

Chart of Accounts:
${accountList}

Respond in JSON format only:
{"accountCode": "xxxx", "accountName": "Account Name", "confidence": 0.0-1.0, "reason": "Brief explanation"}

Rules:
- Match the transaction to the most appropriate account
- Consider South African merchant names and conventions
- Confidence should reflect how certain you are (0.5 = guess, 0.9+ = very confident)
- For ${direction}, select an appropriate ${tx.isDebit ? 'expense/asset' : 'revenue/liability'} account`;
}

// ═══════════════════════════════════════════════════════════════════════════
// RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseCategorizationResponse(response: string): CategorizationResult | null {
  if (!response || response.trim() === '') return null;

  try {
    // Try to extract JSON from the response (might be wrapped in markdown code blocks)
    let jsonStr = response;

    // Extract from ```json ... ``` blocks
    const jsonMatch = response.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) {
      jsonStr = jsonMatch[1]!;
    } else {
      // Try to find a JSON object in the text
      const objMatch = response.match(/\{[\s\S]*"accountCode"[\s\S]*\}/);
      if (objMatch) {
        jsonStr = objMatch[0];
      }
    }

    const parsed = JSON.parse(jsonStr);

    return {
      accountCode: String(parsed.accountCode || ''),
      accountName: String(parsed.accountName || ''),
      confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.5,
      reason: String(parsed.reason || ''),
      strategy: 'llm',
    };
  } catch {
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// STRATEGY SELECTION
// ═══════════════════════════════════════════════════════════════════════════

const PATTERN_CONFIDENCE_THRESHOLD = 0.6;

export function selectCategorizationStrategy(input: {
  hasRuleMatch: boolean;
  hasPatternMatch: boolean;
  ruleConfidence: number;
  patternConfidence: number;
}): CategorizationStrategy {
  // Rules are always preferred (deterministic, free)
  if (input.hasRuleMatch && input.ruleConfidence > 0) return 'rules';

  // Patterns used if confidence is high enough
  if (input.hasPatternMatch && input.patternConfidence >= PATTERN_CONFIDENCE_THRESHOLD) return 'patterns';

  // Fall back to LLM
  return 'llm';
}

// ═══════════════════════════════════════════════════════════════════════════
// CONFIDENCE
// ═══════════════════════════════════════════════════════════════════════════

export function calculateConfidence(score: number): ConfidenceLevel {
  const clamped = Math.max(0, Math.min(1, score));

  if (clamped >= 0.85) return { level: 'HIGH', color: 'green', score: clamped };
  if (clamped >= 0.60) return { level: 'MEDIUM', color: 'amber', score: clamped };
  return { level: 'LOW', color: 'gray', score: clamped };
}

// ═══════════════════════════════════════════════════════════════════════════
// RESULT MERGING
// ═══════════════════════════════════════════════════════════════════════════

export function mergeCategorizationResults(results: CategorizationResult[]): CategorizationResult {
  if (results.length === 0) {
    return { accountCode: '', accountName: '', confidence: 0, reason: '', strategy: 'llm' };
  }

  if (results.length === 1) return results[0]!;

  // Rules always win if present
  const ruleResult = results.find(r => r.strategy === 'rules');
  if (ruleResult) return ruleResult;

  // Check if multiple strategies agree on the same account
  const accountCounts = new Map<string, CategorizationResult[]>();
  for (const r of results) {
    const existing = accountCounts.get(r.accountCode) || [];
    existing.push(r);
    accountCounts.set(r.accountCode, existing);
  }

  // Find the account code with most agreement
  let bestCode = '';
  let bestResults: CategorizationResult[] = [];
  for (const [code, group] of accountCounts) {
    if (group.length > bestResults.length || (group.length === bestResults.length && Math.max(...group.map(r => r.confidence)) > Math.max(...bestResults.map(r => r.confidence)))) {
      bestCode = code;
      bestResults = group;
    }
  }

  const highestConfResult = bestResults.reduce((best, r) => r.confidence > best.confidence ? r : best, bestResults[0]!);

  // Boost confidence when multiple strategies agree
  let boostedConfidence = highestConfResult.confidence;
  if (bestResults.length > 1) {
    boostedConfidence = Math.min(1, boostedConfidence + 0.1 * (bestResults.length - 1));
  }

  return {
    ...highestConfResult,
    confidence: Math.round(boostedConfidence * 100) / 100,
  };
}

/**
 * Document Validation Service
 * Compares VLM-extracted data against entity records to detect discrepancies.
 */

import type {
  ExtractedDocument,
  ExtractedStatutoryDoc,
  ValidationDiscrepancy,
  DocumentValidationResult,
} from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Invoice Validation
// ---------------------------------------------------------------------------

interface InvoiceRecord {
  invoiceNumber?: string;
  totalAmount?: number;
  vatAmount?: number;
  taxRate?: number;
  vendorName?: string;
  supplierName?: string;
  customerName?: string;
  clientName?: string;
  invoiceDate?: string;
}

export function validateInvoiceDocument(
  extracted: ExtractedDocument,
  invoice: InvoiceRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  // Total amount
  if (extracted.totalAmount !== null && invoice.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - invoice.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: invoice.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > invoice.totalAmount * 0.05 ? 'error' : 'warning',
        message: `Total mismatch: document shows ${extracted.totalAmount}, record has ${invoice.totalAmount}`,
      });
    }
  }

  // VAT amount
  if (extracted.vatAmount !== null && invoice.vatAmount !== undefined) {
    const diff = Math.abs(extracted.vatAmount - invoice.vatAmount);
    if (diff > 1) {
      discrepancies.push({
        field: 'vatAmount',
        expected: invoice.vatAmount,
        actual: extracted.vatAmount,
        severity: 'warning',
        message: `VAT mismatch: document shows ${extracted.vatAmount}, record has ${invoice.vatAmount}`,
      });
    }
  }

  // VAT arithmetic check
  if (extracted.subtotal !== null && extracted.vatAmount !== null && extracted.totalAmount !== null) {
    const expected = Math.round((extracted.subtotal + extracted.vatAmount) * 100) / 100;
    if (Math.abs(expected - extracted.totalAmount) > 0.02) {
      discrepancies.push({
        field: 'vatArithmetic',
        expected: expected,
        actual: extracted.totalAmount,
        severity: 'error',
        message: `VAT arithmetic error on document: subtotal (${extracted.subtotal}) + VAT (${extracted.vatAmount}) = ${expected}, but total shows ${extracted.totalAmount}`,
      });
    }
  }

  // Reference number
  if (extracted.referenceNumber && invoice.invoiceNumber) {
    const normExtracted = extracted.referenceNumber.replace(/[-\s/]/g, '').toLowerCase();
    const normInvoice = invoice.invoiceNumber.replace(/[-\s/]/g, '').toLowerCase();
    if (normExtracted !== normInvoice) {
      discrepancies.push({
        field: 'referenceNumber',
        expected: invoice.invoiceNumber,
        actual: extracted.referenceNumber,
        severity: 'warning',
        message: `Reference mismatch: document shows "${extracted.referenceNumber}", record has "${invoice.invoiceNumber}"`,
      });
    }
  }

  // Vendor/customer name (fuzzy check)
  const entityName = invoice.vendorName || invoice.supplierName || invoice.customerName || invoice.clientName;
  const extractedName = extracted.vendorName || extracted.customerName;
  if (entityName && extractedName) {
    const normEntity = entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normExtracted = extractedName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normEntity) && !normEntity.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: entityName,
        actual: extractedName,
        severity: 'warning',
        message: `Name mismatch: document shows "${extractedName}", record has "${entityName}"`,
      });
    }
  }

  // Date check
  if (extracted.date && invoice.invoiceDate) {
    if (extracted.date !== invoice.invoiceDate) {
      discrepancies.push({
        field: 'date',
        expected: invoice.invoiceDate,
        actual: extracted.date,
        severity: 'info',
        message: `Date differs: document shows ${extracted.date}, record has ${invoice.invoiceDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const warningCount = discrepancies.filter(d => d.severity === 'warning').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + warningCount * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Payment Receipt Validation
// ---------------------------------------------------------------------------

interface PaymentRecord {
  totalAmount?: number;
  paymentDate?: string;
  reference?: string;
  bankReference?: string;
}

export function validatePaymentReceipt(
  extracted: ExtractedDocument,
  payment: PaymentRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.totalAmount !== null && payment.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - payment.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: payment.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > payment.totalAmount * 0.01 ? 'error' : 'warning',
        message: `Amount mismatch: receipt shows ${extracted.totalAmount}, payment record has ${payment.totalAmount}`,
      });
    }
  }

  if (extracted.date && payment.paymentDate) {
    const docDate = new Date(extracted.date);
    const payDate = new Date(payment.paymentDate);
    const daysDiff = Math.abs((docDate.getTime() - payDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > 7) {
      discrepancies.push({
        field: 'date',
        expected: payment.paymentDate,
        actual: extracted.date,
        severity: 'warning',
        message: `Date differs by ${Math.round(daysDiff)} days: receipt ${extracted.date}, payment ${payment.paymentDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Statutory Compliance Validation
// ---------------------------------------------------------------------------

interface CompanyRecord {
  companyName?: string;
  registrationNumber?: string;
  vatNumber?: string;
}

export function validateStatutoryCompliance(
  extracted: ExtractedStatutoryDoc,
  company: CompanyRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.entityName && company.companyName) {
    const normExtracted = extracted.entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normCompany = company.companyName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normCompany) && !normCompany.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: company.companyName,
        actual: extracted.entityName,
        severity: 'error',
        message: `Entity name mismatch: certificate shows "${extracted.entityName}", company is "${company.companyName}"`,
      });
    }
  }

  if (extracted.expiryDate) {
    const expiry = new Date(extracted.expiryDate);
    const now = new Date();
    if (expiry < now) {
      discrepancies.push({
        field: 'expiryDate',
        expected: 'valid (not expired)',
        actual: extracted.expiryDate,
        severity: 'error',
        message: `Certificate expired on ${extracted.expiryDate}`,
      });
    } else {
      const daysUntil = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (daysUntil < 30) {
        discrepancies.push({
          field: 'expiryDate',
          expected: 'valid for >30 days',
          actual: `${daysUntil} days remaining`,
          severity: 'warning',
          message: `Certificate expires in ${daysUntil} days (${extracted.expiryDate})`,
        });
      }
    }
  }

  if (extracted.vatNumber && company.vatNumber && extracted.vatNumber !== company.vatNumber) {
    discrepancies.push({
      field: 'vatNumber',
      expected: company.vatNumber,
      actual: extracted.vatNumber,
      severity: 'error',
      message: `VAT number mismatch: certificate shows ${extracted.vatNumber}, company has ${company.vatNumber}`,
    });
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

