                    <div className="px-6 py-3 border-b border-[var(--ff-border-light)] bg-purple-500/5 flex items-center">
                      <h3 className="font-semibold text-purple-400">Equity</h3>
                      {compHeader}
                    </div>
                    <div className="divide-y divide-[var(--ff-border-light)]">
                      {report.equity.map(e => (
                        <div key={e.accountCode}>
                          <button onClick={() => setExpandedAccount(expandedAccount === e.accountCode ? null : e.accountCode)}
                            className="w-full px-6 py-2 flex justify-between text-sm hover:bg-[var(--ff-bg-tertiary)] cursor-pointer">
                            <span className="flex items-center gap-1 text-[var(--ff-text-secondary)]">
                              {expandedAccount === e.accountCode ? <ChevronDown className="h-3 w-3 text-[var(--ff-text-tertiary)]" /> : <ChevronRight className="h-3 w-3 text-[var(--ff-text-tertiary)]" />}
                              <span className="font-mono text-xs mr-2">{e.accountCode}</span>{e.accountName}
                            </span>
                            {showComparative && e.priorBalance !== undefined ? (
                              <span className="flex items-center gap-3">
                                <span className="font-mono text-[var(--ff-text-tertiary)] text-xs w-24 text-right">{formatCurrency(e.priorBalance)}</span>
                                <span className="font-mono text-[var(--ff-text-primary)] w-24 text-right">{formatCurrency(e.balance)}</span>
                                <span className={`font-mono text-xs w-20 text-right ${(e.variance ?? 0) >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                                  {(e.variance ?? 0) >= 0 ? '+' : ''}{formatCurrency(e.variance ?? 0)}
                                </span>
                              </span>
                            ) : (
                              <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(e.balance)}</span>
                            )}
                          </button>
                          {expandedAccount === e.accountCode && (
                            <AccountDrillDown accountCode={e.accountCode} periodStart={drillDownStart} periodEnd={drillDownEnd} />
                          )}
                        </div>
                      ))}
                      {report.equity.length === 0 && <div className="px-6 py-3 text-sm text-[var(--ff-text-tertiary)]">No equity balances</div>}
                    </div>
                    <div className="px-6 py-2 border-t border-[var(--ff-border-light)] flex justify-between">
                      <span className="font-medium text-sm text-[var(--ff-text-primary)]">Total Equity
                        {showComparative && report.priorTotalEquity !== undefined && (
                          <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">(prior: {formatCurrency(report.priorTotalEquity)})</span>
                        )}
                      </span>
                      <span className="font-medium font-mono text-purple-400">{formatCurrency(report.totalEquity)}</span>
                    </div>
                  </div>

                  {/* L + E Total */}
                  <div className="px-6 py-3 bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] flex justify-between">
                    <span className="font-semibold text-[var(--ff-text-primary)]">Total L + E</span>
                    <span className="font-bold font-mono text-blue-400">{formatCurrency(report.totalLiabilities + report.totalEquity)}</span>
                  </div>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Cash Flow Statement
 * Sage equivalent: Reports > Cash Flow
 * Operating, Investing, Financing activities
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Banknote, Loader2, AlertCircle, Download } from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface CashFlowSection {
  section: string;
  items: { label: string; amount: number }[];
  total: number;
}

interface CashFlowReport {
  period_start: string;
  period_end: string;
  sections: CashFlowSection[];
  net_change: number;
  opening_cash: number;
  closing_cash: number;
}

interface CostCentre { id: string; code: string; name: string }

export default function CashFlowPage() {
  const [report, setReport] = useState<CashFlowReport | null>(null);
  const [costCentres, setCostCentres] = useState<CostCentre[]>([]);
  const [costCentreFilter, setCostCentreFilter] = useState('');
  const [startDate, setStartDate] = useState(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    d.setDate(1);
    return d.toISOString().split('T')[0];
  });
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    apiFetch('/api/accounting/cost-centres', { credentials: 'include' }).then(r => r.json()).then(res => {
      const list = res.data?.items || [];
      setCostCentres(list.map((c: Record<string, unknown>) => ({ id: String(c.id), code: String(c.code), name: String(c.name) })));
    }).catch(() => { /* reference data load failure — non-critical, cost centre filter will be empty */ });
  }, []);

  const loadReport = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ start_date: startDate || '', end_date: endDate || '' });
      if (costCentreFilter) params.set('cost_centre', costCentreFilter);
      const res = await apiFetch(`/api/accounting/reports-cash-flow?${params}`);
      const json = await res.json();
      if (!res.ok) {
        setError(json?.error?.message || 'Failed to load cash flow statement');
        return;
      }
      const data = json.data || json;
      setReport(data.report || data);
    } catch {
      setError('Failed to load cash flow statement');
    } finally {
      setIsLoading(false);
    }
  }, [startDate, endDate, costCentreFilter]);

  useEffect(() => { loadReport(); }, [loadReport]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-green-500/10">
                  <Banknote className="h-6 w-6 text-green-500" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Cash Flow Statement</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    Operating, investing and financing activities
                  </p>
                </div>
              </div>
              <button onClick={() => {
                if (!startDate || !endDate) return;
                const params = new URLSearchParams({ period_start: startDate, period_end: endDate });
                window.open(`/api/accounting/cash-flow-export?${params}`, '_blank');
              }} disabled={!report}
                className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg flex items-center gap-2 text-sm font-medium disabled:opacity-50">
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-4xl">
          {/* Date filters */}
          <div className="flex items-center gap-4 mb-6">
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">From</label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              />
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">To</label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              />
            </div>
            {costCentres.length > 0 && (
              <div>
                <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Cost Centre</label>
                <select value={costCentreFilter} onChange={e => setCostCentreFilter(e.target.value)} className="ff-select text-sm">
                  <option value="">All Cost Centres</option>
                  {costCentres.map(cc => <option key={cc.id} value={cc.code}>{cc.code} — {cc.name}</option>)}
                </select>
              </div>
            )}
          </div>

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-green-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : !report ? (
            <div className="text-center py-12">
              <Banknote className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No cash flow data available for this period</p>
            </div>
          ) : (
            <div className="space-y-6">
              {/* Opening Cash */}
              <div className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
                <div className="flex justify-between">
                  <span className="font-medium text-[var(--ff-text-primary)]">Opening Cash Balance</span>
                  <span className="font-mono font-bold text-[var(--ff-text-primary)]">{formatCurrency(report.opening_cash)}</span>
                </div>
              </div>

              {/* Sections */}
              {(report.sections || []).map((section) => (
                <div key={section.section} className="rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] overflow-hidden">
                  <div className="px-4 py-3 bg-[var(--ff-bg-tertiary)] border-b border-[var(--ff-border-light)]">
                    <h3 className="font-semibold text-[var(--ff-text-primary)]">{section.section}</h3>
                  </div>
                  <div className="divide-y divide-[var(--ff-border-light)]">
                    {section.items.map((item, i) => (
                      <div key={i} className="flex justify-between px-4 py-2.5">
                        <span className="text-sm text-[var(--ff-text-secondary)]">{item.label}</span>
                        <span className={`text-sm font-mono ${item.amount >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                          {formatCurrency(item.amount)}
                        </span>
                      </div>
                    ))}
                  </div>
                  <div className="flex justify-between px-4 py-3 bg-[var(--ff-bg-tertiary)] border-t border-[var(--ff-border-light)]">
                    <span className="font-medium text-[var(--ff-text-primary)]">Net {section.section}</span>
                    <span className={`font-mono font-bold ${section.total >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                      {formatCurrency(section.total)}
                    </span>
                  </div>
                </div>
              ))}

              {/* Net Change & Closing */}
              <div className="p-4 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] space-y-3">
                <div className="flex justify-between">
                  <span className="text-[var(--ff-text-secondary)]">Net Change in Cash</span>
                  <span className={`font-mono font-bold ${report.net_change >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {formatCurrency(report.net_change)}
                  </span>
                </div>
                <div className="flex justify-between pt-3 border-t border-[var(--ff-border-light)]">
                  <span className="font-medium text-[var(--ff-text-primary)]">Closing Cash Balance</span>
                  <span className="font-mono font-bold text-lg text-[var(--ff-text-primary)]">{formatCurrency(report.closing_cash)}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * VAT201 Return Report Page
 * Full SARS VAT201 form with expandable transaction drill-down
 * Sage equivalent: Accountant's Area > VAT > VAT Return
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Receipt,
  Loader2,
  AlertCircle,
  ChevronDown,
  ChevronRight,
  Download,
  FileText,
} from 'lucide-react';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface VAT201Transaction {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  description: string;
  sourceDocument?: string;
  amount: number;
}

interface VAT201Box {
  box: string;
  label: string;
  amount: number;
  transactions?: VAT201Transaction[];
}

interface VAT201Report {
  periodStart: string;
  periodEnd: string;
  outputBoxes: VAT201Box[];
  totalOutputTax: number;
  inputBoxes: VAT201Box[];
  totalInputTax: number;
  netVAT: number;
}

function getDefaultDates() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const end = new Date(now.getFullYear(), now.getMonth(), 0);
  return {
    periodStart: start.toISOString().split('T')[0],
    periodEnd: end.toISOString().split('T')[0],
  };
}

function BoxRow({ box, section }: { box: VAT201Box; section: 'output' | 'input' }) {
  const [expanded, setExpanded] = useState(false);
  const hasTransactions = box.transactions && box.transactions.length > 0;
  const isPositive = box.amount > 0;
  const colorClass = section === 'output'
    ? (isPositive ? 'text-red-400' : 'text-[var(--ff-text-tertiary)]')
    : (isPositive ? 'text-teal-400' : 'text-[var(--ff-text-tertiary)]');

  return (
    <div>
      <button
        onClick={() => hasTransactions && setExpanded(!expanded)}
        className={`w-full flex items-center justify-between px-4 py-2.5 text-sm border-b border-[var(--ff-border-light)] transition-colors ${
          hasTransactions ? 'hover:bg-[var(--ff-bg-tertiary)] cursor-pointer' : 'cursor-default'
        } ${expanded ? 'bg-[var(--ff-bg-tertiary)]' : ''}`}
      >
        <div className="flex items-center gap-2">
          {hasTransactions ? (
            expanded ? <ChevronDown className="h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" /> : <ChevronRight className="h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" />
          ) : (
            <span className="w-3.5" />
          )}
          <span className="font-mono text-xs text-[var(--ff-text-tertiary)] w-12">{box.box}</span>
          <span className="text-[var(--ff-text-secondary)]">{box.label}</span>
          {hasTransactions && (
            <span className="text-xs text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-tertiary)] px-1.5 py-0.5 rounded">
              {box.transactions!.length}
            </span>
          )}
        </div>
        <span className={`font-mono font-medium ${Math.abs(box.amount) < 0.01 ? 'text-[var(--ff-text-tertiary)]' : colorClass}`}>
          {formatCurrency(box.amount)}
        </span>
      </button>

      {expanded && hasTransactions && (
        <div className="bg-[var(--ff-bg-primary)] border-b border-[var(--ff-border-light)]">
          <div className="px-4 py-1.5 flex items-center gap-4 text-xs text-[var(--ff-text-tertiary)] border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]/50">
            <span className="w-24">Date</span>
            <span className="w-28">Entry #</span>
            <span className="flex-1">Description</span>
            <span className="w-28 text-right">Amount</span>
          </div>
          {box.transactions!.map((tx, i) => (
            <div
              key={`${tx.journalEntryId}-${i}`}
              className="px-4 py-1.5 flex items-center gap-4 text-xs border-b border-[var(--ff-border-light)]/50 hover:bg-[var(--ff-bg-tertiary)]/30"
            >
              <span className="w-24 text-[var(--ff-text-tertiary)]">{formatDate(tx.entryDate)}</span>
              <span className="w-28 font-mono text-[var(--ff-text-secondary)]">{tx.entryNumber}</span>
              <span className="flex-1 text-[var(--ff-text-secondary)] truncate">{tx.description}</span>
              <span className={`w-28 text-right font-mono ${tx.amount >= 0 ? colorClass : 'text-[var(--ff-text-tertiary)]'}`}>
                {formatCurrency(tx.amount)}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function VATReturnPage() {
  const defaults = getDefaultDates();
  const [periodStart, setPeriodStart] = useState(defaults.periodStart);
  const [periodEnd, setPeriodEnd] = useState(defaults.periodEnd);
  const [report, setReport] = useState<VAT201Report | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const loadReport = useCallback(async () => {
    if (!periodStart || !periodEnd) return;
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
      const res = await apiFetch(`/api/accounting/reports-vat-return?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load');
      setReport(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load VAT return');
    } finally {
      setIsLoading(false);
    }
  }, [periodStart, periodEnd]);

  useEffect(() => { loadReport(); }, [loadReport]);

  const outputWithActivity = report?.outputBoxes.filter(b => Math.abs(b.amount) > 0.01) || [];
  const inputWithActivity = report?.inputBoxes.filter(b => Math.abs(b.amount) > 0.01) || [];

  return (
    <AppLayout>
