        <div className="p-6 max-w-5xl space-y-6">
          {/* Date filters */}
          <div className="flex items-center gap-4">
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Period Start</label>
              <input
                type="date"
