                  ? 'border-red-500/40 bg-red-500/5'
                  : 'border-teal-500/40 bg-teal-500/5'
              }`}>
                <div className="flex justify-between items-center">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-sm text-[var(--ff-text-tertiary)]">Box 20</span>
                      <span className="text-lg font-bold text-[var(--ff-text-primary)]">
                        VAT {report.netVAT > 0 ? 'PAYABLE' : 'REFUNDABLE'}
                      </span>
                    </div>
                    <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                      Box 13 ({formatCurrency(report.totalOutputTax)}) minus Box 19 ({formatCurrency(report.totalInputTax)})
                    </p>
                  </div>
                  <span className={`text-3xl font-bold font-mono ${
                    report.netVAT > 0 ? 'text-red-400' : 'text-teal-400'
                  }`}>
                    {formatCurrency(Math.abs(report.netVAT))}
                  </span>
                </div>
              </div>

              {/* Activity breakdown */}
              {(outputWithActivity.length > 0 || inputWithActivity.length > 0) && (
                <div className="text-xs text-[var(--ff-text-tertiary)] px-1">
                  Active boxes: {outputWithActivity.map(b => `${b.box}`).join(', ')}
                  {outputWithActivity.length > 0 && inputWithActivity.length > 0 && ' | '}
                  {inputWithActivity.map(b => `${b.box}`).join(', ')}
                </div>
              )}
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Budget vs Actual Report
 * Sage equivalent: Reports > Budget vs Actual
 * Compare budgeted amounts per GL account against actual GL balances
 */

import React, { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { AccountDrillDown } from '@/components/accounting/AccountDrillDown';
import { BarChart3, Loader2, AlertCircle, Download, ChevronDown, ChevronRight } from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface BudgetLine {
  account_code: string;
  account_name: string;
  account_type: string;
  budget_amount: number;
  actual_amount: number;
  variance: number;
  variance_pct: number;
}

interface BudgetReport {
  period: string;
  lines: BudgetLine[];
  total_budget: number;
  total_actual: number;
  total_variance: number;
}

function getDrillDownDates(period: string): { start: string; end: string } {
  const now = new Date();
  const year = now.getFullYear();
  const todayStr = now.toISOString().split('T')[0] ?? `${year}-01-01`;
  if (period === 'ytd') return { start: `${year}-01-01`, end: todayStr };
  if (period === 'full_year') return { start: `${year}-01-01`, end: `${year}-12-31` };
  // current period = current month
  const monthStart = new Date(year, now.getMonth(), 1);
  const monthStartStr = monthStart.toISOString().split('T')[0] ?? `${year}-01-01`;
  return { start: monthStartStr, end: todayStr };
}

export default function BudgetVsActualPage() {
  const [report, setReport] = useState<BudgetReport | null>(null);
  const [fiscalPeriod, setFiscalPeriod] = useState('current');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [expandedAccount, setExpandedAccount] = useState<string | null>(null);

  const drillDates = getDrillDownDates(fiscalPeriod);

  const loadReport = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ period: fiscalPeriod });
      const res = await apiFetch(`/api/accounting/reports-budget-vs-actual?${params}`);
      const json = await res.json();
      const data = json.data || json;
      setReport(data.report || data);
    } catch {
      setError('Failed to load budget report');
    } finally {
      setIsLoading(false);
    }
  }, [fiscalPeriod]);

  useEffect(() => { loadReport(); }, [loadReport]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-violet-500/10">
                  <BarChart3 className="h-6 w-6 text-violet-500" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Budget vs Actual</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    Compare budgeted and actual amounts by GL account
                  </p>
                </div>
              </div>
              <button onClick={() => {
                const params = new URLSearchParams({ period: fiscalPeriod });
                window.open(`/api/accounting/budget-vs-actual-export?${params}`, '_blank');
              }} disabled={!report || !report.lines || report.lines.length === 0}
                className="px-4 py-2 bg-violet-600 hover:bg-violet-700 text-white rounded-lg flex items-center gap-2 text-sm font-medium disabled:opacity-50">
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          <div className="flex items-center gap-4 mb-6">
            <select
              value={fiscalPeriod}
              onChange={(e) => setFiscalPeriod(e.target.value)}
              className="px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
            >
              <option value="current">Current Period</option>
              <option value="ytd">Year to Date</option>
              <option value="full_year">Full Year</option>
            </select>
          </div>

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-violet-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : !report || !report.lines || report.lines.length === 0 ? (
            <div className="text-center py-12">
              <BarChart3 className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No budget data available</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Set budgets per GL account to see variance analysis
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)]">
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Account</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Name</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Budget</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actual</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Variance</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">%</th>
                    <th className="py-3 px-4 text-[var(--ff-text-secondary)] font-medium w-32">Bar</th>
                  </tr>
                </thead>
                <tbody>
                  {report.lines.map((line) => {
                    const pct = line.budget_amount > 0 ? (line.actual_amount / line.budget_amount) * 100 : 0;
                    return (
                      <React.Fragment key={line.account_code}>
                        <tr
                          onClick={() => setExpandedAccount(expandedAccount === line.account_code ? null : line.account_code)}
                          className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] cursor-pointer"
                        >
                          <td className="py-3 px-4 font-mono text-[var(--ff-text-tertiary)]">
                            <span className="flex items-center gap-1">
                              {expandedAccount === line.account_code
                                ? <ChevronDown className="h-3 w-3" />
                                : <ChevronRight className="h-3 w-3" />}
                              {line.account_code}
                            </span>
                          </td>
                          <td className="py-3 px-4 text-[var(--ff-text-primary)]">{line.account_name}</td>
                          <td className="py-3 px-4 text-right text-[var(--ff-text-secondary)]">{formatCurrency(line.budget_amount)}</td>
                          <td className="py-3 px-4 text-right text-[var(--ff-text-primary)]">{formatCurrency(line.actual_amount)}</td>
                          <td className={`py-3 px-4 text-right font-medium ${line.variance >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                            {formatCurrency(line.variance)}
                          </td>
                          <td className={`py-3 px-4 text-right text-xs ${line.variance_pct >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                            {line.variance_pct.toFixed(1)}%
                          </td>
                          <td className="py-3 px-4">
                            <div className="w-full h-2 bg-[var(--ff-bg-tertiary)] rounded-full overflow-hidden">
                              <div
                                className={`h-full rounded-full ${pct > 100 ? 'bg-red-500' : pct > 80 ? 'bg-amber-500' : 'bg-teal-500'}`}
                                style={{ width: `${Math.min(pct, 100)}%` }}
                              />
                            </div>
                          </td>
                        </tr>
                        {expandedAccount === line.account_code && (
                          <AccountDrillDown
                            accountCode={line.account_code}
                            periodStart={drillDates.start}
                            periodEnd={drillDates.end}
                            asTableRow
                            colSpan={7}
                          />
                        )}
                      </React.Fragment>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-[var(--ff-border-light)] font-bold">
                    <td colSpan={2} className="py-3 px-4 text-[var(--ff-text-primary)]">Total</td>
                    <td className="py-3 px-4 text-right text-[var(--ff-text-primary)]">{formatCurrency(report.total_budget)}</td>
                    <td className="py-3 px-4 text-right text-[var(--ff-text-primary)]">{formatCurrency(report.total_actual)}</td>
                    <td className={`py-3 px-4 text-right ${report.total_variance >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                      {formatCurrency(report.total_variance)}
                    </td>
                    <td colSpan={2}></td>
                  </tr>
                </tfoot>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * General Ledger Report — All accounts' transactions for a period
 * Shows every GL account with its debit/credit entries and running balance
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, BookOpen, Loader2, AlertCircle, Download, ChevronDown, ChevronRight } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface GLAccount {
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
}

interface AccountReport {
  accountCode: string;
  accountName: string;
  accountType: string;
  openingBalance: number;
  closingBalance: number;
  totalDebit: number;
  totalCredit: number;
  transactions: {
    date: string;
    entryNumber: string;
    description: string;
    debit: number;
    credit: number;
    balance: number;
    source: string;
  }[];
}

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

function getDefaultDates() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  return { periodStart: start.toISOString().split('T')[0], periodEnd: now.toISOString().split('T')[0] };
}

export default function GeneralLedgerPage() {
  const defaults = getDefaultDates();
  const [periodStart, setPeriodStart] = useState(defaults.periodStart);
  const [periodEnd, setPeriodEnd] = useState(defaults.periodEnd);
  const [accounts, setAccounts] = useState<GLAccount[]>([]);
  const [reports, setReports] = useState<AccountReport[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  useEffect(() => {
    apiFetch('/api/accounting/chart-of-accounts', { credentials: 'include' })
      .then(r => r.json())
      .then(res => {
        const d = res.data || res;
        const list = Array.isArray(d) ? d : d.accounts || d.items || [];
        setAccounts(
          list
            .filter((a: GLAccount & { level?: number }) => !a.level || a.level >= 3)
            .map((a: Record<string, unknown>) => ({
              id: String(a.id),
              accountCode: String(a.accountCode || a.account_code || ''),
              accountName: String(a.accountName || a.account_name || ''),
              accountType: String(a.accountType || a.account_type || ''),
            }))
        );
      })
      .catch(() => { /* reference data load failure — non-critical, filter will show no accounts */ });
  }, []);

  const load = useCallback(async () => {
    if (!periodStart || !periodEnd || accounts.length === 0) return;
    setLoading(true);
    setError('');
    try {
      const results: AccountReport[] = [];
      const top20 = accounts.slice(0, 20);
      await Promise.all(
        top20.map(async (acct) => {
          try {
            const params = new URLSearchParams({
              account_code: acct.accountCode,
              period_start: periodStart,
              period_end: periodEnd,
            });
            const res = await apiFetch(`/api/accounting/reports-account-transactions?${params}`, { credentials: 'include' });
            if (!res.ok) return;
            const json = await res.json();
            const data = json.data;
            if (data && (data.transactions?.length > 0 || data.openingBalance !== 0)) {
              results.push({
                accountCode: data.accountCode || acct.accountCode,
                accountName: data.accountName || acct.accountName,
                accountType: data.accountType || acct.accountType,
                openingBalance: Number(data.openingBalance || 0),
                closingBalance: Number(data.closingBalance || 0),
                totalDebit: (data.transactions || []).reduce((s: number, t: { debit: number }) => s + Number(t.debit || 0), 0),
                totalCredit: (data.transactions || []).reduce((s: number, t: { credit: number }) => s + Number(t.credit || 0), 0),
                transactions: data.transactions || [],
              });
            }
          } catch { /* skip failed accounts */ }
        })
      );
      results.sort((a, b) => a.accountCode.localeCompare(b.accountCode));
      setReports(results);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, [periodStart, periodEnd, accounts]);

  useEffect(() => {
    if (accounts.length > 0) load();
  }, [accounts, load]);

  const toggleExpand = (code: string) => {
    setExpanded(prev => {
      const next = new Set(prev);
      next.has(code) ? next.delete(code) : next.add(code);
      return next;
    });
  };

  const grandTotalDebit = reports.reduce((s, r) => s + r.totalDebit, 0);
  const grandTotalCredit = reports.reduce((s, r) => s + r.totalCredit, 0);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link
            href="/accounting"
            className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2"
          >
            <ArrowLeft className="h-4 w-4" /> Back to Accounting
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <BookOpen className="h-6 w-6 text-violet-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">General Ledger</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  All account transactions for period
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <input type="date" value={periodStart} onChange={e => setPeriodStart(e.target.value)} className="ff-input text-sm" />
              <span className="text-[var(--ff-text-tertiary)]">to</span>
              <input type="date" value={periodEnd} onChange={e => setPeriodEnd(e.target.value)} className="ff-input text-sm" />
              <button
                onClick={() => {
                  const params = new URLSearchParams({ period_start: periodStart ?? '', period_end: periodEnd ?? '' });
                  window.open(`/api/accounting/audit-trail-export?${params}`, '_blank');
                }}
                disabled={reports.length === 0}
                className="inline-flex items-center gap-2 px-4 py-2 bg-violet-600 text-white rounded-lg text-sm font-medium disabled:opacity-50 hover:bg-violet-700"
              >
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-violet-500" />
            </div>
          ) : reports.length === 0 ? (
            <div className="text-center py-12 text-[var(--ff-text-secondary)]">
              No account activity for the selected period
            </div>
          ) : (
            <div className="space-y-3">
              {reports.map(r => {
                const isOpen = expanded.has(r.accountCode);
                return (
                  <div
                    key={r.accountCode}
                    className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden"
                  >
                    <button
                      onClick={() => toggleExpand(r.accountCode)}
                      className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--ff-bg-tertiary)] transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        {isOpen ? (
                          <ChevronDown className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                        )}
                        <span className="font-mono text-sm text-violet-400">{r.accountCode}</span>
                        <span className="text-sm text-[var(--ff-text-primary)]">{r.accountName}</span>
                        <span className="text-xs px-2 py-0.5 rounded bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]">
                          {r.accountType}
                        </span>
                      </div>
                      <div className="flex items-center gap-6 text-sm font-mono">
                        <span className="text-[var(--ff-text-secondary)]">
                          Dr {fmt(r.totalDebit)}
                        </span>
                        <span className="text-[var(--ff-text-secondary)]">
                          Cr {fmt(r.totalCredit)}
                        </span>
                        <span className="text-[var(--ff-text-primary)] font-bold">
                          {fmt(r.closingBalance)}
                        </span>
                      </div>
                    </button>

                    {isOpen && r.transactions.length > 0 && (
                      <table className="w-full text-sm border-t border-[var(--ff-border-light)]">
                        <thead>
                          <tr className="bg-[var(--ff-bg-tertiary)]">
                            <th className="px-4 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Date</th>
                            <th className="px-4 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Entry #</th>
                            <th className="px-4 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Description</th>
                            <th className="px-4 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Debit</th>
                            <th className="px-4 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Credit</th>
                            <th className="px-4 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Balance</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-[var(--ff-border-light)]">
                          <tr className="text-xs text-[var(--ff-text-tertiary)]">
                            <td className="px-4 py-2" colSpan={5}>Opening Balance</td>
                            <td className="px-4 py-2 text-right font-mono">{fmt(r.openingBalance)}</td>
                          </tr>
                          {r.transactions.map((t, i) => (
                            <tr key={i} className="hover:bg-[var(--ff-bg-tertiary)]">
                              <td className="px-4 py-2 text-[var(--ff-text-primary)]">{t.date?.split('T')[0]}</td>
                              <td className="px-4 py-2 font-mono text-[var(--ff-text-secondary)]">{t.entryNumber}</td>
                              <td className="px-4 py-2 text-[var(--ff-text-primary)]">{t.description}</td>
                              <td className="px-4 py-2 text-right font-mono">{t.debit > 0 ? fmt(t.debit) : ''}</td>
                              <td className="px-4 py-2 text-right font-mono">{t.credit > 0 ? fmt(t.credit) : ''}</td>
                              <td className="px-4 py-2 text-right font-mono text-[var(--ff-text-primary)]">{fmt(t.balance)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                );
              })}

              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border-2 border-[var(--ff-border-medium)] px-4 py-3 flex items-center justify-between font-bold text-sm">
                <span className="text-[var(--ff-text-primary)]">GRAND TOTALS ({reports.length} accounts)</span>
                <div className="flex items-center gap-6 font-mono">
                  <span>Dr {fmt(grandTotalDebit)}</span>
                  <span>Cr {fmt(grandTotalCredit)}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Project Profitability Report Page
 * PRD-060 Phase 5: Revenue vs costs per project
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, TrendingUp, Loader2, AlertCircle } from 'lucide-react';
import type { ProjectProfitabilityReport } from '@/modules/accounting/types/gl.types';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

function getDefaultDates() {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 1);
  return {
    periodStart: start.toISOString().split('T')[0],
    periodEnd: now.toISOString().split('T')[0],
  };
}

export default function ProjectProfitabilityPage() {
  const defaults = getDefaultDates();
  const [periodStart, setPeriodStart] = useState(defaults.periodStart);
  const [periodEnd, setPeriodEnd] = useState(defaults.periodEnd);
  const [reports, setReports] = useState<ProjectProfitabilityReport[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [expanded, setExpanded] = useState<string | null>(null);

  const loadReport = useCallback(async () => {
    if (!periodStart || !periodEnd) return;
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
      const res = await apiFetch(`/api/accounting/reports-project-profitability?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load');
      const data = json.data || json;
      setReports(Array.isArray(data) ? data : []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load profitability');
    } finally {
      setIsLoading(false);
    }
