/**
 * Management Pack Report API
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { buildManagementPack } from '@/modules/accounting/services/reportingEngineService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  const companyId = (req as any).companyId as string;
  const period = String(req.query.period || new Date().toISOString().slice(0, 7));

  const companies = await sql`SELECT name FROM companies WHERE id = ${companyId}::UUID LIMIT 1` as Row[];
  const companyName = String(companies[0]?.name || 'Company');

  const pack = buildManagementPack({
    companyName,
    period,
    revenue: 0, expenses: 0, netProfit: 0,
    cashBalance: 0, arOutstanding: 0, apOutstanding: 0,
  });

  return apiResponse.success(res, pack);
}
export default withCompany(withErrorHandler(handler as any));

/**
 * Consolidated Reports API
 * GET — consolidated trial balance, income statement, balance sheet, dashboard
 * POST — elimination adjustments
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  getConsolidatedTrialBalance,
  getConsolidatedIncomeStatement,
  getConsolidatedBalanceSheet,
  getGroupDashboardStats,
  getEliminationAdjustments,
  createEliminationAdjustment,
  postEliminationAdjustment,
  reverseEliminationAdjustment,
  autoGenerateEliminations,
} from '@/modules/accounting/services/consolidatedReportingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;
  const groupId = req.query.group_id as string;

  if (req.method === 'GET') {
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');

    if (action === 'trial-balance') {
      const periodStart = req.query.period_start as string;
      const periodEnd = req.query.period_end as string;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'period_start and period_end required');
      const report = await getConsolidatedTrialBalance(groupId, periodStart, periodEnd);
      return apiResponse.success(res, report);
    }

    if (action === 'income-statement') {
      const periodStart = req.query.period_start as string;
      const periodEnd = req.query.period_end as string;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'period_start and period_end required');
      const report = await getConsolidatedIncomeStatement(groupId, periodStart, periodEnd);
      return apiResponse.success(res, report);
    }

    if (action === 'balance-sheet') {
      const asAtDate = req.query.as_at_date as string;
      if (!asAtDate) return apiResponse.badRequest(res, 'as_at_date required');
      const report = await getConsolidatedBalanceSheet(groupId, asAtDate);
      return apiResponse.success(res, report);
    }

    if (action === 'dashboard') {
      const stats = await getGroupDashboardStats(groupId);
      return apiResponse.success(res, stats);
    }

    if (action === 'eliminations') {
      const periodStart = req.query.period_start as string | undefined;
      const periodEnd = req.query.period_end as string | undefined;
      const adjustments = await getEliminationAdjustments(groupId, periodStart, periodEnd);
      return apiResponse.success(res, { items: adjustments });
    }

    return apiResponse.badRequest(res, 'action required: trial-balance, income-statement, balance-sheet, dashboard, eliminations');
  }

  if (req.method === 'POST') {
    if (!groupId && !req.body.groupId) return apiResponse.badRequest(res, 'groupId required');
    const gId = groupId || req.body.groupId;

    if (action === 'create-elimination') {
      const { adjustmentType, description, periodStart, periodEnd, lines } = req.body;
      if (!adjustmentType || !lines?.length) {
        return apiResponse.badRequest(res, 'adjustmentType and lines required');
      }
      const adj = await createEliminationAdjustment(gId, {
        adjustmentType, description, periodStart, periodEnd, lines,
      });

/**
 * Item Valuation Report
 * Sage Parity: Items > Reports > Item Valuation
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { DollarSign, Loader2, Download } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Row { id: string; itemCode: string; name: string; category: string; uom: string; qtyOnHand: number; costPrice: number; stockValue: number; }

export default function ItemValuationReport() {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    const res = await apiFetch('/api/accounting/reports/item-valuation', { credentials: 'include' });
    const json = await res.json();
    setRows(json.data || []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const totalValue = rows.reduce((s, r) => s + r.stockValue, 0);

  // Group by category for summary
  const byCategory = rows.reduce<Record<string, number>>((acc, r) => {
    acc[r.category] = (acc[r.category] || 0) + r.stockValue;
    return acc;
  }, {});

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-500/10"><DollarSign className="h-6 w-6 text-amber-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Item Valuation</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Current stock value by item</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right">
                <p className="text-xs text-[var(--ff-text-tertiary)]">Total Stock Value</p>
                <p className="text-xl font-bold text-amber-400 font-mono">{fmt(totalValue)}</p>
              </div>
              <button onClick={() => window.open('/api/accounting/reports/item-valuation?format=csv', '_blank')}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 hover:bg-blue-500 text-white rounded-lg">
                <Download className="h-4 w-4" /> CSV
              </button>
            </div>
          </div>
        </div>
        <div className="p-6 space-y-4">
          {/* Category summary */}
          {!loading && Object.keys(byCategory).length > 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {Object.entries(byCategory).sort((a, b) => b[1] - a[1]).map(([cat, val]) => (
                <div key={cat} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-3">
                  <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{cat}</p>
                  <p className="text-sm font-bold text-[var(--ff-text-primary)] font-mono">{fmt(val)}</p>
                </div>
              ))}
            </div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
            ) : rows.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No items with stock value</div>
            ) : (
              <table className="w-full text-sm">
                <thead><tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Code</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Item</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Category</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">UOM</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Qty</th>
