/**
 * TDD: Ratio Trend Analysis
 * RED phase — tests for multi-period ratio tracking.
 */

import { describe, it, expect } from 'vitest';
import {
  calculateRatioTrends,
  type RatioTrendResult,
} from '@/modules/accounting/services/ratioTrendService';
import type { FinancialData } from '@/modules/accounting/services/reportingEngineService';

const makeData = (revenue: number, netProfit: number, cash: number): FinancialData => ({
  revenue,
  costOfSales: revenue * 0.6,
  operatingExpenses: revenue * 0.15,
  netProfit,
  totalAssets: revenue * 2,
  totalLiabilities: revenue * 0.8,
  totalEquity: revenue * 1.2,
  currentAssets: revenue * 0.5,
  currentLiabilities: revenue * 0.3,
  inventory: revenue * 0.1,
  accountsReceivable: revenue * 0.2,
  accountsPayable: revenue * 0.15,
  cash,
});

describe('Ratio Trend Calculator', () => {
  const periods: FinancialData[] = [
    makeData(800000, 120000, 100000),   // Jan
    makeData(900000, 150000, 120000),   // Feb
    makeData(1000000, 200000, 150000),  // Mar
    makeData(1100000, 220000, 170000),  // Apr
    makeData(1050000, 190000, 160000),  // May
    makeData(1200000, 260000, 200000),  // Jun
  ];
  const labels = ['Jan 2026', 'Feb 2026', 'Mar 2026', 'Apr 2026', 'May 2026', 'Jun 2026'];

  it('computes ratios for multiple periods and returns array', () => {
    const trends = calculateRatioTrends(periods, labels);
    expect(Array.isArray(trends)).toBe(true);
    expect(trends.length).toBeGreaterThan(0);
    // Each trend should have values for all 6 periods
    const revenueGrowth = trends.find(t => t.ratioName === 'grossProfitMargin');
    expect(revenueGrowth).toBeDefined();
    expect(revenueGrowth!.values.length).toBe(6);
  });

  it('calculates period-over-period change for each ratio', () => {
    const trends = calculateRatioTrends(periods, labels);
    const gpm = trends.find(t => t.ratioName === 'grossProfitMargin')!;
    // Each value should have a period label and numeric value
    gpm.values.forEach(v => {
      expect(v.period).toBeDefined();
      expect(typeof v.value).toBe('number');
    });
    // Change % should be defined
    expect(typeof gpm.changePercent).toBe('number');
  });

  it('flags improving/declining trends based on ratio type', () => {
    const trends = calculateRatioTrends(periods, labels);
    const gpm = trends.find(t => t.ratioName === 'grossProfitMargin')!;
    // Gross profit margin is constant at 40% (revenue*0.6 COGS ratio), so stable
    expect(['improving', 'declining', 'stable']).toContain(gpm.trend);
  });

  it('handles missing periods with null values', () => {
    const sparseData = [periods[0]!, periods[2]!, periods[5]!];
    const sparseLabels = ['Jan 2026', 'Mar 2026', 'Jun 2026'];
    const trends = calculateRatioTrends(sparseData, sparseLabels);
    expect(trends.length).toBeGreaterThan(0);
    expect(trends[0]!.values.length).toBe(3);
  });

  it('supports 3, 6, and 12 month lookback windows', () => {
    // 3 months
    const t3 = calculateRatioTrends(periods.slice(0, 3), labels.slice(0, 3));
    expect(t3[0]!.values.length).toBe(3);

    // 6 months
    const t6 = calculateRatioTrends(periods, labels);
    expect(t6[0]!.values.length).toBe(6);
  });

  it('includes key ratio names in output', () => {
    const trends = calculateRatioTrends(periods, labels);
    const names = trends.map(t => t.ratioName);
    expect(names).toContain('grossProfitMargin');
    expect(names).toContain('currentRatio');
    expect(names).toContain('debtorDays');
    expect(names).toContain('returnOnEquity');
  });
});

