import { describe, it, expect } from 'vitest';
import {
  buildKPIScorecard,
  type KPITargetConfig,
  type KPIScorecardItem,
} from '@/modules/accounting/services/kpiScorecardService';
import type { ExtendedRatioResult } from '@/modules/accounting/services/reportingEngineService';

// Sample ratios representing a healthy company
const sampleRatios: ExtendedRatioResult = {
  // Original 11
  grossProfitMargin: 40,
  netProfitMargin: 20,
  operatingProfitMargin: 20,
  currentRatio: 1.67,
  quickRatio: 1.33,
  debtToEquity: 0.67,
  returnOnAssets: 10,
  returnOnEquity: 16.67,
  debtorDays: 73,
  creditorDays: 91,
  inventoryTurnover: 6,
  // Extended
  ebitda: 260000,
  ebitdaMargin: 26,
  roce: 11.76,
  interestCoverage: 6.67,
  debtRatio: 0.40,
  equityMultiplier: 1.67,
  cashRatio: 0.50,
  workingCapital: 200000,
  operatingCashFlowRatio: 0.83,
  assetTurnover: 0.50,
  receivablesTurnover: 5.00,
  payablesTurnover: 4.00,
  inventoryDays: 60.83,
  cashConversionCycle: 42.58,
  freeCashFlow: 170000,
  revenuePerEmployee: 100000,
  dupontMargin: 20,
  dupontTurnover: 0.50,
  dupontLeverage: 1.67,
};

const targets: KPITargetConfig[] = [
  { ratioKey: 'grossProfitMargin', target: 35, warningThreshold: 30, criticalThreshold: 25, lowerIsBetter: false },
  { ratioKey: 'currentRatio', target: 1.5, warningThreshold: 1.2, criticalThreshold: 1.0, lowerIsBetter: false },
  { ratioKey: 'debtToEquity', target: 0.5, warningThreshold: 0.8, criticalThreshold: 1.0, lowerIsBetter: true },
  { ratioKey: 'debtorDays', target: 60, warningThreshold: 75, criticalThreshold: 90, lowerIsBetter: true },
  { ratioKey: 'netProfitMargin', target: 15, warningThreshold: 10, criticalThreshold: 5, lowerIsBetter: false },
];

describe('KPI Scorecard Engine', () => {
  it('assigns green status when value meets target', () => {
    const scorecard = buildKPIScorecard(sampleRatios, targets);
    const gpm = scorecard.find(s => s.ratioKey === 'grossProfitMargin')!;
    // GPM is 40%, target is 35% → green
    expect(gpm.status).toBe('green');
  });

  it('assigns amber status when within warning threshold', () => {
    const weakRatios = { ...sampleRatios, grossProfitMargin: 32 };
    const scorecard = buildKPIScorecard(weakRatios, targets);
    const gpm = scorecard.find(s => s.ratioKey === 'grossProfitMargin')!;
    // GPM 32% is between warning (30) and target (35) → amber
    expect(gpm.status).toBe('amber');
  });

  it('assigns red status when outside acceptable range', () => {
    const badRatios = { ...sampleRatios, grossProfitMargin: 22 };
    const scorecard = buildKPIScorecard(badRatios, targets);
    const gpm = scorecard.find(s => s.ratioKey === 'grossProfitMargin')!;
    // GPM 22% is below critical (25) → red
    expect(gpm.status).toBe('red');
  });

  it('inverts thresholds for expense-type KPIs (lower is better)', () => {
    // debtToEquity: actual 0.67, target 0.5, warning 0.8, critical 1.0
    // 0.67 is above target (0.5) but below warning (0.8) → amber
    const scorecard = buildKPIScorecard(sampleRatios, targets);
    const de = scorecard.find(s => s.ratioKey === 'debtToEquity')!;
    expect(de.status).toBe('amber');

    // Test with good value (below target)
    const goodRatios = { ...sampleRatios, debtToEquity: 0.40 };
    const sc2 = buildKPIScorecard(goodRatios, targets);
    expect(sc2.find(s => s.ratioKey === 'debtToEquity')!.status).toBe('green');

    // Test with bad value (above critical)
    const badRatios = { ...sampleRatios, debtToEquity: 1.2 };
    const sc3 = buildKPIScorecard(badRatios, targets);
    expect(sc3.find(s => s.ratioKey === 'debtToEquity')!.status).toBe('red');
  });

  it('calculates percentage of target achieved', () => {
    const scorecard = buildKPIScorecard(sampleRatios, targets);
    const gpm = scorecard.find(s => s.ratioKey === 'grossProfitMargin')!;
    // 40 / 35 * 100 = 114.29%
    expect(gpm.percentOfTarget).toBeCloseTo(114.29, 0);
  });

  it('builds scorecard from ratio result + target config', () => {
    const scorecard = buildKPIScorecard(sampleRatios, targets);
    expect(scorecard.length).toBe(targets.length);
    scorecard.forEach(item => {
      expect(item.ratioKey).toBeDefined();
      expect(item.name).toBeDefined();
      expect(typeof item.value).toBe('number');
      expect(typeof item.target).toBe('number');
